L["disabled."] = "desativado."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "ninguém está na sua lista de nunca oferecer. Use Shift + clique direito no lembrete para pôr nela quem ele estiver mostrando."
L["never offered anything unless they buff you: %s"] = "nunca recebem ofertas, a menos que deem bônus a você: %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "diga quem: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lista todos que estão na lista."
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r pode receber ofertas de novo."
L["nobody called %s is on your never-offer list."] = "ninguém chamado %s está na sua lista de nunca oferecer."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "a soneca aceita um número de minutos de 1 a %d, ou off -- por exemplo, |cffffd100/manners snooze 15|r ou |cffffd100/manners snooze 1h|r."
L["your settings are in the box under |cffffd100Share as text|r on the Profiles tab of the options -- click in it, select all and copy."] = "suas configurações estão na caixa em |cffffd100Compartilhar como texto|r, na aba Perfis das opções -- clique nela, selecione tudo e copie."
L["this string is too long to be imported back -- a very long phrase box under What I say is the usual cause. Shorten it if you want to share these settings."] = "este texto é longo demais para ser importado de volta -- a causa mais comum é uma caixa de frases muito longa na aba O que eu digo. Encurte-a se quiser compartilhar estas configurações."
L["paste the settings string into the box under |cffffd100Share as text|r on the Profiles tab, or type |cffffd100/manners import|r followed by it."] = "cole o texto de configurações na caixa em |cffffd100Compartilhar como texto|r, na aba Perfis, ou digite |cffffd100/manners import|r seguido dele."
L["type |cffffd100/manners import|r followed by a settings string."] = "digite |cffffd100/manners import|r seguido de um texto de configurações."
