L["your own buff: offered to you when you are missing it."] = "seu próprio bônus: oferecido a você quando você está sem ele."
L["your own buff: nothing you cast goes on yourself alone."] = "seu próprio bônus: nada do que você lança é só para você."
L["|cffff8080own buffs: last scan not believed (%s)|r -- %d read, baseline %d"] = "|cffff8080seus bônus: última varredura descartada (%s)|r -- %d lidos, linha de base %d"
L["|cffffd100own buffs: baseline not settled|r -- %d read, waiting for a second scan to agree"] = "|cffffd100seus bônus: linha de base não definida|r -- %d lidos, aguardando uma segunda varredura confirmar"
L["own buffs: %d read, baseline %d"] = "seus bônus: %d lidos, linha de base %d"
L["%d changes to your auras this session, read in %d walks"] = "%d mudanças nas suas auras nesta sessão, lidas em %d passagens"
L["thank with an emote: |cff00ff00on|r"] = "agradecer com um emote: |cff00ff00ativado|r"
L["thank with an emote: |cffff0000off|r"] = "agradecer com um emote: |cffff0000desativado|r"
L["last thanked: |cffffffff%s|r, %ds ago (the game answered %s)"] = "último agradecimento: |cffffffff%s|r, há %ds (o jogo respondeu %s)"
L["last not thanked: |cffffffff%s|r, %ds ago (%s)"] = "último agradecimento pulado: |cffffffff%s|r, há %ds (%s)"
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "DESATIVADO neste perfil -- nada é anotado nem oferecido; /manners on"
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "lembrete DESTRAVADO -- ele não dá bônus a ninguém até você usar /manners lock"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100em soneca até %s|r -- nenhum lembrete até lá; /manners snooze off encerra a soneca"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100montado|r -- a opção Não quando montado mantém o lembrete escondido até você desmontar"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100poupando mana|r -- até você voltar a %d%% de mana, só aparecem no lembrete seu próprio bônus e quem deu bônus a você ou pediu"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100poupando mana|r -- até você voltar a %d%% de mana, só quem deu bônus a você ou pediu recebe a oferta"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100verificação de prontidão|r -- seu grupo ou raide vem primeiro até o combate começar"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100grupos da raide|r -- numa raide, só os grupos %s recebem a oferta sem pedir"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100grupos da raide|r -- todos os grupos estão desmarcados, então numa raide ninguém recebe a oferta sem pedir"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try está armado:|r %s -- remova com um /manners try sem nada"
L["queue now: %d"] = "fila agora: %d"
L["queue if switched on: %d"] = "fila se ativado: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "não existe |cffffd100/manners %s|r -- você quis dizer |cffffd100/manners %s|r? |cffffd100/manners help|r lista todos."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "não existe |cffffd100/manners %s|r -- você quis dizer |cffffd100/manners %s|r? |cffffd100/manners dev|r lista as ferramentas de teste."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "Brigadão, {name}! A primeira rodada é minha quando voltarmos pra forja."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "Valeu demais, {name}. Agora cê tem amigos na montanha."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "Valeu, {name}! Eu ia me virar sem isso, viu? Mas valeu."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "Brigadão, {name}! Te daria um abraço, mas depois cê ia precisar de curador."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "Já tá pago, {name}. Bem mais rápido que o meu fiado na taverna."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "Lá na taverna isso vai virar 'salvou minha vida', {name}. Valeu!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "Beleza, {name}! Te esculpiria uma estátua, mas assim é mais rápido."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "Os Titãs nos fizeram de pedra, {name}, e mesmo assim essa me amoleceu. Valeu."
L["Thank ye, {name}. Back at ye, before me pride notices I needed it."] = "Valeu, {name}. Tá devolvido, antes que meu orgulho note que eu precisava."
L["Thank ye, {name}. Muradin says a debt left unpaid rusts. Here, before it does."] = "Valeu, {name}. Muradin diz que dívida parada enferruja. Toma, antes disso."
L["Thank ye, {name}. I'd give ye a ride on me ram, but he bites strangers. And me."] = "Valeu, {name}. Te dava carona no meu carneiro, mas ele morde estranho. E a mim."
L["The Explorers' League'll ask where ye dug up such manners, {name}. Thanks!"] = "A Liga dos Exploradores vai perguntar onde cê desenterrou esses modos, {name}. Valeu!"
L["Thank ye, {name}. Me beard's on end. That's dwarven fer 'deeply touched'."] = "Valeu, {name}. Minha barba arrepiou. Em anão, isso quer dizer 'tocou fundo'."
L["Mined half o' Khaz Modan, {name}. Never struck a vein that rich. Yer cut."] = "Minerei meia Khaz Modan, {name}, e nunca topei com veio tão rico. Sua parte, uai."
L["Like a Kharanos hearth in a Dun Morogh blizzard, that, {name}. Thank ye."] = "Isso foi lareira de Kharanos em nevasca de Dun Morogh, {name}. Valeu."
L["Came back to ye like a Wildhammer's stormhammer, {name}. Less painful, mind."] = "Voltou pra cê feito martelo de um Martelo Feroz, {name}. Doendo menos, viu?"
L["Come to Ironforge, {name}. Me mam'll feed ye till ye can't stand. Thank ye!"] = "Aparece em Altaforja, {name}. Minha mãe te entope até cê não parar em pé. Valeu!"
L["Checked it fer gunpowder out o' habit, {name}. Clean as a whistle. Here's yers!"] = "Conferi se tinha pólvora, mania de anão, {name}. Limpinho. Toma o seu!"
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "Opa, {name}, era só pedir. Agora não se mexe, que nem bigorna boa."
L["Say no more, {name}. Stone and steel, here it comes."] = "Nem precisa falar, {name}. Pedra e aço, lá vai!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "Pede ajuda a um anão, {name}, e cê ganha. Aos berros."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "Certo, {name}. Segura firme: eu faço tudo como quem desce o martelo."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "Opa, {name}, e de brinde uma história que cê nem pediu. Por onde começo..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{buff} na pressão, {name}, igual chope bem tirado."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "Pronto, {name}. Obra de anão: forte demais, barata demais e garantida."
L["Easy, {name}. Last favour I did was fix a gnome's tank. Cost me both eyebrows."] = "Moleza, {name}. Último favor que fiz: o tanque de um gnomo. Me custou as sobrancelhas."
L["Aye, {name}. Mountain kings never refuse. I'm more a foothill, but same rule."] = "Opa, {name}. Rei da Montanha não recusa. Sou mais um morrinho, mas a regra vale."
L["Tempered and quenched, {name}. Mind, it's still hot."] = "Forjado e temperado, {name}. Cuidado, que ainda tá quente."
L["Done afore ye finished, {name}. Dwarves hear 'please' through solid rock."] = "Pronto antes de cê acabar, {name}. Anão ouve 'por favor' até através da rocha."
L["Aye, {name}. In Dun Morogh ye help quick, or ye both freeze standin' there."] = "Bora, {name}. Em Dun Morogh se ajuda rápido, senão os dois viram picolé."
L["Aye, {name}. Ye'll feel it in yer boots first. That's how ye know it's dwarven."] = "Pode deixar, {name}. Primeiro cê sente nas botas. É assim que se reconhece obra de anão."
L["Aye, {name}. Say no, and ye'd ask a gnome, and then I'd feel responsible."] = "Claro, {name}. Se eu dissesse não, cê ia pedir pra um gnomo, e aí a culpa era minha."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "Toma, {name}, um trocinho pra te manter de pé. Baixinho, igual eu."
L["Off ye go, {name}, steady as the mountain."] = "Vai lá, {name}, firme feito a montanha."
L["Here, {name}. Ale's for after; this is for before."] = "Toma, {name}. A cerveja é pro depois; isso aqui é pro antes."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "O Magni virou diamante pela causa, {name}. Essa é a opção mais em conta."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "Tem anão cobrindo suas costas, {name}. Bom, seus joelhos. Dá quase na mesma."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "Se um trogg te encher, {name}, diz que foi um anão que mandou. Aí corre."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "Se o efeito passar, {name}, dá um tapão. É assim que a gente conserta tudo."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "Toma, {name}. Te daria teimosia também, mas tô usando toda a minha."
L["Mind the wendigos, {name}: big, hairy and grumpy. Like me, but hungrier."] = "Olho nos wendigos, {name}: grandes, peludos e ranzinzas. Tipo eu, com mais fome."
L["Take this, {name}. Me grandad fought three wars with a pickaxe and this."] = "Toma, {name}. Meu avô lutou três guerras com uma picareta e isto."
L["Dwarven make, {name}. Drop it off Thandol Span and it'd still work. Don't."] = "Fabricação anã, {name}. Cai da ponte de Thandol e segue funcionando. Não tenta."
L["Stonewrought Dam holds back all o' Loch Modan, {name}. This'll hold ye an hour."] = "A represa segura Loch Modan inteiro, {name}. Isto aqui te segura uma hora."
L["Won't keep yer boots dry in the Wetlands, {name}. Nothin' does. The rest, aye."] = "No Pantanal não deixa a bota seca, {name}. Nada deixa. O resto, garanto."
L["Old miner's rule, {name}: never go down a hole without a lamp, a mate and this."] = "Regra de mineiro, {name}: nunca desce num buraco sem lampião, um parceiro e isto, uai."
L["Brann Bronzebeard went explorin' with less, {name}, and wrote three books."] = "Brann Barbabronze explorou com menos, {name}, e escreveu três livros."
L["Mountaineers swear by it, {name}. Ye'll climb no better, but land softer."] = "Montanhista jura por isso, {name}. Não escala melhor, mas cai mais macio."
L["Ironforge's gates have never fallen, {name}. Neither should ye. Take this."] = "Os portões de Altaforja nunca caíram, {name}. Nem cê deve cair. Toma."
L["Me cousins down Blackrock way would've set it alight first, {name}. Fer luck."] = "Meus primos lá da Rocha Negra iam botar fogo nisso antes, {name}. Pra dar sorte."
L["Stone and hammer keep ye, cousin {name}!"] = "Pedra e martelo te guardem, parente {name}!"
L["Three Hammers, one round, cousin {name}!"] = "Três Martelos, uma rodada, parente {name}!"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "Aposto que o primo do seu primo casou com o meu, {name}. A montanha é pequena."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "Dois anões juntos, {name}. Coitado de quem ficar no caminho."
L["Bronzebeard, Wildhammer, Dark Iron, Earthen, {name}: one family, nobody agrees."] = "Barbabronze, Martelo Feroz, Ferro Negro, Terrano, {name}: uma família, ninguém concorda."
L["Between the pair of us, {name}, we could out-stubborn a mountain."] = "Nós dois juntos, {name}, ganhamos de uma montanha na teimosia."
L["Me grandmother'd climb out of her tomb if I did any less fer kin, {name}."] = "Minha avó saía do túmulo se eu fizesse menos que isso pelos meus, {name}."
L["The Titans carved us both from the same rock, {name}. Explains the headaches."] = "Os Titãs nos talharam da mesma pedra, {name}. Por isso a cabeça-dura."
L["Proud o' ye, {name}. Don't let it go to yer head; no room under the helmet."] = "Orgulho de você, {name}. Não deixa subir pra cabeça: não cabe no elmo."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "Fica atrás de mim, {name}. É, eu sei. Agacha um pouco."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "Combinado, {name}: eu vou na frente, cê pega o saque e depois a gente briga."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "Se eu começar a cantar, {name}, o combate foi bem. Ou muito mal."
L["Dwarves never leave a mate behind, {name}. Nor a keg. Mates first, mind."] = "Anão não deixa parceiro pra trás, {name}. Nem barril. Parceiro primeiro, viu?"
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "Barbas pra fora, {name}! Quem não tem barba caça com cara feia."
L["Knocked on the nearest rock, {name}. Solid. No cave-ins fer us today."] = "Bati três vezes na pedra, {name}. Firme. Hoje não desaba nada."
L["No fires near me pack, {name}. It's mostly gunpowder. And a sandwich."] = "Sem fogo perto da minha mochila, {name}. É quase só pólvora. E uma marmita."
L["Dwarves don't retreat, {name}. Our legs aren't built fer it. So forward it is."] = "Anão não recua, {name}. As pernas não foram feitas pra isso. Então, pra frente."
L["Stay close, {name}. If it goes dark, follow the cursin'. That'll be me."] = "Fica perto, {name}. Se escurecer, segue os palavrões. Esse aí sou eu."
L["Dwarves always know which way is down, {name}. Up's yer problem."] = "Anão sempre sabe pra que lado é pra baixo, {name}. Pra cima é com você."
L["Anythin' made o' stone, {name}, let me talk to it first. Might be a cousin."] = "Se for de pedra, {name}, eu falo primeiro. Pode ser parente."
L["If the ceilin' creaks, {name}, I'll tell ye. If I go quiet, run."] = "Se o teto ranger, {name}, eu aviso. Se eu me calar, corre."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "Bom dia, {name}! Cedo demais pra cerveja. Quase. Toma isso antes."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "De pé junto com a forja, {name}! Dia de anão começa com martelo e isto."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "Cedo, {name}? Que nada, uai. A mina tá aberta faz duas horas. Toma."
L["Mornin', {name}. Me beard's still asleep. The rest o' me is ready."] = "Bom dia, {name}. A barba ainda tá dormindo. O resto de mim já tá de pé."
L["Mornin', {name}. Porridge, a pipe and this. The other two are mine."] = "Bom dia, {name}. Mingau, cachimbo e isto. Os dois primeiros são meus."
L["The rams had me up at dawn, {name}. Headbutted the door till I came out. Here."] = "Os carneiros me tiraram da cama cedo, {name}. Cabeçada na porta até eu sair. Toma."
L["Mornin', {name}. Ears still ringin' from last night's singin'. Here."] = "Bom dia, {name}. O ouvido ainda zumbindo da cantoria de ontem. Toma."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "Agradeço, {name}. Deixe-me retribuir antes que um bardo conte tudo errado."
L["Kindly done, {name}. Let no one say we forget a friend."] = "Belo gesto, {name}. Ninguém dirá que esquecemos os amigos."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "Agradeço, {name}. Te daria um título, mas parece que 'preciso de permissão'."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "Pago na hora, {name}. Em Ventobravo, isso pedia três formulários e firma reconhecida."
L["Thanks, {name}. I'd pay in gold, but Stormwind still owes the stonemasons."] = "Valeu, {name}. Pagaria em ouro, mas Ventobravo ainda deve aos pedreiros."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "Fico em dívida, {name}. Minha mãe dizia: gentileza se devolve. E o pote também."
L["Thank you, {name}. Consider the scales balanced, by royal decree. Mine."] = "Agradeço, {name}. Dívida quitada por decreto real. Decreto meu."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "Que vergonha, {name}; eu devia ter pensado nisso antes. Permita-me."
L["Heartier than Westfall Stew, {name}, and I've wept over that stew. Thank you."] = "Supera Ensopado de Cerro Oeste, {name}, e esse ensopado já me fez chorar. Agradeço."
L["Thank you, {name}. I'll tell Marshal Dughan. He won't care, but I'll tell him."] = "Agradeço, {name}. Vou contar ao Marechal Dughan. Ele não vai ligar, mas vou contar."
L["Job's done, {name}! My grandad built half of Stormwind saying that. Thanks."] = "Serviço feito, {name}! Meu avô ergueu meia Ventobravo dizendo isso. Valeu."
L["Lakeshire will finish its bridge before I forget this, {name}. So, never."] = "Esqueço isso quando Vila Plácida terminar a ponte, {name}. Ou seja, nunca."
L["Kul Tirans say a kindness goes back on the next tide, {name}. There it goes."] = "Kultiranos dizem que gentileza volta na próxima maré, {name}. Lá vai ela."
L["Thank you, {name}. Northshire's monks would be proud. Of you. They know me."] = "Agradeço, {name}. Os monges de Vila Norte teriam orgulho. De você. Eles me conhecem."
L["Not since Mum packed my Deadmines lunch, {name}, have I felt so looked after."] = "Ninguém cuida assim de mim desde a marmita da mamãe pras Minas Mortas, {name}."
L["Into my memoirs, {name}. Chapter nine: 'Everyone Was Lovely'. Thank you."] = "Vai pras memórias, {name}. Capítulo nove: 'Todo Mundo Foi Um Amor'. Agradeço."
L["I'll toast you at the Pig and Whistle, {name}. Then the pig. Then the whistle."] = "Vou brindar a você no Porco e Apito, {name}. Depois ao porco. Depois ao apito."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "Claro, {name}. Não se mexa e faça pose heroica; os bardos agradecem."
L["Right away, {name}. Keep your shield high."] = "É pra já, {name}. Mantenha o escudo erguido."
L["More work? Gladly, {name}. It beats the lumber mill."] = "Mais trabalho? Com prazer, {name}. Melhor que a serraria."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "Claro, {name}. Humanos são ótimos em ajudar e prometer demais. Isto é ajudar."
L["Certainly, {name}. Humans are quick learners; I learned this one yesterday."] = "Certamente, {name}. Humanos aprendem rápido; eu aprendi este ontem."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "Não se mexa, {name}, feito estátua no Vale dos Heróis. Você ia combinar."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "É pra já, {name}. A Luz ajuda quem pede. Eu também, e chego antes."
L["Sailors' rule, {name}: somebody calls for help, you row. Here."] = "Regra de marinheiro, {name}: pediu ajuda, a gente rema. Tome."
L["Of course, {name}. Stand up straight; my old sergeant is watching, somewhere."] = "Claro, {name}. Coluna reta; meu velho sargento está vigiando, de algum lugar."
L["Of course, {name}. A polite request is rarer than a quiet night in Duskwood."] = "Claro, {name}. Pedido educado é mais raro que noite calma na Floresta do Crepúsculo."
L["Right away, {name}. I'll play the Archbishop; you pretend to be impressed."] = "É pra já, {name}. Eu faço o Arcebispo; você finge que se impressiona."
L["Step into the light, {name}. Not the Light; I just like to see my aim."] = "Chegue pra luz, {name}. Não a Luz, calma; só quero ver onde miro."
L["Stormwind rose from rubble, {name}. I can manage one {buff}."] = "Ventobravo se reergueu dos escombros, {name}. {buff} eu tiro de letra."
L["Of course, {name}. Last one I did was a Westfall scarecrow. Long story."] = "Claro, {name}. O último foi num espantalho de Cerro Oeste. Longa história."
L["Aye, {name}. Kul Tiran terms: a handshake, and I spare you the shanty."] = "Feito, {name}. Termos kultiranos: aperto de mão, e te poupo da cantiga de marujo."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "A estrada é longa, {name}. Isto não encurta, mas ajuda."
L["Fair winds and following seas, {name}."] = "Bons ventos e mares calmos, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "Tome, {name}. Elfos têm séculos pra ser generosos; eu tenho uns cinquenta anos."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "Um agrado, {name}. Não conte aos guardas, senão todos vão querer."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "Tome, {name}. Se um kobold perguntar, você não viu vela nenhuma."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "Para você, {name}. Presente humano: boa intenção, pura gambiarra e aguenta tudo."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "Cuidado com os murlocs, {name}. Tome; já vi o que eles fazem num piquenique."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "Toda estrada pede heroísmo, {name}. Hoje é comigo, pelo visto. Tome."
L["Stay out of Duskwood after dark, {name}. It's always dark. Take this."] = "Evite a Floresta do Crepúsculo à noite, {name}. É sempre noite. Tome."
L["Redridge gnolls take anything not nailed down, {name}. This is nailed down."] = "Gnoll de Cristarrubra leva tudo que não está pregado, {name}. Isto aqui está."
L["If you meet Hogger, {name}, take this and a friend. Mostly the friend."] = "Se topar com o Hogger, {name}, leve isto e um amigo. Principalmente o amigo."
L["The Light and a good pair of boots, {name}. Now you've got one of them."] = "A Luz e um bom par de botas, {name}. Agora você tem um dos dois."
L["Every hero in Stormwind began with a kindness and a borrowed sword, {name}."] = "Todo herói de Ventobravo começou com uma gentileza e uma espada emprestada, {name}."
L["Here, {name}. The Defias can't steal this one. They've tried everything else."] = "Tome, {name}. Este os Défias não conseguem roubar. Já tentaram todo o resto."
L["Uther blessed strangers on the road, {name}. I've less hammer, same idea."] = "Uther abençoava desconhecidos na estrada, {name}. Menos martelo, mesma ideia."
L["Take this, {name}. It's a tradition. I just started it, but it's a tradition."] = "Tome, {name}. É tradição. Comecei agora, mas é tradição."
L["The wolves in Elwynn look friendly, {name}. They are not. Take this."] = "Os lobos de Elwynn parecem simpáticos, {name}. Não são. Tome."
L["Arathor's children stand together, {name}."] = "Os filhos de Arathor seguem unidos, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "Humanos juntos, {name}! Rápido, vamos fundar um reino antes do almoço."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "Ventobravo ou Boralus, {name}, a gente reclama do tempo do mesmo jeito."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "De humano pra humano, {name}: não, também não sei por que tudo acontece com a gente."
L["Short lives, long to-do lists, {name}. We humans must help each other along."] = "Vida curta, lista de tarefas longa, {name}. Nós, humanos, temos que nos ajudar."
L["Stormwind stone or Kul Tiran oak, {name}, we outlast everyone's expectations."] = "Pedra de Ventobravo ou carvalho kultirano, {name}, duramos mais do que todos esperam."
L["Humans stick together, {name}. Everyone else is taller, older or furrier."] = "Humano ajuda humano, {name}. O resto é mais alto, mais velho ou mais peludo."
L["Our lot built half the world on bread, stubbornness and bad luck, {name}."] = "Nossa gente ergueu meio mundo com pão, teimosia e azar, {name}."
L["Don't tell the dwarves, {name}, but it was us humans who invented the tavern."] = "Não conte aos anões, {name}, mas quem inventou a taverna fomos nós, humanos."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "Fique por perto, {name}. Humano sempre ganhou na base da quantidade."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "Mantenha a formação, {name}. Não temos uma, mas mantenha assim mesmo."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "Vou traçar um plano, {name}, e aí todo mundo ignora junto."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "Todo herói das canções tinha amigos, {name}. Ninguém canta sobre eles. Eu vou."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "Escudos erguidos, {name}. Ventobravo me ensinou a marchar; parar, ninguém ensinou."
L["If this goes badly, {name}, we regroup at the nearest inn. Human tactics."] = "Se der ruim, {name}, a gente se reagrupa na estalagem mais próxima. Tática humana."
L["I've made us a flag, {name}. It's a handkerchief on a stick, but it's ours."] = "Fiz uma bandeira pra nós, {name}. É um lenço num graveto, mas é nossa."
L["Keep a torch lit, {name}. Humans can't see in the dark, and we hate it."] = "Mantenha a tocha acesa, {name}. Humano não enxerga no escuro, e odeia isso."
L["Watch my back, {name}; I'll watch yours. The Light has the rest. Better view."] = "Olho nas minhas costas, {name}, e eu nas suas. O resto é da Luz; ela vê de cima."
L["Humans always rise to the occasion, {name}. Usually after tripping over it."] = "Humano sempre se levanta pro desafio, {name}. Normalmente depois de tropeçar nele."
L["Do this well, {name}. Some elf will be telling the story for a thousand years."] = "Capriche, {name}. Algum elfo vai contar essa história por mil anos."
L["Farmers, sailors, bakers, {name}: every army Stormwind ever raised. Onward!"] = "Lavradores, marujos, padeiros, {name}: todo exército de Ventobravo. Avante!"
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah, {name}. Retribuído no mesmo dia, o que pra um kaldorei é afobação."
L["Thank you, {name}. Elune smiles on the generous."] = "Agradeço, {name}. Eluna sorri para a generosidade."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "Agradeço, {name}. Até os fogos-fátuos brilharam mais, e eles são exigentes."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "Eluna viu isso, {name}. Ela vê tudo, então é melhor eu retribuir."
L["Thank you, {name}. Returned before I nap for a century or two."] = "Agradeço, {name}. Retribuo antes de tirar um cochilo de um ou dois séculos."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "Agradeço, {name}. Os Anciãos vão saber disso. São uns fofoqueiros terríveis."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "Agradeço, {name}. Vou pedir às Sentinelas que parem de mirar em você."
L["My people never hurry, {name}. For you, an exception."] = "Meu povo nunca tem pressa, {name}. Por você, uma exceção."
L["Ande'thoras-ethil, {name}. May your troubles be diminished, as mine just were."] = "Ande'thoras-ethil, {name}. Que seus fardos diminuam, como os meus agora."
L["We gave up immortality at Hyjal, {name}. Kindness has been worth double since."] = "Abrimos mão da imortalidade em Hyjal, {name}. Desde então, gentileza vale o dobro."
L["My ears went a darker purple, {name}. On a kaldorei, that means I'm touched."] = "Minhas orelhas coraram de roxo, {name}. Em kaldorei, é sinal de que me tocou."
L["Azshara's court never gave a thing away, {name}. You've outdone a queen."] = "A corte de Azshara nunca deu nada de graça, {name}. Você superou uma rainha."
L["The owls turned their heads for that, {name}. All the way round. High praise."] = "As corujas viraram a cabeça pra isso, {name}. A volta inteira. Um grande elogio."
L["I outlived the Sundering, {name}. I'll not outlive a debt to you. Here."] = "Sobrevivi à Cisão, {name}. A uma dívida com você, eu não sobreviveria. Tome."
L["All those centuries of memories, {name}, and this one goes near the front."] = "Tantos séculos de memórias, {name}, e esta vai lá pra frente."
L["I'll tell the moon about you tonight, {name}. She likes a good story."] = "Hoje à noite vou contar de você pra lua, {name}. Ela adora uma boa história."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "Com prazer, {name}. Não se mova e deixe o luar te encontrar."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "Claro, {name}. As bênçãos de Eluna são para ser compartilhadas."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "Finalmente, {name}! Esperei dez mil anos por alguém que pedisse."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "Sem enigma, sem presságio de Eluna, {name}. Só um sim, pra variar."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "Claro, {name}. Da próxima vez, peça em darnassiano e eu faço uma reverência."
L["Elune already said yes, {name}. I'm merely catching up."] = "Eluna já disse sim, {name}. Eu só estou assinando embaixo."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "Claro, {name}. Fique imóvel e finja ser uma árvore. Ajuda."
L["Step into the light, {name}. The last kaldorei I did this for Shadowmelded."] = "Chegue pra luz, {name}. O último kaldorei pra quem fiz isso usou Fusão Sombria."
L["Certainly, {name}. Ask a kaldorei anything, except how old we are."] = "Certamente, {name}. Pergunte o que quiser a um kaldorei, menos a idade."
L["In Darnassus, {name}, this takes a moonwell and a priestess. Out here, just me."] = "Em Darnassus, {name}, isto exige um poço lunar e uma sacerdotisa. Aqui fora, só eu."
L["The last army to ask me for help was fighting demons, {name}. You're politer."] = "O último exército a me pedir ajuda enfrentava demônios, {name}. Você tem mais modos."
L["Gladly, {name}. Consider it on loan from Elune. She's never once collected."] = "Com prazer, {name}. É um empréstimo de Eluna. Ela nunca cobrou ninguém."
L["One moment, {name}. My hair is older than most kingdoms, and it tangles."] = "Um instante, {name}. Meu cabelo é mais velho que muitos reinos, e embaraça."
L["Darnassian has nine words for 'yes', {name}. I'll spare you eight of them."] = "O darnassiano tem nove palavras para 'sim', {name}. Vou te poupar de oito."
L["Of course, {name}. The Sentinels would want a password. I'll accept 'please'."] = "Claro, {name}. As Sentinelas pediriam senha. Eu aceito 'por favor'."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore, {name}. Pise leve; as árvores têm sono leve."
L["May the forest shelter you, {name}, wherever you roam."] = "Que a floresta te abrigue, {name}, aonde quer que você vá."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "Um presente das sombras, {name}. Não, nem olhe. Você não vai me achar."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "Eluna ilumina seu caminho, {name}. Eu só seguro a lanterna."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "As corujas apontaram você, {name}. Elas têm opiniões fortes. Tome."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "Tyrande insistiria, {name}, e ninguém discute com Tyrande."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "Tome, {name}. O último foi pra um hipogrifo. Ele agradeceu menos."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "Cuidado com os bichos, {name}. Metade é druida, e todos estão olhando."
L["Walk with Elune, {name}. If she's busy, walk with this."] = "Vá com Eluna, {name}. Se ela estiver ocupada, vá com isto."
L["Mind the satyrs, {name}. They were Highborne once. You can tell by the sneer."] = "Cuidado com os sátiros, {name}. Já foram Altaneiros. Dá pra ver pelo nariz empinado."
L["I've watched you from the treeline a while, {name}. Supportively. Here."] = "Faz um tempo que te observo da orla da mata, {name}. Torcendo por você. Tome."
L["Most furbolgs are friendly, {name}. This is for the other ones."] = "A maioria dos furbolgs é amigável, {name}. Isto é para os outros."
L["Moonwell water would be better, {name}, but it travels badly. This doesn't."] = "Água de poço lunar seria melhor, {name}, mas não viaja bem. Isto viaja."
L["A gift from Teldrassil, {name}. It's a long way down; I nearly dropped it."] = "Um presente de Teldrassil, {name}. A descida é longa; quase deixei cair."
L["I'd stay to chat, {name}, but kaldorei chats run to the next full moon. Here."] = "Ficaria de papo, {name}, mas papo kaldorei dura até a próxima lua cheia. Tome."
L["Bandu thoribas, {name}: prepare to fight. There. Now you're prepared."] = "Bandu thoribas, {name}: prepare-se para lutar. Pronto, preparação concluída."
L["From the kaldorei, the moon and a very old tree, {name}. Mostly from me."] = "Dos kaldorei, da lua e de uma árvore bem velha, {name}. Mais de mim, na verdade."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. Eluna mantém seus filhos por perto."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "Claro que eu te vi, {name}. Só um kaldorei pra achar outro kaldorei."
L["One kaldorei to another, {name}: we lost a tree, never each other."] = "De kaldorei pra kaldorei, {name}: perdemos uma árvore, nunca um ao outro."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "Kaldorei não deixa os seus no escuro, {name}. A não ser pra se esconder."
L["Two kaldorei, {name}, and still no helmet made that fits either pair of ears."] = "Dois kaldorei, {name}, e nenhum elmo no mundo serve nessas quatro orelhas."
L["Sentinel, druid or simply stubborn, {name}? I'm all three on a good night."] = "Sentinela, druida ou só cabeça-dura, {name}? Numa noite boa, sou os três."
L["Between us, {name}, twenty thousand years of telling everyone 'we tried that'."] = "Somando nós dois, {name}, vinte mil anos dizendo a todo mundo 'isso já tentamos'."
L["Let's Shadowmeld together sometime, {name}, and see who notices."] = "Um dia, vamos usar Fusão Sombria ao mesmo tempo, {name}, e ver quem nota."
L["Our shan'do sleeps in the Dream, {name}. Let's make his waking worth it."] = "Nosso shan'do dorme no Sonho, {name}. Vamos fazer o despertar dele valer a pena."
L["Our people are thin on the ground, {name}, and very thick in the trees."] = "Tem pouco kaldorei no chão, {name}. Nas árvores, está lotado."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "Coisa rápida, {name}? Pelo relógio kaldorei, acabamos antes de começar."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "Eu vou ser quem você não vê, {name}. Não é erro; é o plano."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "Eluna vigia o grupo todo, {name}. Eu sou só quem acena pra ela."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "Dez mil anos de companheiros, {name}. Vocês estão bem no topo da lista."
L["Stay close, {name}. We kaldorei misplaced two World Trees. Not you, though."] = "Fique por perto, {name}. Nós, kaldorei, perdemos duas Árvores do Mundo. Você não."
L["If I fall, {name}, don't fret. I'll float about as a wisp, looking wise."] = "Se eu cair, {name}, não se aflija. Viro fogo-fátuo e flutuo por aí com ar sábio."
L["I fought beside Neltharion once, {name}. You're already a better ally."] = "Já lutei ao lado de Neltharion, {name}. Você já é companhia melhor."
L["Follow me, {name}. I know these paths. They were a forest last time, mind."] = "Venha, {name}. Conheço estas trilhas. Da última vez, era tudo floresta."
L["Should we fail, {name}, I'll remember you fondly for several thousand years."] = "Se falharmos, {name}, vou lembrar de você com carinho por alguns milênios."
L["I've watched heroes charge in blind for millennia, {name}. Let's try eyes open."] = "Vi heróis avançarem às cegas por milênios, {name}. Vamos tentar de olhos abertos."
L["If anyone asks, {name}, we were always this good. I'll swear to it for ages."] = "Se alguém perguntar, {name}, sempre mandamos bem assim. Juro isso por eras."
L["I'll take first watch, {name}. And second. A kaldorei barely notices a night."] = "Eu faço a primeira vigília, {name}. E a segunda. Kaldorei mal percebe uma noite."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "A lua subiu, {name}. Pra um kaldorei, isso é o meio da manhã."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "Todo mundo sensato está dormindo, {name}. Eluna e eu preferimos assim."
L["Moonlight suits you, {name}. This is merely a second layer."] = "O luar cai bem em você, {name}. Isto é só uma segunda camada."
L["Dark at last, {name}. Now I see perfectly and everything else has to guess."] = "Enfim escuro, {name}. Agora eu vejo tudo, e o resto que adivinhe."
L["Same stars I saw ten thousand years ago, {name}. They've aged better than me."] = "As mesmas estrelas de dez mil anos atrás, {name}. Envelheceram melhor que eu."
L["Moonrise, {name}. Every kaldorei just woke up a little, and got a little smug."] = "A lua nasceu, {name}. Todo kaldorei despertou um pouco, e se achou um pouco mais."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "Bom dia, {name}. Meu povo passou milênios dormindo nessa hora. Estou me adaptando."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "Amanheceu, {name}. Eluna foi dormir, então estou cobrindo o turno dela."
L["The sun's up, {name}, and so, reluctantly, am I."] = "O sol levantou, {name}, e eu também, a contragosto."
L["Too bright, {name}. I'll squint through this one; Elune forgives squinting."] = "Claro demais, {name}. Vou apertar os olhos; Eluna perdoa olho apertado."
L["Daybreak, {name}: the one hour a night elf is easy to spot. Quick, take this."] = "Amanhecer, {name}: a única hora em que se vê um elfo noturno. Rápido, tome."
L["Up early, {name}? I'm up late. Let's meet in the middle, with this."] = "Madrugou, {name}? Eu nem dormi. A gente se encontra no meio, com isto."
L["The shadows remember kindness, {name}. So do I."] = "As sombras guardam a gentileza, {name}. Eu também."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "Agradeço, {name}. Os ren'dorei não esquecem uma gentileza."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "Agradeço, {name}. As vozes aprovam você, o que é francamente alarmante."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "Agradeço, {name}. Poucos presenteiam alguém com um brilho tão sinistro."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "Gentileza é rara no Caos, {name}. Vou devolver a sua antes que ele perceba."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "Luaprata nos expulsou, {name}. Com gente como você, fica difícil ligar."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "Devolvido por inteiro, {name}. Pode vir meio roxo. É normal."
L["The Void only takes, {name}. I, however, give back."] = "O Caos só toma, {name}. Eu, por outro lado, devolvo."
L["Thank you, {name}. The whispers went quiet. That's how I know it was sincere."] = "Agradeço, {name}. Os sussurros se calaram. É assim que sei que foi sincero."
L["Thank you, {name}. I'd smile, but people say it's unsettling. So: imagine one."] = "Agradeço, {name}. Eu sorriria, mas dizem que assusta. Então: imagine um sorriso."
L["Returned, {name}: cold hands, warm intentions. That's us in a sentence."] = "Devolvido, {name}: mãos frias, coração quente. Somos nós, numa frase."
L["Returned, {name}. You may hear it twice; my spells echo now."] = "Devolvido, {name}. Pode ouvir em dobro; meus feitiços ecoam... ecoam."
L["The Void offered me forbidden knowledge, {name}. Yours was the nicer gift."] = "O Caos me ofereceu saber proibido, {name}. O seu presente foi mais simpático."
L["Alleria says the Void can be mastered, {name}. Kindness, I find, is easier."] = "Alleria diz que o Caos pode ser dominado, {name}. Gentileza, acho, é mais fácil."
L["Much obliged, {name}. Most people give us a wide berth. You gave me this."] = "Fico em dívida, {name}. Quase todos nos dão distância. Você me deu isto."
L["Thank you, {name}. My shadow bowed as well. It never does. You've impressed it."] = "Agradeço, {name}. Até minha sombra se curvou, e ela nunca faz isso. Impressionou."
L["As you wish, {name}. The shadows answer kindly today."] = "Como quiser, {name}. As sombras estão generosas hoje."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "Considere feito, {name}. O Caos nos obedece, não o contrário."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "Certamente, {name}. Os sussurros disseram não, então é um sim fácil."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "Claro, {name}. {buff} com uma pitada de Caos."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "Claro, {name}. Não se mexa; as sombras são tímidas com desconhecidos."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "Com prazer, {name}. Boas maneiras ren'dorei: o Caos espera a vez dele."
L["Asked so nicely, {name}? The Void never says please. Here."] = "Pediu com educação, {name}? O Caos nunca diz 'por favor'. Tome."
L["Of course, {name}. Stand in the light, please; the Void gets ideas in corners."] = "Claro, {name}. Fique na luz, por favor; nos cantos, o Caos tem ideias."
L["Of course, {name}. The Void asked why. I said 'manners'. It's still puzzled."] = "Claro, {name}. O Caos perguntou por quê. Respondi 'boas maneiras'. Segue confuso."
L["Gladly, {name}. Nobody asks us for anything but 'please stop whispering'."] = "Com prazer, {name}. Ninguém nos pede nada além de 'pare de sussurrar, por favor'."
L["Happy to, {name}. Just let me finish arguing with myself. There. I won."] = "Com prazer, {name}. Só termino aqui uma discussão interna. Pronto. Ganhei."
L["Certainly, {name}. I could rift over there first, but that feels showy."] = "Certamente, {name}. Podia abrir uma fenda até aí antes, mas seria ostentação."
L["Asking questions got us exiled, {name}. Answering one is quite safe, I'm told."] = "Perguntar demais nos custou o exílio, {name}. Responder, dizem, é seguro."
L["Of course, {name}. A slight chill and a faint chorus are both perfectly normal."] = "Claro, {name}. Um leve arrepio e um coral distante são perfeitamente normais."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "Um toque de sombra, {name}. Bem seguro. Quase sempre."
L["Walk carefully in the dark places, {name}."] = "Cuidado nos lugares escuros, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "Uma lembrancinha da Fenda Telogrus, {name}. É mais limpa do que parece."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "Tome, {name}. Se vir tentáculos, são só decorativos."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "As sombras perguntaram por você, {name}. Mandei que tivessem modos."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "Tome, {name}. Entramos no Caos pra você não precisar."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "Conferi sua sombra, {name}. Nada à espreita. Tome isto mesmo assim."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "Umbric manda lembranças, {name}. Não manda, mas mandaria."
L["Take this, {name}. It may whisper a compliment. Pretend you didn't hear."] = "Tome, {name}. Pode ser que sussurre um elogio. Finja que não ouviu."
L["Here, {name}. Looks sinister, works beautifully. Rather like me."] = "Tome, {name}. Parece sinistro, funciona lindamente. Meio como eu."
L["Take this, {name}. The Void had worse in mind for you. I intercepted."] = "Tome, {name}. O Caos tinha planos piores pra você. Eu interceptei."
L["If something in the dark whispers your name, {name}, relax. That was me. Here."] = "Se algo no escuro sussurrar seu nome, {name}, relaxe. Fui eu. Tome."
L["Here, {name}. We ren'dorei don't often get to be the nice surprise."] = "Tome, {name}. Não é sempre que nós, ren'dorei, somos a surpresa boa."
L["I left Quel'Thalas with only a knack for the dark, {name}. Here's the knack."] = "Saí de Quel'Thalas só com um jeitinho pro escuro, {name}. Aqui está o jeitinho."
L["Here, {name}. Don't thank the shadows; they'll only want something. Thank me."] = "Tome, {name}. Não agradeça às sombras, que elas cobram. Agradeça a mim."
L["I owe a kindness for every ominous look I've given, {name}. I'm badly behind."] = "Devo uma gentileza por cada olhar sinistro que já dei, {name}. A conta está alta."
L["We ren'dorei look after our own, {name}."] = "Nós, ren'dorei, cuidamos dos nossos, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "Azar de Luaprata, {name}. Estamos muito bem sem ela."
L["Your whispers and mine should really meet sometime, {name}."] = "Seus sussurros e os meus precisam se conhecer um dia, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "Ren'dorei em dobro, {name}. Rápido, cara de sofrência. É o esperado."
L["Nobody else understands the hair, {name}. It was blond once. I think."] = "Ninguém mais entende o cabelo, {name}. Já foi loiro. Acho."
L["Telogrus felt like home in the end, {name}. A very draughty, very dark home."] = "No fim, Telogrus virou lar, {name}. Um lar escuro e cheio de vento encanado."
L["Ren'dorei to ren'dorei, {name}: what's yours whispering? Mine's on about soup."] = "De ren'dorei pra ren'dorei, {name}: e os seus sussurros? Os meus só falam de sopa."
L["Stay close, {name}. The whispers are much quieter in company."] = "Fique por perto, {name}. Os sussurros ficam bem mais baixos com companhia."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "Se as sombras começarem a dar ordens, {name}, ignore. Eu costumo ignorar."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "De olho na minha sombra, {name}. Ela some quando tem combate."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "Se eu brilhar roxo, {name}, siga em frente. Só quer dizer que me empolguei."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "Ren'dorei são boa companhia, {name}. Trazemos até o escuro pra gente se esconder."
L["If I seem to talk to nobody, {name}, I'm fine. If nobody talks back, worry."] = "Se eu falar com ninguém, {name}, tudo bem. Preocupe-se se o ninguém responder."
L["I'll open a rift if it goes wrong, {name}. Only for me, sadly. But I'll wave."] = "Se der errado, {name}, abro uma fenda. Só pra mim, infelizmente. Mas eu aceno."
L["Try to enjoy this, {name}. We ren'dorei rarely get invited anywhere twice."] = "Aproveite, {name}. É raro alguém convidar um ren'dorei duas vezes."
L["Keep the lanterns lit, {name}. I don't need them; the shadows behave better."] = "Deixe as lanternas acesas, {name}. Não por mim: as sombras se comportam melhor."
L["Keep an eye on the corners, {name}. I'll keep an eye on what's in them."] = "Fique de olho nos cantos, {name}. Eu fico de olho no que tem neles."
L["The Void promised me power, {name}. It never mentioned company this good."] = "O Caos me prometeu poder, {name}. Nunca falou de companhia tão boa."
L["If you hear whispers mid-fight, {name}, they're cheering. For us, I think."] = "Se ouvir sussurros no meio do combate, {name}, é torcida. Pra nós, acho."
L["Should anything eldritch turn up, {name}, let me talk to it. I speak a little."] = "Se surgir algum horror ancestral, {name}, deixe comigo. Arranho a língua."
L["Night suits the ren'dorei, {name}. We match the decor."] = "A noite cai bem aos ren'dorei, {name}. Combinamos com a decoração."
L["The shadows are longest now, {name}, and in a very generous mood."] = "As sombras estão mais compridas agora, {name}, e bem generosas."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "Tarde, {name}? Os sussurros amam a madrugada. Cedo ou tarde, eu também."
L["Midnight, {name}. The one hour my shadow and I agree on anything."] = "Meia-noite, {name}: a única hora em que minha sombra e eu concordamos."
L["Stars out, {name}. I've seen what's between them, and I prefer the stars."] = "Estrelas no céu, {name}. Já vi o que tem entre elas, e prefiro as estrelas."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "Valeu, {name}! Gentileza recebida, catalogada e devolvida!"
L["Reciprocity engaged! Much obliged, {name}."] = "Reciprocidade acionada! Valeu mesmo, {name}."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "Pelos meus cálculos, {name}, te devo exatamente uma dose de {buff}."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "Valeu, {name}! Eu te faria uma máquina de agradecer, mas ela ia explodir."
L["Thank you, {name}! This calls for a celebration. Stand back, I'll build one."] = "Valeu, {name}! Isso pede uma comemoração. Afaste-se, vou construir uma."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "Que gentileza, {name}! Retribuir o favor só levou quatro esquemas."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "Droga, {name}! Eu ia inventar a gratidão, mas você chegou primeiro."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "Ah, {name}, que gentileza! Meu coração tá fazendo aquele zumbido de novo."
L["Noted in my lab journal, {name}, page four hundred: 'people are lovely'."] = "Anotado no caderno do laboratório, {name}, página 400: 'gente é um amor'."
L["Splendid, {name}! Returning it at once, before I'm tempted to improve it."] = "Esplêndido, {name}! Devolvo agora, antes que me dê vontade de melhorar."
L["Thanks, {name}! Kindness is a reversible reaction. I checked. Here's yours."] = "Valeu, {name}! Gentileza é uma reação reversível. Conferi. Aqui está a sua."
L["My mechanostrider would salute you, {name}, but it only knows falling over."] = "Meu mecanostrider te bateria continência, {name}, mas ele só sabe cair."
L["My transporter would've sent this to Gadgetzan, {name}. Hand-delivered instead!"] = "Meu transportador ia mandar isso pra Geringontzan, {name}. Entreguei em mãos!"
L["Oh, thank you, {name}! I haven't felt this good since before the troggs."] = "Ah, valeu, {name}! Não me sinto tão bem desde antes dos troggs."
L["I'll name my next invention after you, {name}! It's a very small cannon."] = "Vou batizar minha próxima invenção com seu nome, {name}! É um canhão bem pequeno."
L["Thanks, {name}! Mind the whistle; that's just my gratitude valve venting."] = "Valeu, {name}! Ignore o apito; é só minha válvula de gratidão soltando pressão."
L["You're on my list of favourite people, {name}! It's short. Mostly clockwork."] = "Entrou pra minha lista de gente favorita, {name}! É curta. Quase só engrenagem."
L["Request received, {name}! Processing... done!"] = "Pedido recebido, {name}! Processando... pronto!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "Um aprimoramento saindo, {name}! Não se mexa durante a calibragem."
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "Claro, {name}! Construí uma máquina pra isso. Tá em pedaços, então: na mão."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "Certamente, {name}! Fique em cima do X. Não tem X. Fique em qualquer lugar."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "É pra já, {name}! Óculos no rosto. Não é por você, eu só gosto deles."
L["{buff}, {name}? Simple in theory AND practice. Suspicious!"] = "{buff}, {name}? Simples na teoria E na prática. Suspeito!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "Com prazer, {name}! Mantenha mãos, pés e sobrancelhas bem longe."
L["Right away, {name}! Stand back three paces. Four. Five. There, perfect."] = "É pra já, {name}! Três passos pra trás. Quatro. Cinco. Isso, perfeito."
L["Happy to, {name}! It beats sorting springs by size. Though that's fun too."] = "Com prazer, {name}! Melhor que separar molas por tamanho. Que também é ótimo."
L["Excellent request, {name}! No moving parts. I'll try to add some next time."] = "Ótimo pedido, {name}! Sem peças móveis. Na próxima eu tento pôr algumas."
L["Standard model or deluxe, {name}? They're the same. Deluxe sounds nicer."] = "Modelo básico ou luxo, {name}? São iguais. Luxo soa melhor."
L["Coming up, {name}! Fresh off the workbench, still warm, only slightly smoking."] = "Saindo, {name}! Direto da bancada, quentinho, soltando só um fiozinho de fumaça."
L["Approved, {name}! Stamped, signed and filed under 'obviously'."] = "Aprovado, {name}! Carimbado, assinado e arquivado em 'óbvio'."
L["Of course, {name}! Adjust the gyromatic... no, wait, that's the squirrel's."] = "Claro, {name}! Ajustar o giromático... não, peraí, esse é do esquilo."
L["Gnomes never refuse a problem, {name}. Occasionally we cause them. Here!"] = "Gnomo nunca recusa um problema, {name}. Às vezes a gente até fabrica. Tome!"
L["Hold still, {name}, this is perfectly safe. Probably!"] = "Não se mexa, {name}, é totalmente seguro. Provavelmente!"
L["Science says you need this, {name}. Who am I to argue?"] = "A ciência diz que você precisa, {name}. Quem sou eu pra negar?"
L["A small upgrade for you, {name}. No cogs required."] = "Uma melhoriazinha pra você, {name}. Sem engrenagens."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "Pode levar, {name}, tenho reserva. Tenho três reservas de tudo."
L["Try this, {name}! Version one had legs. Version two is much better."] = "Experimente, {name}! A versão um tinha pernas. A versão dois é bem melhor."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "O Grão-Faz-Tudo manda dividir nossa genialidade, {name}. Eis uma amostra!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "Gnomeregan para sempre, {name}! Isto dura bem menos, mas é de graça."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "Sou de bolso, {name}, mas meu presente é tamanho família. Tome!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "Relaxa, {name}! Funcionou na galinha, e a galinha adorou."
L["Field test, {name}! You're the lucky volunteer. Everyone's a volunteer, really."] = "Teste de campo, {name}! Seu nome saiu no sorteio de voluntários. Saem todos."
L["One size fits all, {name}, gnome to tauren. I measured. The tauren was patient."] = "Tamanho único, {name}, de gnomo a tauren. Eu medi. O tauren teve paciência."
L["Take this, {name}! Unlike my Net-o-Matic, it never lands on me."] = "Tome, {name}! Meu lança-redes vive caindo em mim. Isto, nunca."
L["The Gnomish Army Knife does twelve things badly, {name}. This does one well."] = "O canivete gnômico faz doze coisas mal, {name}. Isto faz uma bem."
L["Guarantee void if exposed to troggs, dragonfire or enthusiasm, {name}. Enjoy!"] = "Garantia não cobre troggs, fogo de dragão nem empolgação, {name}. Aproveite!"
L["Nothing up my sleeves, {name}! Well, a spanner and two fuses. Nothing sinister."] = "Nada na manga, {name}! Bom, uma chave inglesa e dois fusíveis. Nada suspeito."
L["Here, {name}! It's small, but so is a keystone, and look what those hold up."] = "Tome, {name}! É pequeno, mas a pedra-chave também é, e segura o arco todo."
L["I'd explain how it works, {name}, but that takes three days and a chalkboard."] = "Eu explicaria como funciona, {name}, mas leva três dias e um quadro-negro."
L["If you hear ticking, {name}, that's my pocket watch. Almost certainly."] = "Se ouvir um tique-taque, {name}, é meu relógio de bolso. Quase com certeza."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "Por Gnomeregan, {name}! Que bom falar com alguém da minha altura."
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "Reunião de gnomos, {name}! Eu seguro o esquema; você segura o balde."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "Carne ou engrenagem, {name}, somos todos gnomos. Alguns só precisam de óleo."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "De gnomo pra gnomo, {name}: você desligou o reator, né?"
L["Two gnomes, {name}! Stacked up, we're very nearly a night elf."] = "Dois gnomos, {name}! Empilhados, quase dá um elfo noturno."
L["You check my sums, {name}, I check yours, and we're both quietly offended."] = "Você confere minhas contas, {name}, eu as suas, e nos ofendemos em silêncio."
L["You still owe me a sprocket, {name}. Every gnome owes me a sprocket."] = "Você me deve uma engrenagem, {name}. Todo gnomo me deve uma engrenagem."
L["One day, {name}, we'll walk back into Gnomeregan together. With the lights on."] = "Um dia, {name}, eu e você voltamos pra Gnomeregan. E de luz acesa."
L["Between gnomes, {name}: we both know it'll explode, and we both want to watch."] = "Entre gnomos, {name}: a gente sabe que vai explodir, e quer ver de camarote."
L["Shall we build something huge, {name}? Just to see the tall folk's faces?"] = "Vamos construir algo enorme, {name}? Só pra ver a cara do povo alto?"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "Calibragem do grupo concluída, {name}! Ninguém toca em nada brilhante."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "Fiz as contas, {name}: com você aqui, a gente vence. Arredondei pra cima."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "Se eu gritar 'bomba!', {name}, não é o doce. Da última vez deu ruim."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "Formação, {name}: gente alta na frente, eu em algum lugar seguro e esperto."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "Um pra cada, {name}! Peças padronizadas são o segredo de uma boa máquina."
L["My plan, {name}: step one, survive. Step two is still in development."] = "Meu plano, {name}: passo um, sobreviver. O passo dois ainda tá na prancheta."
L["Don't panic, {name}. Whatever goes wrong, I'll have a gadget for it. Next week."] = "Sem pânico, {name}. Deu errado? Vou ter uma engenhoca pra isso. Semana que vem."
L["If I vanish, {name}, check under the nearest boot. Politely, please."] = "Se eu sumir, {name}, olhe sob a bota mais perto. Com educação, por favor."
L["When this is over, {name}, I want samples. Of everything. The big one first."] = "Quando isso acabar, {name}, quero amostras. De tudo. Do grandão primeiro."
L["Every explosion today, {name}, is on purpose. I'll decide which ones later."] = "Toda explosão de hoje, {name}, é de propósito. Depois eu decido quais."
L["Group trial under way, {name}! No control group. Everybody gets the good stuff."] = "Experimento em grupo rolando, {name}! Ninguém toma placebo. Todo mundo leva o bom."
L["If we get separated, {name}, follow the smoke. It'll be me."] = "Se a gente se separar, {name}, siga a fumaça. Sou eu."
L["Everyone keep their fingers, {name}. I've counted. I'll count again after."] = "Ninguém perde dedo, {name}. Já contei. Depois conto de novo."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "Bom dia, {name}! De pé desde as três. A torradeira precisava de motor novo."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "Bom dia, {name}! O café tá se passando sozinho. Aprendeu. Preocupante."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "Começando cedo, {name}! As melhores ideias vêm antes do café. As explosões também."
L["Morning, {name}! My alarm clock went off at six. Exploded, I mean. Effective!"] = "Bom dia, {name}! Meu despertador disparou às seis. Explodiu, digo. Eficiente!"
L["Up early, {name}? I dreamt of a better sprocket and couldn't wait. Here!"] = "Madrugou, {name}? Sonhei com uma engrenagem melhor e não aguentei. Tome!"
L["Morning, {name}! The sun's a bit dim today. I've been meaning to fix that."] = "Bom dia, {name}! O sol tá meio fraco hoje. Faz tempo que quero consertar isso."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "A Luz recompensa a bondade, {name}. Eu só faço a entrega expressa."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. Sua dádiva é retribuída."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "Agradeço, {name}. Te daria uma carona de nave, mas você viu como a gente pousa."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "Um presente dado de coração, {name}. Os Naarus zumbem mais alto. Retribuído."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "Belo gesto, {name}. Em Argus, a gente gravaria isso em cristal. Tome."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "Em doze mundos, {name}, gentileza foi a única língua que não tive de aprender."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "Que gentileza, {name}. Quase compensa a Legião. Quase."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "Agradeço, {name}. Diria na minha língua, mas leva onze minutos."
L["Thank you, {name}. The Exodar crashed; my manners didn't. Here."] = "Agradeço, {name}. O Exodar caiu; a educação ficou de pé. Tome."
L["Sargeras once offered my people gifts, {name}. We ran. Yours, I'll keep."] = "Sargeras já ofereceu presentes ao meu povo, {name}. Fugimos. O seu eu aceito."
L["Thank you, {name}. I've fled demons across the stars, but never from a debt."] = "Agradeço, {name}. Fugi de demônios pelas estrelas, mas nunca de uma dívida."
L["Thank you, {name}. I'll add you to my prayers. The list goes back to Argus."] = "Agradeço, {name}. Vou pôr você nas minhas preces. A lista vem desde Argus."
L["The Legion took a world from us, {name}. Folk like you keep giving bits back."] = "A Legião nos tirou um mundo, {name}. Gente como você vai devolvendo aos pedacinhos."
L["You gave first, {name}. A prophet would call it an omen. I call it manners."] = "Você deu primeiro, {name}. Um profeta diria presságio. Eu digo educação."
L["With the Light's compliments, {name}. It asked me to add 'nicely done'."] = "Com os cumprimentos da Luz, {name}. Ela pediu para acrescentar 'muito bem'."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "Claro, {name}. Os Naarus guiam seus passos; isto dá um gás neles."
L["Gladly, {name}. The Light answers those who ask."] = "Com prazer, {name}. A Luz atende a quem pede."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "Velen previu seu pedido, {name}. Eu previ meu sim."
L["The Light is not rationed, {name}. Take as much as you like."] = "A Luz não é racionada, {name}. Pegue quanto quiser."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "Claro, {name}. Já fugi da Legião Ardente; isto eu dou conta."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "Agora mesmo, {name}. Cascos firmes, cristais zumbindo, lá vai."
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "Com prazer, {name}. Segui um cristal falante pelas estrelas. Isto é fácil."
L["Certainly, {name}. Velen taught us patience. Luckily, this takes none."] = "Certamente, {name}. Velen nos ensinou paciência. Por sorte, aqui nem precisa."
L["Gladly, {name}. The naaru never say no. They say 'hmmm', but it means yes."] = "Com prazer, {name}. Os Naarus nunca dizem não. Dizem 'hmmm', mas quer dizer sim."
L["On the Exodar this took three crystals and a prayer, {name}. Here: the prayer."] = "No Exodar isto levava três cristais e uma prece, {name}. Aqui vai a prece."
L["Of course, {name}. I only refuse demons, and they so rarely say please."] = "Claro, {name}. Só digo não a demônios, e eles quase nunca pedem por favor."
L["Gladly, {name}. We were refugees long enough to know what asking costs."] = "Com prazer, {name}. Fomos refugiados o bastante para saber o custo de pedir."
L["Of course, {name}. My people crossed the stars looking for friends. Found one."] = "Claro, {name}. Meu povo cruzou as estrelas procurando amigos. Missão cumprida."
L["Ask a draenei, {name}: one yes, one blessing, possibly a history lesson."] = "Peça a um draenei, {name}: um sim, uma bênção e, talvez, uma aula de história."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "A Luz está com você, {name}. Vá em paz, ou pelo menos com proteção."
L["Walk in the Light, {name}. May it shelter you always."] = "Caminhe na Luz, {name}. Que ela sempre te abrigue."
L["Take this, {name}. My people always travel Light."] = "Tome, {name}. Meu povo viaja leve: bagagem de mão e muita Luz."
L["Take this, {name}. The Legion is always coming. I'd know."] = "Tome, {name}. A Legião sempre vem. Eu que o diga."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "Hoje acabaram os milagres, {name}. {buff} serve?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "Para a estrada, {name}. A minha já dura vinte e cinco mil anos."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "Bênção de naaru, {name}. Bom, eu fiquei perto de um. Conta igual."
L["Take this, {name}. It glows a bit. Everything we own does."] = "Tome, {name}. Brilha um pouco. Tudo o que é nosso brilha."
L["Here, {name}. We draenei pack for the end of the world. We've had the practice."] = "Tome, {name}. Nós, draeneis, fazemos as malas para o fim do mundo. Prática não falta."
L["Take this, {name}. I've stayed a step ahead of demons for ages. Now you're two."] = "Tome, {name}. Estou um passo à frente dos demônios há eras. Agora você está a dois."
L["The naaru shine on all, {name}. They're dreadful at aiming. I'm helping."] = "Os Naarus brilham para todos, {name}, mas miram mal demais. Estou ajudando."
L["A stranger shared bread with me on Azuremyst, {name}. I'm still paying it back."] = "Um desconhecido dividiu o pão comigo em Névoa Lazúli, {name}. Ainda estou pagando."
L["Velen sees a thousand futures, {name}. I see one: you, better prepared. Here."] = "Velen vê mil futuros, {name}. Eu vejo um: você, com mais proteção. Tome."
L["Don't drink from the streams on Bloodmyst, {name}. Do take this."] = "Não beba dos riachos de Névoa Rubra, {name}. Isto, pode tomar."
L["Eredar magic from before the fall, {name}. We only kept the good kind. Here."] = "Magia eredar de antes da queda, {name}. Só guardamos a boa. Tome."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros, {name}! Os filhos de Argus cuidam uns dos outros."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "Lar é onde draeneis se encontram, {name}. Hoje, é aqui."
L["Horns high, {name}. Two draenei, and nobody's mentioned the Legion. Progress."] = "Chifres erguidos, {name}. Encontro de draeneis e ninguém citou a Legião. Progresso."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "Caudas erguidas, {name}. Argus teria orgulho do que fizemos do exílio."
L["Two draenei, {name}, and between us nearly fifty thousand years of worrying."] = "Draenei com draenei, {name}: quase cinquenta mil anos de preocupação somados."
L["Horns, hooves and hope, {name}. The Legion never found a cure for any of them."] = "Chifres, cascos e esperança, {name}. A Legião nunca achou cura para nenhum dos três."
L["Children of Velen, {name}: exiled, hopeful and dreadfully polite."] = "Povo de Velen, {name}: exílio, esperança e uma educação de dar medo."
L["Third world's the charm, {name}. We draenei are owed one that stays put."] = "Terceiro lar é o da sorte, {name}. Os draeneis merecem um que fique no lugar."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "Fique por perto, {name}. Já perdi um mundo; este grupo eu não perco."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "Vinte e cinco mil anos fugindo, {name}. Andar com amigos é bem melhor."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "Os Naarus chamariam isto de irmandade, {name}. Eu chamo de sorte."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "Já vi mundos acabarem, {name}. O que vier pela frente mal me preocupa."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "Todo mundo junto, {name}. A Luz nos acha mais fácil num lugar só."
L["Stay close, {name}. We draenei are very good at leaving places in a hurry."] = "Fique por perto, {name}. Nós, draeneis, somos ótimos em sair às pressas."
L["We draenei take the long view, {name}. From up here, this fight is very short."] = "Nós, draeneis, vemos longe, {name}. Daqui de cima, este combate é curtinho."
L["Let me go first, {name}. Anything watching will see a very tall optimist."] = "Eu vou na frente, {name}. Quem estiver de olho vai ver um otimista bem alto."
L["We draenei follow prophets, {name}. Today I'll settle for following you."] = "Nós, draeneis, seguimos profetas, {name}. Hoje, me contento em seguir você."
L["The Exodar carried thousands, {name}, and this little party still feels safer."] = "O Exodar levava milhares, {name}, e este grupinho ainda parece mais seguro."
L["Shoulder to shoulder, {name}. Mine's a bit higher, but the principle holds."] = "Ombro a ombro, {name}. O meu fica um pouco mais alto, mas vale o princípio."
L["A prayer for the party, {name}. The short one. The long one ends next age."] = "Uma prece pelo grupo, {name}. A curta. A longa termina na próxima era."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "Fico em dívida, {name}. Guilnéas nunca esquece uma gentileza, nem o meu faro."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "Que gentileza, {name}. Tem minha gratidão e meu melhor uivo."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "Agradeço, {name}. Se worgens tivessem rabo, o meu estaria abanando."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "Você ganhou uma amizade eterna, {name}. Lealdade é bem a nossa praia."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "A fera quer rosnar, {name}. A educação guilneana insiste em agradecer."
L["Much appreciated, {name}. I'd shake your hand, but, claws. Here instead."] = "Agradeço muito, {name}. Apertaria sua mão, mas... garras. Tome isto."
L["We walled ourselves off for years, {name}. You make that look silly."] = "Passamos anos atrás de uma muralha, {name}. Você faz isso parecer bobagem."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "Valeu, {name}. Você ganhou um lugar perto da lareira. O lugar bom."
L["Thank you, {name}. In return, I'll never chase your mount. Well, rarely."] = "Agradeço, {name}. Em troca, nunca vou perseguir sua montaria. Bom, quase nunca."
L["Returned, {name}, with a stiff upper lip. The lower one shows teeth; ignore it."] = "Retribuído, {name}, com um sorriso contido. Se aparecerem presas, finja que não viu."
L["Thank you, {name}. I'd tip my hat, but it doesn't fit over the ears these days."] = "Agradeço, {name}. Tiraria o chapéu, mas hoje em dia ele não passa pelas orelhas."
L["Thank you, {name}. Most folk just scratch my ears and hope for the best."] = "Agradeço, {name}. A maioria só coça minhas orelhas e torce pelo melhor."
L["Returned, {name}. A Gilnean pays debts; a worgen pays them at a sprint."] = "Retribuído, {name}. Guilneano paga as dívidas; worgen paga correndo."
L["Spoiled twice today, {name}, and the first time was a biscuit. Thank you."] = "Dois agrados hoje, {name}, e o primeiro foi um biscoito. Agradeço."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "Certamente, {name}. Não se mexa, eu não mordo. Muito."
L["Right you are, {name}. Stand steady now."] = "Pois não, {name}. Agora fique firme."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "É pra já, {name}. Agora, fica. Sempre quis dizer isso."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "Com prazer, {name}. Faça chuva ou faça sol, e em Guilnéas é chuva."
L["Certainly, {name}. I'll try not to shed on you."] = "Certamente, {name}. Vou tentar não soltar pelo em você."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "Nem precisa dizer, {name}. Estas orelhas ouviram antes de você decidir pedir."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "Claro, {name}. Você pediu com mais jeito que o último que me jogou um graveto."
L["Glad to, {name}. Few people ask a seven-foot wolf for favours. I love it."] = "Com prazer, {name}. Pouca gente pede favor a um lobo de dois metros. Adoro."
L["Certainly, {name}. I'll stay in this form. The other one causes a scene."] = "Certamente, {name}. Fico nesta forma. A outra causa alvoroço."
L["Tea first? No? Straight to business, {name}. How very un-Gilnean. Here."] = "Chá primeiro? Não? Direto ao assunto, {name}. Que pouco guilneano. Tome."
L["Of course, {name}. Excuse the damp. Nothing smells quite like a wet worgen."] = "Claro, {name}. Perdão pela umidade. Nada cheira como worgen molhado."
L["Of course, {name}. I'll try not to sniff. I will fail, but I'll try."] = "Claro, {name}. Vou tentar não farejar. Não vou conseguir, mas vou tentar."
L["Of course, {name}. Anything but a bath."] = "Claro, {name}. Tudo, menos banho."
L["Stay off the moors after dark, {name}. Take this."] = "Longe das charnecas à noite, {name}. Tome isto."
L["Keep your wits about you, {name}. Something is always hunting."] = "Mantenha a guarda, {name}. Sempre tem alguma coisa caçando."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "Eu teria trazido antes, {name}, mas parei pra correr atrás de uma coisa."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "Pra você, {name}. Não, não quero petisco. Bom... talvez um pequeno."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "Guilneanos sempre oferecem, {name}. As garras são só parte do figurino."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "Remédio guilneano, {name}. Cura gripe, tristeza e quase toda maldição. A minha, não."
L["Run with this, {name}. Trust me, I know about running."] = "Corra com isto, {name}. Confie em mim, de correr eu entendo."
L["Fetched this for you, {name}. Don't make a thing of it."] = "Fui buscar isto pra você, {name}. Não precisa fazer festa."
L["Here, {name}. That's why I was following you. Honestly. I'll stop now."] = "Tome, {name}. Era por isso que eu estava te seguindo. Sério. Já parei."
L["For you, {name}. Not everything that prowls was as well raised as I was."] = "Para você, {name}. Nem tudo que ronda por aí teve a minha criação."
L["From a Gilnean of good family, {name}. The fur is new; the manners are old."] = "De uma boa família guilneana, {name}. O pelo é novo; os modos, antigos."
L["I thought of this in a dream, {name}. I was also chasing a rabbit. Here."] = "Sonhei com isto, {name}. No sonho eu também corria atrás de um coelho. Tome."
L["Liam would have cried 'For Gilneas!', {name}. I'll just say: for you."] = "Liam teria gritado 'Por Guilnéas!', {name}. Eu só digo: por você."
L["Tal'doren's druids taught me to leash the beast, {name}. Now it fetches. Here."] = "Em Tal'doren os druidas domaram minha fera, {name}. Agora ela traz a bolinha."
L["Be careful out there, {name}. Take it from someone who was bitten once."] = "Cuidado lá fora, {name}. Conselho de quem já levou uma mordida."
L["Here, {name}. I'd leave it on your doorstep, but that frightens people."] = "Tome, {name}. Eu deixaria na sua porta, mas isso assusta as pessoas."
L["Take this, {name}. I'd offer my coat, but it's attached."] = "Tome, {name}. Te daria meu casaco, mas ele vem grudado."
L["Here, {name}. Chin up, hackles down. Words to live by."] = "Tome, {name}. Queixo erguido, pelo baixo. Lema de vida."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "A maldição nos une, {name}, mas Guilnéas nos une ainda mais."
L["No need to explain the ears to you, {name}."] = "Não preciso te explicar as orelhas, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "Pelo, neblina e chuva, {name}. Só quem é de Guilnéas entende os três."
L["Pack looks after pack, {name}. Always has."] = "A matilha cuida da matilha, {name}. Sempre cuidou."
L["Do you shed this badly too, {name}? Between us we could knit a third worgen."] = "Você também solta tanto pelo, {name}? Com o nosso dá pra tricotar outro worgen."
L["Two worgen, {name}. Somewhere, a cat's having a very bad day."] = "Worgen com worgen, {name}. Algum gato por aí está num dia péssimo."
L["Honestly, {name}, do you ever forget which form you left home in?"] = "Sério, {name}, você nunca esquece em que forma saiu de casa?"
L["Gilnean to Gilnean, {name}: the finest-mannered wolves in all Azeroth."] = "Coisa de Guilnéas, {name}: os lobos mais bem-educados de toda Azeroth."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "Regras da matilha, {name}: ninguém se perde e ninguém fala das pulgas."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "Uma matilha de novo, {name}. Nem sabia quanta falta isso me fazia."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "Eu farejo o perigo primeiro, {name}. É a única vantagem da maldição."
L["If I howl, {name}, it's a battle cry. Probably. Don't look at me like that."] = "Se eu uivar, {name}, é grito de guerra. Provavelmente. Não me olhe assim."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "Vá na frente, {name}. Eu vou trotando. É indigno, mas é bem mais rápido."
L["If I stop and stare at a wall, {name}, something's behind it. Or it's a wall."] = "Se eu parar e encarar uma parede, {name}, tem algo atrás dela. Ou é só parede."
L["Years on the Greymane Wall, {name}. Holding a line with you is a holiday."] = "Anos na Muralha de Greymane, {name}. Segurar a linha com você é férias."
L["After this, {name}, a proper cup of tea. Before this, a proper mauling."] = "Depois disso, {name}, uma boa xícara de chá. Antes, uma boa estraçalhada."
L["If I limp back, {name}, I'll make big sad eyes. Don't fuss. I'm fine."] = "Se eu voltar mancando, {name}, faço olhar de cachorro pidão. Ignore. Estou bem."
L["Short rest? I'll curl up, {name}, after three turns. The turns aren't optional."] = "Pausa? Eu me enrolo, {name}, depois de dar três voltas. Não são opcionais."
L["Stay together, {name}. I was a lone wolf once. Dreadful pay, nobody talks."] = "Todo mundo junto, {name}. Já fui lobo solitário. Paga mal e ninguém conversa."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "Noite de novo, {name}. Estou no meu melhor e no meu pior. Esta é a parte boa."
L["Look at that moon, {name}. Don't mind me; I'm not howling. Much."] = "Olha essa lua, {name}. Não liga pra mim; não estou uivando. Muito."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "Guilnéas à noite era neblina e passos, {name}. Hoje em dia, os passos sou eu."
L["Curfew in Gilneas was sundown, {name}. For good reason, as it turned out."] = "Em Guilnéas, o toque de recolher era ao pôr do sol, {name}. Por um bom motivo."
L["Something out there keeps rustling, {name}. I'm not going to look. I'm looking."] = "Tem algo farfalhando lá fora, {name}. Não vou olhar. Estou olhando."
L["Past dark, {name}: ears up, nose working, manners on. Two out of three will do."] = "No escuro, {name}: orelhas em pé, faro ligado, bons modos. Dois de três já basta."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "Bom dia, {name}. Teria levantado antes, mas o tapete da lareira estava tão quentinho."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "Cheiro de chuva hoje cedo, {name}. Tudo em Guilnéas tinha cheiro de chuva."
L["Up already, {name}? I've chased two rabbits. For exercise. Purely."] = "Já de pé, {name}? Eu já corri atrás de dois coelhos. Por exercício. Só isso."
L["Morning, {name}. Tea, toast, a shave. The shave takes rather longer now."] = "Bom dia, {name}. Chá, torrada, barba. A barba demora bem mais agora."
L["Morning, {name}. The birds woke me, so I woke the birds. It seemed only fair."] = "Bom dia, {name}. Os pássaros me acordaram; acordei os pássaros. Nada mais justo."
L["Morning, {name}. The squirrels are taunting me. Quickly, before I'm distracted."] = "Bom dia, {name}. Os esquilos estão me provocando. Rápido, antes que eu me distraia."
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka, {name}! Honra se paga com honra."
L["You give freely, {name}. I return the favour."] = "Você dá de graça, {name}. Retribuo o favor."
L["Orcs keep their thanks short, {name}. Thanks."] = "Orc agradece curto, {name}. Valeu."
L["Orcs return every blow twice, {name}. The kind ones too."] = "Orc devolve todo golpe em dobro, {name}. Os gentis também."
L["You helped me, I help you. Orc poetry, {name}. It doesn't rhyme."] = "Você me ajudou, eu te ajudo. Poesia orc, {name}. Não rima."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "Antigamente eu te pagaria com um javali, {name}. Isto dura mais."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "Dever favor coça mais que areia de Durotar, {name}. Pronto. Coceira resolvida."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "Coisa forte, {name}. Agora eu derrubo um kodo na luta. Você também."
L["Ambushed by kindness, {name}. No orc trains for that. Returned in full."] = "Emboscada de gentileza, {name}. Nenhum orc treina pra isso. Devolvo com juros."
L["Honour is a debt, {name}. Orcs pay on the spot, before we forget what for."] = "Honra é dívida, {name}. Orc paga na hora, antes de esquecer do quê."
L["An orc remembers a kindness like a scar, {name}: fondly, and for good."] = "Orc lembra de gentileza como de cicatriz, {name}: com carinho, e pra sempre."
L["I'd give you my axe, {name}, but we're not that close yet. Take this."] = "Te daria meu machado, {name}, mas ainda não temos intimidade. Pega isto."
L["Thanks, {name}. My wolf growled at you. That's how he says it."] = "Valeu, {name}. Meu lobo rosnou pra você. É o obrigado dele."
L["I've had gifts from shamans, chieftains and one lost kodo, {name}. Yours wins."] = "Já ganhei presente de xamã, de chefe e de um kodo perdido, {name}. O seu ganha."
L["We once took strength from demons, {name}. Yours comes on far better terms."] = "Já bebemos força de demônio, {name}. A sua vem com um contrato bem melhor."
L["The spirits saw that, {name}. My shaman says they approve. Of you, anyway."] = "Os espíritos viram isso, {name}. Meu xamã diz que aprovam. De você, pelo menos."
L["I'll carve that on my axe handle, {name}. Next to the notches. Thank you."] = "Vou gravar isso no cabo do machado, {name}. Do lado dos entalhes. Valeu."
L["A kindness, {name}? Hm. My face is doing something. I think it's a smile."] = "Uma gentileza, {name}? Hm. Minha cara está fazendo algo. Acho que é um sorriso."
L["In my clan a gift gets a bigger one back, {name}. Don't make me escalate."] = "No meu clã, presente volta maior, {name}. Não me faça subir a aposta."
L["Dabu, {name}. It is done."] = "Dabu, {name}. Está feito."
L["Hold still, {name}. Strength for the fight ahead."] = "Não se mexa, {name}. Força para a batalha que vem."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "Peça ajuda a um orc e você recebe, {name}. Peça sutileza e espere sentado."
L["Help, yes. Hugging, no. Hold still, {name}."] = "Ajuda, sim. Abraço, não. Não se mexe, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "Quer {buff}? Tem {buff}, {name}. Próximo."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "Não se assuste, {name}. Minha cara de ajudar é igualzinha à de brigar."
L["Short question, short answer, {name}: yes."] = "Pergunta curta, resposta curta, {name}: sim."
L["Work complete, {name}. I started out as a peon; the words never leave you."] = "Trabalho concluído, {name}. Comecei como peão; essas palavras nunca saem."
L["A challenge, {name}? Oh, a request. Close enough. I accept either way."] = "Um desafio, {name}? Ah, um pedido. Dá no mesmo. Aceito de qualquer jeito."
L["Yes, {name}. I was sharpening my axe, but it'll keep. It always keeps."] = "Sim, {name}. Eu estava afiando o machado, mas pode esperar. Sempre pode."
L["In the Valley of Honor this would cost you a duel, {name}. For you, a nod."] = "No Vale da Honra isto custaria um duelo, {name}. Pra você, um aceno."
L["Now, {name}? Now. Orcs never learned the word 'later'."] = "Agora, {name}? Agora. Orc não conhece a palavra 'depois'."
L["One {buff}, {name}. Orc style: fast, direct, a bit too hard."] = "{buff}, {name}. Estilo orc: rápido, direto e meio forte demais."
L["Stand still, {name}. I aim this like a throwing axe, and I rarely miss."] = "Não se mexe, {name}. Miro isto feito machado de arremesso, e raramente erro."
L["Lok'tar, {name}. It means 'victory'. Today it also means 'yes'."] = "Lok'tar, {name}. Quer dizer 'vitória'. Hoje também quer dizer 'sim'."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Lok'tar ogar, {name}! Leve isto para a batalha. Briga de taverna também conta."
L["Blood and thunder, {name}! Go and earn your glory."] = "Sangue e trovão, {name}! Vá conquistar sua glória."
L["Among orcs, {name}, making you stronger is how we say we like you."] = "Entre orcs, {name}, te deixar mais forte é dizer 'gosto de você'."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "Orc dando presente sem pedirem? Bico calado, {name}. Pega mal."
L["I was told to be more diplomatic, {name}. This is me being diplomatic."] = "Me pediram mais diplomacia, {name}. Isto sou eu com diplomacia."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "Vai bater em alguma coisa por mim, {name}. Ou tacar fogo. Orc não é exigente."
L["Don't thank me, {name}. Just win, and do it loudly."] = "Não agradeça, {name}. Só vença, e fazendo barulho."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "Eu faria um discurso, {name}, mas é quase tudo grito. Só pega."
L["You looked like you needed an orc, {name}. Everybody does, sooner or later."] = "Parecia que você precisava de um orc, {name}. Todo mundo precisa, cedo ou tarde."
L["'Strike first,' Grom always said, {name}. So: here, before you could ask."] = "'Ataque primeiro', dizia Grom, {name}. Então pega, antes de você pedir."
L["Take it, {name}. A grunt who walks past a comrade gets a talking-to. From me."] = "Pega, {name}. Soldado que passa reto por um camarada leva bronca. Minha."
L["Frostwolves share the hunt, {name}. I caught nothing today, so share this."] = "O clã Lobo do Gelo divide a caça, {name}. Hoje não cacei nada; divido isto."
L["Walk the Durotar way, {name}: head up, sun on your neck, scorpid underfoot."] = "À moda de Durotar, {name}: cabeça erguida, sol na nuca, escorpídeo sob os pés."
L["Here, {name}. The spirits love generosity. My axe says nothing; it sulks."] = "Pega, {name}. Os espíritos amam quem dá. Meu machado não diz nada; está de bico."
L["Orcs give two things freely, {name}: advice and this. Skip the advice."] = "Orc dá duas coisas de graça, {name}: conselho e isto. Pula o conselho."
L["The Barrens don't end, {name}. They just get more zhevra. Take this."] = "Os Sertões não acabam, {name}. Só vão tendo mais zhevra. Pega isto."
L["Strength for your arm, {name}. The honour, I see, you brought yourself."] = "Força pro seu braço, {name}. A honra, pelo visto, já veio com você."
L["My wolf wanted you to have his bone, {name}. I talked him down to this."] = "Meu lobo queria te dar o osso dele, {name}. Negociei e ficou nisto."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka, {name}! O sangue dos clãs corre forte em você."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "Orc, {name}! Até que enfim alguém que grita no meu volume."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "Lobo do Gelo, Brado Guerreiro ou Rocha Negra, {name}: é tudo briga de família."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "Entre orcs, palavras não são necessárias, {name}. Ótimo. Acabaram as minhas."
L["Green skin or brown, {name}, it's the same stubborn blood."] = "Pele verde ou marrom, {name}, é o mesmo sangue teimoso."
L["Two orcs, {name}, and nobody's shouted yet. The shamans will call it an omen."] = "Orc com orc, {name}, e ninguém gritou ainda. Os xamãs vão dizer que é presságio."
L["Our clans probably feuded once, {name}. Everybody's did. Let's call it settled."] = "Nossos clãs devem ter brigado um dia, {name}. Todos brigaram. Assunto encerrado."
L["Between orcs, {name}, 'victory or death' is just how we say 'see you later'."] = "Entre orcs, {name}, 'vitória ou morte' é só o nosso 'até mais'."
L["Your tusks and mine have seen worse days, {name}. This is a better one."] = "Suas presas e as minhas já viram dias piores, {name}. Hoje é dos melhores."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "O plano, {name}: a gente bate. Dúvidas? Não? Bom plano."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "Bando de guerra de verdade, {name}: barulhento, bravo e do mesmo lado, pra variar."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "Fique com o bando, {name}. A união faz a força. E o machado também."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "Se você cair, {name}, eu te carrego. Reclamando o caminho todo, mas carrego."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "Lute bem, {name}, e hoje à noite você divide nossa fogueira. E nossas bravatas."
L["Nobody runs, {name}. Walking briskly away is allowed. Barely."] = "Ninguém foge, {name}. Sair andando rápido é permitido. Por pouco."
L["I'll go first, {name}. I have the thickest skull here, and I'm proud of it."] = "Eu vou na frente, {name}. Tenho a cabeça mais dura daqui, e com orgulho."
L["When the war drums start, {name}, charge. We have no drums. I'll hum."] = "Quando os tambores rufarem, {name}, avance. Não temos tambor. Eu cantarolo."
L["Watch my back, {name}. The front I can see; that's the part I hit."] = "Cuida das minhas costas, {name}. A frente eu vejo; é nela que eu bato."
L["One clan today, {name}: the Clan of Whoever Showed Up. Finest there is."] = "Um clã só hoje, {name}: o Clã de Quem Apareceu. O melhor que existe."
L["Anything big comes through that door, {name}, it's mine. Anything bigger, ours."] = "Se passar algo grande por aquela porta, {name}, é meu. Maior que isso, é nosso."
L["Scars are stories, {name}. Let's all come out of this with short ones."] = "Cicatriz é história, {name}. Que todo mundo saia daqui com uma curtinha."
L["Old chieftains had war councils, {name}. We have me pointing at things."] = "Antigamente havia conselho de guerra, {name}. Hoje tem eu apontando pras coisas."
L["If I charge early, {name}, it isn't impatience. It's tradition."] = "Se eu avançar antes da hora, {name}, não é impaciência. É tradição."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "Agradeço, {name}. Aqueceria meu coração, se ele ainda batesse."
L["Such warmth, for one so cold? Returned in full, {name}."] = "Tanto calor para alguém tão frio? Devolvo tudo, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "Agradeço, {name}. Eu coraria, mas o sangue parou de chegar no rosto."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "Gratidão eterna, {name}. No meu caso, é literal."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "Muita gentileza, {name}. Você me promoveu de 'cadáver' a 'cadáver bem-disposto'."
L["You've added years to my life, {name}. Shame it already ended."] = "Você acrescentou anos à minha vida, {name}. Pena que ela já acabou."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "Essa eu senti, {name}, e hoje em dia não sinto quase nada. Tome, sinta esta."
L["I'd shake your hand, {name}, but I'm not sure mine is still attached."] = "Apertaria sua mão, {name}, mas não sei se a minha ainda está presa."
L["Thank you, {name}. I'd send a bat with a proper note, but they eat the notes."] = "Agradeço, {name}. Mandaria um morcego com um bilhete, mas eles comem os bilhetes."
L["You've spoiled me, {name}. The pleasant kind of spoiled, for once."] = "Você me estragou de mimo, {name}. Pela primeira vez, do jeito bom."
L["The last gift I got was the plague, {name}. Yours is a big improvement."] = "O último presente que ganhei foi a praga, {name}. O seu é bem melhor."
L["Thank you, {name}. Nothing this fresh has touched me since Lordaeron fell."] = "Agradeço, {name}. Nada tão fresco me tocou desde a queda de Lordaeron."
L["Sylvanas says we repay every debt, {name}. She rarely means the nice ones."] = "Sylvanas diz que pagamos toda dívida, {name}. Raramente ela fala das boas."
L["My posture's improved, {name}. It's been slumping since the Third War. Thanks."] = "Minha postura melhorou, {name}. Estava caída desde a Terceira Guerra. Agradeço."
L["Repaid at once, {name}. We Forsaken never carry debts. They rot."] = "Pago na hora, {name}. Renegado não carrega dívida. Apodrece."
L["Thank you, {name}. Unpaid debts in Undercity end up in the canal. Not yours."] = "Agradeço, {name}. Dívida não paga na Cidade Baixa acaba no canal. A sua, não."
L["Thank you, {name}. I'll keep this somewhere safe. My ribcage has room."] = "Agradeço, {name}. Vou guardar em lugar seguro. Minha caixa torácica tem espaço."
L["Thank you, {name}. I'd bake you something, but everything I touch goes off."] = "Agradeço, {name}. Faria um bolo pra você, mas tudo que eu toco estraga."
L["I'll mention you to the Dark Lady, {name}. She won't care, but I will."] = "Vou falar de você à Dama Sombria, {name}. Ela não vai ligar, mas eu ligo."
L["Kindness returned, {name}. Even the flies around me look impressed."] = "Gentileza devolvida, {name}. Até minhas moscas parecem impressionadas."
L["In all my years with the Scourge, nobody once said this, {name}. Thank you."] = "Em todos os meus anos no Flagelo, ninguém nunca disse isto, {name}. Agradeço."
L["I'll drink to you tonight, {name}. It all leaks out, but it's the thought."] = "Vou brindar a você hoje, {name}. Vaza tudo, mas o que vale é a intenção."
L["The Dark Lady says trust no gift, {name}. I'll risk it, and send one back."] = "A Dama Sombria manda desconfiar de presentes, {name}. Arrisco e devolvo um."
L["Thank you, {name}. You've made my list of reasons to keep going. It's short."] = "Agradeço, {name}. Você entrou na minha lista de motivos pra continuar. É curta."
L["Thank you, {name}. No contract, no fine print. Varimathras should take notes."] = "Agradeço, {name}. Sem contrato, sem letras miúdas. Varimathras devia anotar."
L["Grave dirt and gratitude, {name}: all I own. You'll prefer the gratitude."] = "Terra de cova e gratidão, {name}: tudo que tenho. Você vai preferir a gratidão."
L["Thank you, {name}. Eternity drags; this was the best bit of the decade."] = "Agradeço, {name}. A eternidade se arrasta; isto foi o melhor da década."
L["Faranell would want notes on that reaction, {name}. I'll just return it."] = "Faranell ia querer estudar essa reação, {name}. Eu só devolvo."
L["Thank you, {name}. Lordaeron had manners once. Glad somebody kept them."] = "Agradeço, {name}. Lordaeron já teve boas maneiras. Que bom que alguém guardou."
L["The Deathguard would salute you, {name}, but it's hard on their arms. Thanks."] = "Os guardas de Tirisfal bateriam continência, {name}, mas os braços caem. Agradeço."
L["I'd have Lordaeron's bells rung for you, {name}, but they only do funerals now."] = "Os sinos de Lordaeron tocariam por você, {name}, mas hoje só dobram por finados."
L["Thank you, {name}. Next time I'm in Brill, I'll name a pumpkin after you."] = "Agradeço, {name}. Na próxima vez em Brill, vou batizar uma abóbora com seu nome."
L["Thank you, {name}. My afterlife had rather let itself go. You've tidied it up."] = "Agradeço, {name}. Minha pós-vida andava bem desleixada. Você deu uma arrumada."
L["Certainly, {name}. Try not to die. It's overrated."] = "Certamente, {name}. Tente não morrer. É superestimado."
L["You need only ask, {name}. The dead are patient."] = "Basta pedir, {name}. Os mortos são pacientes."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "Peça um favor aos mortos, {name}. Raramente temos outros planos."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "Certamente, {name}. Afaste-se; odiaria deixar cair algum pedaço em você."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "Um momento, {name}. O rigor mortis judia da mão que lança feitiços."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "Bom me pedirem algo, {name}, além do caminho pro cemitério."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "Com prazer, {name}. Me distrai do cheiro. O meu, no caso."
L["Certainly, {name}. Hold still. My aim drifts when my eye does."] = "Claro, {name}. Não se mexa. Quando meu olho cai, a mira cai junto."
L["In Undercity nobody says please, {name}. Mostly they gurgle. Here you are."] = "Na Cidade Baixa ninguém pede por favor, {name}. O povo só gorgoleja. Tome."
L["Just {buff}, {name}? The apothecaries always want a sample too."] = "Só {buff}, {name}? Os boticários sempre pedem uma amostra também."
L["I always rise when called, {name}. Unfortunate history. Here you are."] = "Quando me chamam, eu me levanto, {name}. Histórico infeliz. Tome."
L["Anything for you, {name}. Within reason, and what's left of mine."] = "Tudo por você, {name}. Dentro do razoável, e do que me resta de razão."
L["Of course, {name}. I'd say 'over my dead body', but that's been tried."] = "Claro, {name}. Eu diria 'só por cima do meu cadáver', mas isso já foi tentado."
L["Right away, {name}. The dead don't dawdle. We shamble with purpose."] = "Agora mesmo, {name}. Os mortos não enrolam. Cambaleamos com propósito."
L["Of course, {name}. Free will is a gift. I spend mine on things like this."] = "Claro, {name}. O livre-arbítrio é um presente. Gasto o meu com coisas assim."
L["Coming up, {name}. Quicker than a bat out of Undercity, and it doesn't bite."] = "Saindo, {name}! Mais rápido que morcego da Cidade Baixa, e sem morder."
L["Of course, {name}. After a winter in the Plaguelands, this counts as a holiday."] = "Claro, {name}. Depois de um inverno nas Terras Pestilentas, isto é quase férias."
L["{buff}, {name}? Sorry, my good ear's in my other pocket."] = "{buff}, {name}? Perdão, minha orelha boa está no outro bolso."
L["Of course, {name}. No sleep, no meals, no plans. I'm extremely available."] = "Claro, {name}. Sem sono, sem refeições, sem planos. Estou extremamente disponível."
L["I'm dying to help, {name}. Figure of speech. I've done the real one."] = "Morro de vontade de ajudar, {name}. É modo de dizer. Morrer mesmo, já morri."
L["Stay among the living a little longer, {name}."] = "Fique entre os vivos mais um pouco, {name}."
L["Take this, {name}. The grave can wait."] = "Tome, {name}. O túmulo pode esperar."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "Eu clinicava em Lordaeron, {name}. O hábito custou mais a morrer do que eu."
L["No charge, {name}. The apothecaries would have made you sign something."] = "Sem custo, {name}. Os boticários te fariam assinar alguma coisa."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "Um presente do além-túmulo, {name}. Relaxa, eu lavei."
L["Every body needs a little help, {name}. Mine mostly needs stitches."] = "Todo corpo precisa de ajuda, {name}. O meu precisa mais é de pontos."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "Já vi onde os heróis vão parar, {name}. Eu moro lá. Tome."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "Tome, {name}. Aprendi na marra: caixão não tem gaveta."
L["Take this, {name}. It's the only thing I own that isn't slightly damp."] = "Tome, {name}. É a única coisa minha que não está meio úmida."
L["Hold on to yourself, {name}. Trust me, the pieces are hard to find later."] = "Não perca a cabeça, {name}. Confie em mim: depois é difícil de achar."
L["Take this, {name}. The Plaguelands are full of people who didn't."] = "Tome, {name}. As Terras Pestilentas estão cheias de gente que não tomou."
L["A small kindness, {name}. My bat got the last one, and it never said thanks."] = "Uma gentileza, {name}. Meu morcego ganhou a última e nem agradeceu."
L["Tirisfal fog gets into everything, {name}. So does this, but pleasantly."] = "A névoa de Tirisfal entra em tudo, {name}. Isto também, mas é agradável."
L["Here, {name}. I kept it cool for you. I keep everything cool. Can't help it."] = "Tome, {name}. Guardei geladinho pra você. Comigo tudo fica gelado. Não tem jeito."
L["I've outlived everyone I knew, {name}. I'd rather not outlive you. Take this."] = "Sobrevivi a todos que conheci, {name}. Prefiro não sobreviver a você. Tome."
L["Pardon me, {name}. I'm told I lurk. I'm trying to lurk helpfully."] = "Com licença, {name}. Dizem que eu espreito. Tento espreitar com utilidade."
L["Out of my own pocket, {name}. What's left of the pocket, anyway."] = "Do meu próprio bolso, {name}. Do que sobrou do bolso, pelo menos."
L["I've already had the worst day there is, {name}. Let's spare you yours."] = "Eu já tive o pior dia que existe, {name}. Vamos poupar você do seu."
L["Wind's off the Plaguelands, {name}. Take this, and breathe through your mouth."] = "Vento das Terras Pestilentas, {name}. Tome isto e respire pela boca."
L["The crows have been watching you, {name}. Let's disappoint them."] = "Os corvos estão de olho em você, {name}. Vamos decepcioná-los."
L["Here, {name}. Tirisfal grows nothing but pumpkins and grudges. This is neither."] = "Tome, {name}. Tirisfal só dá abóbora e rancor. Isto não é nenhum dos dois."
L["Take this, {name}. The only thing in Undercity that needn't be boiled first."] = "Tome, {name}. A única coisa na Cidade Baixa que não precisa ferver antes."
L["Eternity is long, {name}, and I've spent a fair bit of it practising this."] = "A eternidade é longa, {name}, e passei boa parte dela treinando isto."
L["For the road, {name}. Undercity-made, so do keep it away from open flame."] = "Pra viagem, {name}. Feito na Cidade Baixa, então mantenha longe do fogo."
L["Take this, {name}. It's odourless, which I'm told makes it my best feature."] = "Tome, {name}. Não tem cheiro nenhum, e dizem que é a melhor coisa em mim."
L["Forsaken are famously patient, {name}. I just couldn't wait to give you this."] = "Renegados são famosos pela paciência, {name}. Mas não aguentei esperar pra te dar isto."
L["No strings attached, {name}. I cut mine when the Lich King lost his grip."] = "Sem amarras, {name}. Cortei as minhas quando o Lich Rei perdeu o controle."
L["Fresh from Tirisfal, {name}. Well, fresh for Tirisfal."] = "Fresquinho de Tirisfal, {name}. Bom, fresquinho para Tirisfal."
L["Take this, {name}. I was saving it, but I'm bad at keeping things. Look at me."] = "Tome, {name}. Eu estava guardando, mas não sei conservar nada. Olhe para mim."
L["We Forsaken must look after each other, {name}."] = "Nós, Renegados, cuidamos uns dos outros, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "Cá entre defuntos, {name}, sua conservação é impecável."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "Perdeu um dedo, {name}? Tenho um sobrando. Renegado divide."
L["Is your jaw clicking too, {name}, or is that just me?"] = "Sua mandíbula também estala, {name}, ou é só a minha?"
L["Victory for Sylvanas, {name}. A small one this time, but it's ours."] = "Vitória para Sylvanas, {name}. Pequena desta vez, mas é nossa."
L["Brill or Deathknell, {name}? We all woke up somewhere. I got the damp crypt."] = "Onde você despertou, {name}? Cada um acordou num canto. Eu peguei a cripta úmida."
L["When the Scourge comes calling, {name}, we won't be home. Not ever again."] = "Quando o Flagelo bater à porta, {name}, não estaremos em casa. Nunca mais."
L["The Bulwark still holds, {name}, and so do we. Held together, but holding."] = "O Baluarte resiste, {name}, e nós também. Remendados, mas firmes."
L["Lordaeron raised us twice, {name}: once as children, once as Forsaken."] = "Lordaeron nos pôs de pé duas vezes, {name}: como crianças e como Renegados."
L["Somewhere in Northrend, {name}, the Lich King is sulking about us. Good."] = "Lá em Nortúndria, {name}, o Lich Rei está emburrado com a gente. Ótimo."
L["The Dark Lady needs us whole, {name}. Near enough will do."] = "A Dama Sombria nos quer inteiros, {name}. Quase inteiros já serve."
L["You smell of Tirisfal, {name}. From one of us, that's a compliment."] = "Você tem cheiro de Tirisfal, {name}. Vindo de um de nós, é um elogio."
L["We've both got forever, {name}. Let's not spend it all waiting for the lift."] = "Temos a eternidade, {name}. Não vamos gastá-la toda esperando o elevador."
L["One Forsaken to another, {name}: the sewer shortcut is not a shortcut."] = "De Renegado pra Renegado, {name}: o atalho do esgoto não é atalho."
L["If the Deathguard ask, {name}, we're on patrol. A very, very slow patrol."] = "Se a guarda perguntar, {name}, é patrulha. Uma patrulha muito, muito lenta."
L["Our kind don't get many kindnesses, {name}. Let's keep them in the family."] = "Gente como nós recebe pouca gentileza, {name}. Vamos mantê-la na família."
L["The bats in the Trade Quarter know us both by now, {name}. That's fame, nearly."] = "Os morcegos do bairro comercial já nos conhecem, {name}. É quase fama."
L["Keep the faith, {name}. In each other, I mean. It answers more often."] = "Tenha fé, {name}. Um no outro, quero dizer. Responde com mais frequência."
L["The dead look after the dead, {name}. The living could learn a thing or two."] = "Morto cuida de morto, {name}. Os vivos bem que podiam aprender."
L["We've both seen the inside of a grave, {name}. Dreadful service. No view."] = "Nós dois já vimos um túmulo por dentro, {name}. Serviço péssimo. Sem vista."
L["Stay alive, {name}. Undercity's housing list is already very long."] = "Não morra, {name}. A fila de moradia da Cidade Baixa já está enorme."
L["If I fall down, {name}, give it a minute. Old habit."] = "Se eu cair, {name}, espera um minuto. Mania antiga."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "Eu vou na frente, {name}. O que de pior pode acontecer? De novo?"
L["Keep upwind of me, {name}. It's better for morale."] = "Fique longe do meu cheiro, {name}. É melhor pro moral."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "No último grupo em que entrei, {name}, acordei numa cripta. Vamos melhorar isso."
L["Anything that bites, {name}, point it at me. There's nothing left worth eating."] = "O que morder, {name}, mande pra mim. Não sobrou nada que valha a pena comer."
L["Spare the heals for the others, {name}. I run on spite and embalming fluid."] = "Guarde a cura para os outros, {name}. Eu funciono à base de rancor e formol."
L["If this goes badly, {name}, don't worry. I know the way back. Intimately."] = "Se der errado, {name}, relaxe. Conheço o caminho de volta. Intimamente."
L["I've fought the Scourge from both sides, {name}. This side's better company."] = "Já estive dos dois lados do Flagelo, {name}. Deste lado a companhia é melhor."
L["Stay close, {name}. I'm the one who won't scream at the ghouls. Old neighbours."] = "Fique perto, {name}. Eu não vou gritar com os carniçais. Velhos vizinhos."
L["I've walked the Plaguelands at night, {name}. This is a stroll by comparison."] = "Já andei pelas Terras Pestilentas à noite, {name}. Isto aqui é um passeio."
L["The corpse at the back is me, {name}. Please don't loot it."] = "O cadáver lá atrás sou eu, {name}. Por favor, não saqueie."
L["Stay together, {name}. It's easier than putting somebody back together."] = "Não se separem, {name}. É mais fácil que juntar os pedaços de alguém depois."
L["Don't wait for me, {name}. I shamble, but I shamble forever. I'll catch up."] = "Não me espere, {name}. Eu cambaleio, mas cambaleio para sempre. Eu alcanço."
L["Keep the torches clear of me, {name}. I'm old, dry and very flammable."] = "Tochas longe de mim, {name}. Tenho idade, pele seca e sou muito inflamável."
L["Don't check me for a pulse after, {name}. It only worries people."] = "Depois, não confira meu pulso, {name}. Só deixa as pessoas preocupadas."
L["Mind the green puddles, {name}. I've seen what they do. I'm what they do."] = "Cuidado com as poças verdes, {name}. Sei o que elas fazem. Eu sou o que elas fazem."
L["Send anything scary to me, {name}. I've been dead; it's got nothing."] = "Mande o que assustar pra mim, {name}. Já morri; nada mais me assusta."
L["Stick together, {name}. The apothecaries pay well for strays."] = "Não se dispersem, {name}. Os boticários pagam bem por desgarrados."
L["If this ends underwater, {name}, don't mind me. Breathing's optional now."] = "Se isso acabar debaixo d'água, {name}, não se preocupe. Respirar agora é opcional."
L["The Dark Lady trusts no one, {name}. I've made an exception for this party."] = "A Dama Sombria não confia em ninguém, {name}. Abri uma exceção para este grupo."
L["When we win, {name}, drinks at the Gallows' End in Brill. My treat. Your risk."] = "Quando vencermos, {name}, bebidas na taverna de Brill. Eu pago. Você arrisca."
L["Don't mind the bats, {name}. They follow me everywhere. They think I'm a cave."] = "Não ligue para os morcegos, {name}. Me seguem pra todo lado. Acham que sou uma caverna."
L["I'll watch the rear, {name}. Nothing sneaks up on someone who can't blink."] = "Eu vigio a retaguarda, {name}. Ninguém surpreende quem não pisca."
L["Any blood on the floor after, {name}, it isn't mine. I stopped carrying any."] = "Se tiver sangue no chão depois, {name}, não é meu. Parei de carregar."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "Os mortos têm horários péssimos, {name}. Bom ter companhia, pra variar."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "Meia-noite, {name}: a melhor hora pra estar de pé quando não se devia."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "Os vivos dormem, {name}. Nós, Renegados, chamamos isso de plantão tranquilo."
L["Late, {name}? In Undercity, this is lunchtime."] = "Tarde, {name}? Na Cidade Baixa, isto é hora do almoço."
L["This is the hour the Scourge used to walk, {name}. Now it's ours."] = "Nesta hora o Flagelo andava por aí, {name}. Agora ela é nossa."
L["Night, {name}. The one time nobody can tell I'm pale."] = "Noite, {name}. A única hora em que ninguém nota minha palidez."
L["Dark as the Undercity, {name}. Finally, some proper lighting."] = "Escuro como a Cidade Baixa, {name}. Enfim, uma iluminação decente."
L["Fog, moonlight and a hint of mildew, {name}. Proper Tirisfal weather."] = "Névoa, luar e um toque de mofo, {name}. Clima típico de Tirisfal."
L["The banshees start singing about now, {name}. Relax. They're only practising."] = "As banshees começam a cantar agora, {name}. Relaxe. É só ensaio."
L["Stars over Tirisfal, {name}. The one thing up there that never rotted."] = "Estrelas sobre Tirisfal, {name}. A única coisa lá em cima que nunca apodreceu."
L["Past midnight, {name}. The graveyards are quiet. The good ones, anyway."] = "Passa da meia-noite, {name}. Os cemitérios estão quietos. Os bons, pelo menos."
L["An owl just saw me and left, {name}. They're sensible birds."] = "Uma coruja me viu e foi embora, {name}. Aves sensatas."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "Já amanheceu, {name}? Virei a noite. E a década passada inteira."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "O sol nasceu, {name}. Vou ficar na sombra, se não se importa. As coisas descascam."
L["Early start, {name}. The dead never sleep in. Or at all, really."] = "Começando cedo, {name}. Morto não dorme até tarde. Nem dorme, na verdade."
L["Sunrise, {name}. My least favourite colour. I'm off to find some shade."] = "Nascer do sol, {name}. Minha cor menos favorita. Vou procurar uma sombra."
L["Dawn over Tirisfal, {name}: grey, then slightly less grey. Glorious."] = "Amanhecer em Tirisfal, {name}: cinza, depois um pouco menos cinza. Glorioso."
L["Morning, {name}. The Gallows' End porridge moved again. Have this instead."] = "Bom dia, {name}. O mingau da taverna se mexeu de novo. Fique com isto."
L["The roosters in Brill still crow, {name}. Nobody's had the heart to tell them."] = "Os galos de Brill ainda cantam, {name}. Ninguém teve coração pra contar a eles."
L["Morning, {name}. The Deathguard change shifts now. They just turn round."] = "Bom dia, {name}. A guarda troca de turno agora. Eles só dão meia-volta."
L["Take the lift slowly, {name}. The last man who rushed it is still coming down."] = "Vá devagar no elevador, {name}. O último apressado ainda está descendo."
L["Undercity has it all, {name}: a bank, an inn, and opinions in the sewers."] = "A Cidade Baixa tem de tudo, {name}: banco, estalagem e opiniões nos esgotos."
L["Even the rats bow to the Dark Lady here, {name}. Take this before one asks."] = "Aqui até os ratos se curvam à Dama Sombria, {name}. Tome antes que um peça."
L["Mind the canal, {name}. It's green for a reason, and the reason isn't moss."] = "Cuidado com o canal, {name}. É verde por um motivo, e o motivo não é musgo."
L["Undercity's lovely this time of year, {name}. It's always this time of year."] = "A Cidade Baixa é linda nesta época do ano, {name}. É sempre esta época do ano."
L["We moved into Lordaeron's cellar, {name}, and kept the good silver."] = "Nos mudamos para o porão de Lordaeron, {name}, e ficamos com a prataria boa."
L["The Royal Quarter's that way, {name}. Bow low; the banshees keep score."] = "O bairro real é por ali, {name}. Curve-se bem; as banshees dão nota."
L["The bat handler swears they're friendly, {name}. Take this before you test it."] = "O tratador de morcegos jura que são mansos, {name}. Tome isto antes de testar."
L["Magic Quarter's that way, {name}. The glowing puddles aren't for drinking."] = "O bairro mágico é por ali, {name}. As poças brilhantes não são pra beber."
L["The throne room's just upstairs, {name}. Nobody sits in it. Bad memories."] = "O trono fica logo lá em cima, {name}. Ninguém se senta nele. Más lembranças."
L["Most folk greet a Forsaken with holy water, {name}. You're a welcome change."] = "A maioria recebe um Renegado com água benta, {name}. Você é uma mudança bem-vinda."
L["Few stop for a Forsaken, {name}. You did, and I noticed. Thank you."] = "Poucos param por um Renegado, {name}. Você parou, e eu reparei. Agradeço."
L["Contrary to rumour, {name}, not everything a Forsaken hands out is a plague."] = "Ao contrário do boato, {name}, nem tudo que um Renegado distribui é praga."
L["Forsaken can't be charmed, {name}, they say. Asking nicely works, though."] = "Dizem que Renegado não se deixa encantar, {name}. Mas pedir com educação funciona."
L["Take this instead of small talk, {name}. Mine tends to unsettle people."] = "Tome isto no lugar de conversa fiada, {name}. A minha costuma assustar."
L["They say the Forsaken have no friends, {name}. I'm recruiting."] = "Dizem que os Renegados não têm amigos, {name}. Estou recrutando."
L["Take this, {name}. If anyone asks, the Forsaken were perfectly charming."] = "Tome, {name}. Se perguntarem, os Renegados foram um encanto."
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "Não morra, {name}. Já testei a alternativa e não recomendo."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "A Mãe Terra viu sua bondade, {name}. Ela me cutucou. Com força."
L["Thank you, {name}. May the winds guide you."] = "Agradeço, {name}. Que os ventos te guiem."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "Agradeço, {name}. Isso me comoveu, e mover um tauren não é fácil."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "É uma subida longa até o coração de um tauren, {name}. Você chegou."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "Senti isso do chifre ao casco, {name}. Retribuo, do casco ao chifre."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "Presente dado é semente plantada, {name}. Aqui está a colheita."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "Isso merece um banquete, {name}. O banquete pode esperar; {buff}, não."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "Agradeço, {name}. Se um dia precisar de uma parede pra se esconder, estou livre."
L["I'd dance for joy, {name}, but last time Bloodhoof lost a roof. This instead."] = "Eu dançaria de alegria, {name}, mas da última vez Casco Sangrento perdeu um telhado."
L["Returned faster than a wind rider, {name}, and with much less screeching."] = "Retribuído mais rápido que uma rota de voo, {name}, e com bem menos guincho."
L["Returned, {name}. The quilboar never learned to give back, and look at them."] = "Retribuído, {name}. Os javalenos nunca aprenderam a retribuir, e olhe só pra eles."
L["Thank you, {name}. My ancestors are all nodding. It's a great deal of nodding."] = "Agradeço, {name}. Meus ancestrais estão todos assentindo. É muita cabeça balançando."
L["In Mulgore we return a gift before the grass under it grows back, {name}."] = "Em Mulgore, presente se retribui antes que a grama cresça de novo, {name}."
L["Thank you, {name}. I'll name my next kodo calf after you. They're lovely."] = "Agradeço, {name}. Vou dar seu nome ao meu próximo filhote de kodo. São uns amores."
L["Kindness is rarer than shade in the Barrens, {name}. Here's some back."] = "Gentileza é mais rara que sombra nos Sertões, {name}. Aqui vai um pouco de volta."
L["I'll carve this on a totem, {name}. Tauren carve slowly; expect it by spring."] = "Vou entalhar isto num totem, {name}. Tauren entalha devagar; fica pronto na primavera."
L["Folk give directions by me, {name}: 'left at the tauren.' You gave me a gift."] = "Me usam de referência, {name}: 'esquerda no tauren.' Você me deu um presente."
L["Cairne taught us to honour every kindness, {name}. I'd been hoping for one."] = "Cairne nos ensinou a honrar toda gentileza, {name}. Eu estava torcendo por uma."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "Claro, {name}. Cabeça erguida e fique em paz. A parte da altura é comigo."
L["Ask and it is given, {name}. The herd shares what it has."] = "Pediu, está dado, {name}. A manada divide o que tem."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "Claro, {name}. Um passo pra trás; faço isso com o corpo todo."
L["Gladly, {name}. Mind the tail."] = "Com prazer, {name}. Cuidado com a cauda."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "A Mãe Terra dá sem pedir nada, {name}, e seus filhos maiores também."
L["Gladly, {name}. Tauren are slow to anger and quick to help. Quick-ish."] = "Com prazer, {name}. Tauren custa a se irritar e corre pra ajudar. Bom, trota."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "Recusar, {name}? Meus ancestrais nunca me deixariam esquecer."
L["Of course, {name}. A tauren says yes the way the plains grow grass: easily."] = "Claro, {name}. Tauren diz sim como a planície dá grama: sem esforço."
L["Of course, {name}. One moment; my hands are big and the spell is small."] = "Claro, {name}. Um momento; minhas mãos são grandes e o feitiço é pequeno."
L["After a season herding kodo, {name}, a polite request is a holiday. Here."] = "Depois de uma estação tocando kodos, {name}, pedido educado é feriado. Tome."
L["The Earth Mother says share, {name}. My stomach says lunch. She outranks it."] = "A Mãe Terra diz: divida, {name}. Minha barriga diz: almoço. Ela manda mais."
L["Of course, {name}. You get the help and a tauren proverb. Proverb: hold still."] = "Claro, {name}. Você ganha a ajuda e um provérbio tauren. Provérbio: não se mexa."
L["Spirits of the plains, lend me a hand. ...Ah, I have two. Here, {name}."] = "Espíritos da planície, me deem uma mão. ...Ah, eu tenho duas. Tome, {name}."
L["Magatha would want a favour for it, {name}. Baine would just say yes. So: yes."] = "Magatha cobraria um favor, {name}. Baine só diria sim. Então: sim."
L["Hold still, {name}. I've practised on kodo, and they're far less polite."] = "Não se mexa, {name}. Treinei com kodos, e eles são bem menos educados."
L["Of course, {name}. A shu'halo never refuses a traveller. Or a second helping."] = "Claro, {name}. Um shu'halo nunca recusa um viajante. Nem um segundo prato."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "Ande com a Mãe Terra, {name}. Ela está em toda parte; impossível se perder."
L["May An'she light your path, {name}."] = "Que An'she ilumine seu caminho, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "Você parecia precisar de um ombro amigo, {name}. O meu é enorme."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "Tome, {name}. A Mãe Terra me daria bronca se eu passasse direto."
L["Tread lightly, {name}. Take it from someone who never has."] = "Pise leve, {name}. Palavra de quem nunca conseguiu."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "O vento disse que você passaria por aqui, {name}. O vento é muito fofoqueiro."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "Tome, {name}. Emprestaria meu kodo também, mas ele é menos generoso que eu."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "Os shu'halo dizem: carregue o que puder pelos outros, {name}. Eu posso muito."
L["Take this, {name}. If the centaur trouble you, say Thunder Bluff sends regards."] = "Tome, {name}. Se centauros te incomodarem, diga que o Penhasco do Trovão manda lembranças."
L["Here, {name}. Plainstriders run from me for no reason at all. You needn't."] = "Tome, {name}. As aves da planície fogem de mim sem motivo algum. Você não precisa."
L["For you, {name}. Visit Mulgore sometime. The grass is soft and nobody hurries."] = "Pra você, {name}. Visite Mulgore um dia. A grama é macia e ninguém tem pressa."
L["Here, {name}. Grandmother blessed travellers and fed them. I'm out of bread."] = "Tome, {name}. Minha avó abençoava viajantes e os alimentava. Estou sem pão."
L["The spirits asked me to mind you, {name}. I said yes before they'd finished."] = "Os espíritos pediram que eu cuidasse de você, {name}. Disse sim antes de terminarem."
L["Here, {name}. Better a gift than a war stomp. Both leave an impression."] = "Tome, {name}. Melhor um presente que uma pisada de guerra. Os dois deixam marca."
L["Here, {name}. Tauren leave the world a little better, and a little trampled."] = "Tome, {name}. Tauren deixam o mundo um pouco melhor, e um pouco pisoteado."
L["You look weary, {name}. The Earth Mother would offer a nap. I offer this."] = "Cara de cansaço, {name}. A Mãe Terra ofereceria um cochilo. Eu ofereço isto."
L["Sunwalkers call it a blessing, hunters luck, {name}. Tauren call it manners."] = "É bênção pros Andarilhos do Sol, sorte pros caçadores, {name}. Pra tauren, é educação."
L["Take this, {name}. If a harpy screeches at you, screech back. They hate that."] = "Tome, {name}. Se uma harpia guinchar pra você, guinche de volta. Elas odeiam."
L["Here, {name}. A tauren blessing: sturdy, slow to fade, smells faintly of sage."] = "Tome, {name}. Uma bênção tauren: robusta, demora a passar, cheira de leve a sálvia."
L["The Earth Mother watches over us both, {name}."] = "A Mãe Terra zela por você e por mim, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "Alguém avise os batentes das portas, {name}. Agora é em dobro."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "Mulgore ou Alta Montanha, {name}, coração shu'halo é enorme."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "Chifres e elmos, {name}. Só tauren entende essa dor."
L["Rain on fur takes a week to dry, {name}. Only another tauren ever believes me."] = "Pelo molhado de chuva leva uma semana pra secar, {name}. Só outro tauren acredita."
L["Between tauren, {name}: Thunder Bluff's lifts were built by somebody smaller."] = "Cá entre tauren, {name}: quem fez os elevadores do Penhasco do Trovão era baixinho."
L["Our ancestors watch us both, {name}. Let's give them something nice to see."] = "Nossos ancestrais olham por nós dois, {name}. Vamos dar a eles algo bonito de ver."
L["From Mulgore to Highmountain, {name}, the herd always finds itself."] = "De Mulgore a Alta Montanha, {name}, a manada sempre se reencontra."
L["Get behind me, {name}. There's room back there for the whole party."] = "Fique atrás de mim, {name}. Cabe o grupo inteiro aí atrás."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "A manada anda junta, {name}. Cuidado com meus cascos; a manada já aprendeu."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "Teto baixo à frente, {name}? Eu descubro antes de todo mundo. Tome."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "Custo a me irritar, {name}, mas guardo rancor pelo grupo inteiro."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "Precisa de uma parede pra se esconder, {name}? Sou quase uma. Vem."
L["When I war stomp, {name}, everybody sit down. It saves you falling over."] = "Quando eu der a pisada de guerra, {name}, todo mundo senta. Poupa o tombo."
L["Everyone fed? Everyone blessed? Good, {name}. Tauren never lead a hungry herd."] = "Todos alimentados? Todos abençoados? Ótimo, {name}. Tauren não guia manada com fome."
L["Tauren don't swim, {name}, we wade. If it's deep, you're riding on me."] = "Tauren não nada, {name}: tauren vadeia. Se for fundo, você vai de carona em mim."
L["Stay close, {name}. My ancestors walk with us. They're quieter than you lot."] = "Fique perto, {name}. Meus ancestrais andam conosco. São mais quietos que vocês."
L["If I fall, {name}, don't try to carry me. Drag me. Fondly."] = "Se eu cair, {name}, não tente me carregar. Me arraste. Com carinho."
L["We move like a stampede, {name}: all together, and sorry about the flowers."] = "Andamos feito estouro de boiada, {name}: todos juntos, e desculpa pelas flores."
L["Nobody walks alone at the rear, {name}. That's where I'll be, looming kindly."] = "Ninguém anda sozinho na retaguarda, {name}. Eu fico lá, me agigantando com carinho."
L["Tell me when to charge, {name}. Tauren are slow to start, and slower to stop."] = "Avise quando investir, {name}. Tauren demora a arrancar, e mais ainda a parar."
L["Nobody wander, {name}. The last party that did in the Barrens is still walking."] = "Ninguém se afasta, {name}. O último grupo que fez isso nos Sertões ainda está andando."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "An'she se levanta, {name}, e nós também. Mais devagar, no meu caso."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "O sol é o olho de An'she, {name}. Ele está vendo, então vamos fingir serviço."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "Bom dia, {name}. Os kodos acordaram, a grama está molhada, e isto é seu."
L["Morning, {name}. I've greeted the sun, the wind and two plainstriders. Now you."] = "Bom dia, {name}. Já saudei o sol, o vento e duas aves da planície. Agora você."
L["Morning, {name}. Dew on the grass, dew on my fur. I'll be damp till noon."] = "Bom dia, {name}. Orvalho na grama, orvalho no pelo. Só seca ao meio-dia."
L["Early, {name}. That mist over Mulgore at dawn? Mostly kodo breath."] = "Cedo, {name}. A névoa sobre Mulgore ao amanhecer? Quase tudo bafo de kodo."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "Mu'sha faz a vigília da noite, {name}. Vou pedir pra ela ficar de olho em você."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "A lua saiu, {name}. Mu'sha te vê e aprova. Eu perguntei."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "Tarde, {name}. Os kodos dormem e roncam feito trovão. Tome."
L["Stars out, {name}. Each one's an ancestor, they say. That one's winking at you."] = "Estrelas no céu, {name}. Cada uma é um ancestral, dizem. Aquela pisca pra você."
L["Late, {name}. Mulgore is so quiet at night you can hear the grass argue."] = "Tarde, {name}. À noite Mulgore é tão quieta que dá pra ouvir a grama discutir."
L["Quiet now, {name}. At this hour, even my hooves try to tiptoe."] = "Silêncio, {name}. A esta hora, até meus cascos andam na ponta dos pés."
L["Ya be too kind, {name}! Dis one be from me."] = "Cê é gente boa demais, {name}! Essa vai de mim."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "Valeu, mano! Os espíritos sorriem procê, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "Cê me deu mojo bom, {name}. Agora toma de volta, extra apimentado."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "Bwonsamdi vai ficar bem decepcionado, {name}. Valeu, mano."
L["Dat be some fine work, {name}. Almost as fine as me. Almost."] = "Trampo caprichado, {name}. Quase no meu nível. Quase."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "Troll regenera uma mão, {name}. Honra não regenera. Toma."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "Cê fez um troll sorrir, {name}, e a gente tem muito dente."
L["Da loa keep a tally, {name}, and now ya on da good side of it."] = "Os loa anotam tudo, {name}, e agora cê tá do lado bom da conta."
L["Ya beat me to it, {name}! Darkspear hate bein' second. Now we even."] = "Cê foi primeiro, {name}! Lançanegra odeia ser segundo. Agora tamo quite."
L["I owe ya now, {name}, and trolls only like owin' da loa. Settled."] = "Agora eu te devo, {name}, e troll só gosta de dever pros loa. Quitado."
L["I be tellin' da whole Echo Isles 'bout ya, {name}. All dey talk 'bout is crabs."] = "Vou falar docê pras Ilhas do Eco inteiras, {name}. Lá só se fala de caranguejo."
L["My hair just stood up taller, {name}. Didn't know it could. Thanks, mon."] = "Meu cabelo ficou ainda mais em pé, {name}. Nem sabia que dava. Valeu, mano."
L["Da spirits say 'give it back', {name}. Da spirits nag, but dey right."] = "Os espíritos dizem 'devolve', {name}. Eles pegam no pé, mas tão certos."
L["Mojo for mojo, {name}: oldest trade in da jungle. Second oldest be bananas."] = "Mojo por mojo, {name}: o comércio mais antigo da selva. O segundo é banana."
L["Vol'jin said repay kindness quick, {name}. He said a lot. Dat one stuck."] = "Vol'jin mandava retribuir gentileza logo, {name}. Falava muito. Essa pegou."
L["Dat deserve a dance, {name}. Lucky ya, ya get {buff} instead."] = "Isso merece uma dança, {name}. Sorte sua: cê ganha {buff} no lugar."
L["Jungle rule, {name}: what ya give come back, usually wit' teeth. Dis one don't."] = "Lei da selva, {name}: o que cê dá volta, geralmente com dente. Esse aqui não."
L["A gift for a troll? Careful, {name}. We follow nice folk home."] = "Presente pra troll? Cuidado, {name}. A gente segue gente boa até em casa."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "Firmeza, {name}. Não se mexe; o mojo não curte alvo em movimento."
L["No worries, {name}. Da loa got ya covered."] = "Relaxa, {name}. Os loa tão contigo."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "Fica longe do vodu, {name}. ...Menos desse vodu. Esse tá de boa."
L["Close ya eyes, {name}. Da mojo be shy when people watch."] = "Fecha os olhos, {name}. O mojo fica tímido quando tem gente olhando."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "Nem precisa pedir duas vezes, {name}. Mal precisa pedir uma."
L["Sure, {name}. Bein' a troll be mostly swagger. Da rest be dis."] = "Claro, {name}. Ser troll é quase tudo ginga. O resto é isso aqui."
L["Ya asked real polite, {name}. Polite get da good stuff."] = "Cê pediu na educação, {name}. Quem pede na educação leva do bom."
L["Ya came to da right troll, {name}. Da wrong troll be over dere, fishin'."] = "Cê veio no troll certo, {name}. O troll errado tá ali, pescando."
L["Yes, {name}. Da loa owe me a favour, and I be spendin' it on you."] = "Sim, {name}. Os loa me devem um favor, e vou gastar com você."
L["No problem, {name}. Got a pouch fulla mojo. Don't touch da other pouch."] = "Sem problema, {name}. Tenho uma bolsa cheia de mojo. Não mexe na outra bolsa."
L["Anyting for ya, {name}. Well, not my hair. Da hair be sacred."] = "Qualquer coisa procê, {name}. Bom, menos o cabelo. O cabelo é sagrado."
L["Troll magic, {name}, served hot. Blow on it first."] = "Magia troll, {name}, servida quentinha. Assopra antes."
L["Right away, {name}. In Zandalar dis need a priest, a pyramid and a week."] = "É pra já, {name}. Em Zandalar isso pede um sacerdote, uma pirâmide e uma semana."
L["Easy one, {name}. Hard one be gettin' a raptor to sit still."] = "Essa é fácil, {name}. Difícil é fazer um raptor ficar parado."
L["Troll rule, {name}: never make a friend beg or a raptor wait. Here."] = "Regra troll, {name}: amigo não implora e raptor não espera. Toma."
L["Hold still, {name}. Last one who wiggled got da spell and a new haircut."] = "Não se mexe, {name}. O último que se mexeu levou o feitiço e um corte de cabelo."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "Os loa tão de olho em você, {name}. São xeretas assim mesmo."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "Olho aberto lá fora, {name}. Leva isso contigo."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "Cê tem cara de quem curte qualidade, {name}. Toma: qualidade."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "Toma, {name}. Anda como se a selva fosse sua. Eu ando."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "Todo mundo precisa de mojo, {name}. Eu faço tanto que tenho que dar."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "Um agradinho procê, {name}. Não pergunta onde os loa arrumaram."
L["Go on, {name}. Anyting try to eat ya now gonna get indigestion."] = "Vai lá, {name}. O que tentar te comer agora vai ter indigestão."
L["Ya lookin' dangerous now, {name}. Almost troll-level dangerous."] = "Agora cê tá com cara de perigo, {name}. Quase nível troll de perigo."
L["Somethin' for ya, {name}. No, ya don't owe da loa nothin'. Probably."] = "Um agrado procê, {name}. Não, cê não deve nada pros loa. Acho."
L["Raptors out dere got bigger teeth den me, {name}. Now dey got a problem."] = "Os raptores lá fora têm dente maior que o meu, {name}. Agora o problema é deles."
L["Troll hospitality, {name}: ya get mojo, ya get a smile, ya don't get my fish."] = "Hospitalidade troll, {name}: cê ganha mojo, ganha sorriso, mas meu peixe não."
L["Walk wit' mojo, {name}. Everybody else just be walkin'."] = "Anda com mojo, {name}. O resto do povo só anda."
L["Free mojo, {name}! Quick, before da witch doctor find out I give it away."] = "Mojo de graça, {name}! Rápido, antes que o feiticeiro descubra que eu tô dando."
L["Da loa said give dis to da next good soul, {name}. Ya da next good soul."] = "Os loa mandaram dar isso pra próxima alma boa, {name}. Cê é a próxima alma boa."
L["Here, {name}. Hakkar never shared, and look what happen to him."] = "Toma, {name}. Hakkar nunca dividia nada, e olha no que deu."
L["Jungle got two kinds of folk, {name}: da ready and da lunch. Now ya ready."] = "A selva tem dois tipos, {name}: quem caça e quem vira almoço. Agora cê caça."
L["Easy, {name}. Dis mojo tickle goin' in. Don't laugh; it get offended."] = "Calma, {name}. Esse mojo faz cócegas quando entra. Não ri, que ele se ofende."
L["'Nobody badduh dan me,' Zul'jin said, {name}. Dis let ya argue da point."] = "'Ninguém é mais brabo que eu', disse Zul'jin, {name}. Agora cê pode discordar."
L["Hey, {name}! Always good to see family, mon."] = "Ei, {name}! Sempre bom ver a família, mano."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "O resto de Azeroth anda reto, {name}. A gente tem mais estilo."
L["Hey, {name}, ya tusks be lookin' sharp. Mine too, obviously."] = "E aí, {name}, suas presas tão no grau. As minhas também, óbvio."
L["Every troll be family, {name}. Even da ones who still owe me gold."] = "Todo troll é família, {name}. Até os que ainda me devem ouro."
L["Island or pyramid, {name}, a troll be a troll. Zandalari just wear more gold."] = "Ilha ou pirâmide, {name}, troll é troll. Zandalari só usa mais ouro."
L["Two trolls, {name}. Da room just got taller and a lot more relaxed."] = "Dois trolls, {name}. O lugar ficou mais alto e muito mais tranquilo."
L["Da loa can't tell us apart, {name}. Dat be why dey bless us both. Cheaper."] = "Os loa confundem a gente, {name}. Por isso abençoam no atacado. Mais barato."
L["Troll to troll, {name}: nobody else know how hard it be to buy boots."] = "De troll pra troll, {name}: ninguém mais sabe como é difícil comprar bota."
L["Our ancestors had empires, {name}. We got each other. Fair trade, I say."] = "Nossos ancestrais tinham impérios, {name}. A gente tem a gente. Troca justa."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "Fica perto, {name}. Troll regenera; o resto de vocês tem que se cuidar."
L["Dis crew got style, {name}. Now it got mojo too."] = "Essa galera tem estilo, {name}. Agora tem mojo também."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "A gente entra junto, {name}, a gente sai junto. Esse é o plano todo, mano."
L["Nobody fallin' today, {name}. Bwonsamdi can wait for da next group."] = "Ninguém cai hoje, {name}. Bwonsamdi que espere o próximo grupo."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "Cabeça baixa, {name}. A minha fica erguida. Alguém tem que fazer bonito."
L["Raptor formation, {name}: fast, loud, and nobody look back."] = "Formação raptor, {name}: rápido, barulhento e sem olhar pra trás."
L["Big snake show up, {name}, don't run. Ya run, it chase. Stand behind me."] = "Cobra grande, {name}? Não corre. Correu, ela caça. Fica atrás de mim."
L["Anybody need more mojo, {name}, just shout. Not too loud; da loa nappin'."] = "Quer mais mojo, {name}, é só gritar. Baixinho; os loa tão cochilando."
L["We gonna be a story at Sen'jin, {name}. Let's make it one wit' a happy endin'."] = "A gente vai virar história na Vila Sen'jin, {name}. Que seja com final feliz."
L["Stick close, {name}. My tusks be sharp, but dey can't be everywhere."] = "Fica pertinho, {name}. Minhas presas são afiadas, mas não tão em todo canto."
L["Nobody panic, {name}. Panic be bad mojo. Swagger be good mojo."] = "Sem pânico, {name}. Pânico é mojo ruim. Ginga é mojo bom."
L["See a big idol wit' glowin' eyes, {name}? Don't touch it. Trust me on dis."] = "Viu um ídolo grande de olho brilhando, {name}? Não encosta. Confia em mim."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "Noite é a melhor hora pro mojo, {name}. Ninguém vê de onde vem."
L["Da jungle wake up at night, {name}. So do I. Here, dis one fresh."] = "A selva acorda de noite, {name}. Eu também. Toma, esse tá fresquinho."
L["Moon be high, {name}, spirits be restless. Dis keep dem off ya."] = "Lua alta, {name}, espírito inquieto. Isso aqui deixa eles longe de você."
L["Hir'eek, da bat loa, keep late hours too, {name}. Dis from da both of us."] = "Hir'eek, o loa morcego, também vara a madrugada, {name}. Essa vai de nós dois."
L["Dis late, {name}, only trolls and trouble be awake. I be da nice one."] = "Tarde assim, {name}, só troll e treta tão acordados. Eu sou a parte boa."
L["Stars be out, {name}. Every one a loa, my granny say. Dat a lotta watchers."] = "Estrelas no céu, {name}. Cada uma é um loa, diz minha vó. É muito olho em cima."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "Tanta cortesia honra você, {name}. Quase tanto quanto me honra."
L["How gracious, {name}. Allow me to return the favour."] = "Quanta elegância, {name}. Permita-me retribuir o favor."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "Agradeço, {name}. Não me sentia tão radiante desde... bem, hoje de manhã."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "Gentileza sua, {name}. Sin'dorei nunca recusa magia de graça. Pergunte por aí."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "Primoroso, {name}. Eu entendo do assunto: só aceito o primoroso."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "Adorável, {name}. Vou ficar insuportável com isso o dia todo. Mais que o normal."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "Agradeço, {name}. Até combina com meus detalhes dourados. Que bom gosto."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "Retribuído na mesma moeda, {name}. Uma moeda mais bonita, confesso. Não resisto."
L["Thank you, {name}. Visit Silvermoon; I'll show you all of it but Murder Row."] = "Agradeço, {name}. Visite Luaprata; mostro tudo, menos o beco dos ladinos."
L["Returned, {name}. Unlike Kael'thas, I give things back."] = "Retribuído, {name}. Diferente de Kael'thas, eu devolvo."
L["Thank you, {name}. I felt that to the tips of my ears, and that's a long way."] = "Agradeço, {name}. Senti isso até a ponta das orelhas, e olha que é longe."
L["Thank you, {name}. That was so kind my eyes nearly changed colour again."] = "Agradeço, {name}. Foi tão gentil que meus olhos quase mudaram de cor de novo."
L["A gift, unasked? Farstriders would call that an ambush. A lovely one, {name}."] = "Presente sem pedir? Patrulheiro chamaria de emboscada. Das adoráveis, {name}."
L["Better than a mana crystal, {name}, and I've given those up. Mostly. Thank you."] = "Melhor que cristal de mana, {name}, e olha que eu larguei. Quase. Agradeço."
L["Quick of you, {name}. Elves live for centuries, and you still beat me to it."] = "Que rapidez, {name}. Elfo vive séculos, e mesmo assim você chegou antes."
L["Charming, {name}. I don't say it lightly. I say it constantly, but not lightly."] = "Encantador, {name}. Não digo isso à toa. Digo toda hora, mas não à toa."
L["Thank you, {name}. I'll mention you at court. Well, at a very exclusive picnic."] = "Agradeço, {name}. Vou citar você na corte. Bem, num piquenique muito exclusivo."
L["Thank you, {name}. You've been added to my list of people who deserve me."] = "Agradeço, {name}. Você entrou na minha lista de quem me merece."
L["Unasked kindness, {name}! Somebody tell Rommath; he'll want to study it."] = "Gentileza espontânea, {name}! Avisem o Rommath; ele vai querer estudar."
L["Naturally, {name}. Only the finest for you."] = "Naturalmente, {name}. Só o melhor para você."
L["For you, {name}? Of course. The sun gives freely."] = "Para você, {name}? Mas é claro. O sol é generoso."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "Paciência, {name}. Esplendor não se apressa, só se admira."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "Claro, {name}. {buff}, entregue com postura impecável."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "Você pediu com educação, {name}. Em Luaprata, isso é tudo."
L["One moment, {name}. I never cast anything without checking my hair."] = "Um momento, {name}. Nunca lanço nada sem conferir o cabelo."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "Agora mesmo, {name}. Deixar alguém esperando é tão fora de moda."
L["Certainly, {name}. Stand back a step; my sleeves are enchanted and very wide."] = "Certamente, {name}. Um passo atrás; minhas mangas são encantadas e bem largas."
L["Magisters would bill you, {name}. Blood Knights would lecture. I merely glow."] = "Um magíster cobraria, {name}. Um Cavaleiro de Sangue daria sermão. Eu só brilho."
L["At once, {name}. If it goes well, tell everyone. If not, blame the robe."] = "Agora mesmo, {name}. Se der certo, conte a todos. Se não, culpe a toga."
L["At once, {name}. The dragonhawk can wait; it's used to waiting while I dress."] = "Agora mesmo, {name}. O falcodrago espera; já se acostumou a esperar eu me vestir."
L["Gladly, {name}. We once took the Light from a naaru. Asking is so much nicer."] = "Com prazer, {name}. Já arrancamos a Luz de um naaru. Pedir é bem mais simpático."
L["Three centuries of casting, {name}, and you're the first to say please."] = "Três séculos de feitiços, {name}, e só agora alguém disse 'por favor'."
L["Gladly, {name}. Silvermoon's brooms sweep themselves, so my hands are free."] = "Com prazer, {name}. Em Luaprata as vassouras varrem sozinhas; estou de mãos livres."
L["Of course, {name}. Arcane Torrent is for the rude. You asked nicely."] = "Claro, {name}. Torrente Arcana é para os grosseiros. Você pediu com jeito."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore, {name}. Que o sol te guie e ilumine seu melhor ângulo."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. Lute com elegância."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "Tome, {name}. O que acontecer lá fora é só um contratempo."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "Todos merecem brilhar, {name}. Só um pouquinho menos que eu, claro."
L["The sun is with you, {name}. I simply held the door for it."] = "O sol está com você, {name}. Eu só segurei a porta pra ele."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "Vai, {name}, pode pegar. A Nascente do Sol voltou; podemos esbanjar."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "Para você, {name}: {buff}, com um leve perfume de Luaprata."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "Tome, {name}. Artesanal, de Luaprata; tente não arranhar."
L["A little Sunwell for you, {name}. It's been through a lot; treat it kindly."] = "Um pouco da Nascente do Sol, {name}. Ela já sofreu muito; trate com carinho."
L["Be prepared, {name}. We weren't, once, and now we have a scar for a road."] = "Previna-se, {name}. Nós não nos prevenimos, e hoje há uma cicatriz por estrada."
L["Here, {name}. I only give to the worthy. How convenient that you walked by."] = "Tome, {name}. Só dou a quem merece. Que conveniente você passar por aqui."
L["Take this, {name}. It's been in my family for moments."] = "Tome, {name}. Está na minha família há instantes."
L["We sin'dorei have lost much, {name}. Never our generosity. Or our cheekbones."] = "Nós, sin'dorei, perdemos muito, {name}. Nunca a generosidade. Nem as maçãs do rosto."
L["Take this, {name}. Should a mana wyrm follow you, it's only jealous."] = "Tome, {name}. Se uma serpe de mana seguir você, é só ciúme."
L["Seven thousand years to perfect generosity, {name}. We started last week."] = "Sete mil anos para aperfeiçoar a generosidade, {name}. Começamos semana passada."
L["Take this, {name}. It came through the Undercity orb, so it's slightly dizzy."] = "Tome, {name}. Veio pelo orbe da Cidade Baixa, então chegou meio tonto."
L["For you, {name}. It matches everything. I checked, obviously."] = "Para você, {name}. Combina com tudo. Eu conferi, óbvio."
L["If a ghoul stops you, {name}, say Silvermoon's still standing. They hate that."] = "Se um carniçal parar você, {name}, diga que Luaprata continua de pé. Eles odeiam isso."
L["The Sunwell shines for us both, {name}."] = "A Nascente do Sol brilha para nós, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "Sin'dorei em dobro, {name}. O dia ficou duas vezes mais elegante."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "Você também, {name}? Um espelho só pra nós? Vamos ter que revezar."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "Como a fênix, {name}: sempre renascemos, e com estilo."
L["Between sin'dorei, {name}: yes, the Horde is loud. Yes, we're used to it now."] = "Entre sin'dorei, {name}: sim, a Horda é barulhenta. Sim, já nos acostumamos."
L["Sin'dorei to sin'dorei, {name}: shall we pretend neither of us had a fel phase?"] = "De sin'dorei para sin'dorei, {name}: vamos fingir que ninguém aqui teve uma fase vil?"
L["Sunstrider or Farstrider, {name}, we all stride beautifully."] = "Andassol ou andarilho, {name}, todos nós andamos lindamente."
L["We both remember Quel'Thalas before the Scourge, {name}. Let's earn the after."] = "Lembramos de Quel'Thalas antes do Flagelo, {name}. Vamos fazer por merecer o depois."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "Acompanhe o ritmo, {name}. Temos fama de chegar arrasando."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "Fique onde a luz é boa, {name}. Se é pra ter combate, vamos sair bem na foto."
L["A party at last, {name}. I did dress for one."] = "Enfim um grupo, {name}. E eu me vesti pra festa."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "O sol nasce para todos, {name}. Mais pra mim, mas ele divide."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "Um pra você, {name}, e um pela imagem do grupo, que ficou por minha conta."
L["If I fall, {name}, arrange me attractively. The rest I leave to the healer."] = "Se eu cair, {name}, me arrume com charme. O resto fica com o curandeiro."
L["Nobody touch the enchanted relics, {name}. Well, I may. I've had training."] = "Ninguém toca nas relíquias encantadas, {name}. Bem, eu posso. Tenho treinamento."
L["Every expedition needs a ranger, {name}. I'm not one, but I have the boots."] = "Toda expedição precisa de um patrulheiro, {name}. Não sou um, mas tenho as botas."
L["We fight together, {name}, then tell it beautifully. I'll handle the telling."] = "Lutamos lado a lado, {name}, depois contamos com elegância. A parte de contar é minha."
L["The healer is to be thanked and the tank adored, {name}. Me, admired. Carry on."] = "Ao curandeiro, gratidão; ao tanque, adoração, {name}. A mim, admiração. Prossigam."
L["If this goes badly, {name}, we blame the Scourge. It's traditional."] = "Se isto der errado, {name}, a culpa é do Flagelo. É tradição."
L["Mana potions are for emergencies, {name}. I've had eleven emergencies today."] = "Poção de mana é para emergências, {name}. Hoje já tive onze emergências."
L["We walked out of the ashes once, {name}. We'll walk out of whatever's ahead."] = "Já saímos das cinzas uma vez, {name}. Saímos do que vier pela frente."
L["The sun has risen, {name}, and so have I. We coordinate."] = "O sol levantou, {name}, e eu também. A gente combina."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "O amanhecer em Quel'Thalas é mais bonito, {name}, mas este serve. Por pouco."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "Luz da manhã, {name}. A hora que mais favorece. Você e eu, naturalmente."
L["Breakfast in Eversong is fruit, tea and arcane, {name}. Skip to the arcane."] = "Café da manhã no Canto Eterno: fruta, chá e arcano, {name}. Pule pro arcano."
L["Dawn, {name}. Red and gold across the sky. Somebody's been copying us."] = "Amanhecer, {name}. Vermelho e dourado no céu todo. Alguém anda nos copiando."
L["Morning, {name}. Only Silvermoon's arcane guardians are up this early. And me."] = "Bom dia, {name}. A essa hora só os guardiões arcanos de Luaprata estão de pé. E eu."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "Sua generosidade foi registrada, {name}. Em três vias. Suramar se lembra dos amigos."
L["Most gracious, {name}. Allow me to repay you in kind."] = "Muito gentil, {name}. Permita-me retribuir à altura."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "Agradeço, {name}. Dez mil anos sob uma cúpula; ainda estou treinando isso."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "Um presente sem favor em troca? A corte desmaiaria. Agradeço, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "Retribuído, {name}. Anotamos com cuidado cada gentileza. E cada desfeita."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "Vou falar de você à Primeira Arcanista Thalyssra, {name}. Bem, inclusive."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "Muita gentileza, {name}. Em Suramar daríamos um banquete. Considere dado."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "Mandaria um ofício de agradecimento, {name}, mas assim é mais rápido."
L["In Elisande's court a gift hid a knife, {name}. Yours hides none. Thank you."] = "Na corte de Elisande, presente escondia faca, {name}. O seu, nenhuma. Agradeço."
L["Thank you, {name}. My manasaber approves of you, and she approves of no one."] = "Agradeço, {name}. Meu sabre-de-mana aprova você, e ele não aprova ninguém."
L["Exquisite, {name}. Once I'd have said 'adequate'. The world has humbled me."] = "Primoroso, {name}. Antes eu diria 'adequado'. O mundo me ensinou humildade."
L["You fed a mind that once went hungry, {name}. We never forget those who do."] = "Você alimentou uma mente que já passou fome, {name}. Nunca esquecemos quem faz isso."
L["Centuries of court etiquette, {name}, and 'thank you' still outperforms it all."] = "Séculos de etiqueta da corte, {name}, e um 'agradeço' ainda supera tudo."
L["Thank you, {name}. You're invited to the next masquerade. Masks mandatory."] = "Agradeço, {name}. Venha ao próximo baile de máscaras. Máscara obrigatória."
L["Thank you, {name}. Oculeth would open a portal to say so. I'll simply cast."] = "Agradeço, {name}. Oculeth abriria um portal para dizer isso. Eu só lanço."
L["Of course, {name}. A little arcane polish, just for you."] = "Claro, {name}. Um polimento arcano, só para você."
L["A reasonable request, {name}. Granted."] = "Um pedido razoável, {name}. Concedido."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "Certamente, {name}. A versão curta; a longa leva um ciclo lunar."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "Um pedido, que novidade. A corte só fazia exigências. Tome, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "Feito, {name}, e de graça. Elisande cobraria um favor por isso."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "Pronto, {name}. Não precisa se curvar. Mas um aceno de cabeça seria ótimo."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "Claro, {name}. Aperfeiçoo isto desde antes de a maioria das cidades ter muralhas."
L["Granted, {name}. I'd ask a favour back, but I'm trying to be less Suramar."] = "Concedido, {name}. Cobraria um favor, mas estou tentando ser menos Suramar."
L["Certainly, {name}. Forgive the flourish. We can't cast plainly; we've tried."] = "Certamente, {name}. Perdoe o floreio. Não sabemos lançar sem firula; já tentamos."
L["At once, {name}. Elisande once stopped time. I only need a second."] = "Agora mesmo, {name}. Elisande parou o tempo. Eu só preciso de um segundo."
L["Of course, {name}. The ley lines here are shallow, but I'll make do."] = "Claro, {name}. As linhas ley aqui são rasas, mas eu me viro."
L["Very well, {name}. Stand in the moonlight. Or by that lamp. Lamps will do."] = "Muito bem, {name}. Fique sob o luar. Ou perto daquele lampião. Lampião serve."
L["Naturally, {name}. Suramar had a spell for everything. I remember several."] = "Naturalmente, {name}. Suramar tinha feitiço para tudo. Eu lembro de vários."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "Tome, {name}. Dons arcanos se perdem com quem fica à toa."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "Uma centelha arcana de Suramar, {name}. Use com sabedoria."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "Já fiquei sem magia uma vez, {name}. Não recomendo. Tome."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "O mundo fora da cúpula é tão grande, {name}. E tão pouco encantado. Tome."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "Vinho arcano é o tradicional, {name}, mas {buff} viaja melhor."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "Aceite, {name}. É falta de educação recusar a hospitalidade de Suramar. Muita."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "Tome, {name}. Dizem que é assim que os forasteiros dão oi. Costume encantador."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "Tome, {name}. Magia guardada é magia estragada, como Suramar aprendeu."
L["Once, I'd have made you bow for this, {name}. We've all grown."] = "Antes, eu exigiria uma reverência por isto, {name}. Todos crescemos."
L["The Kirin Tor do this too, {name}, bless them. Quite nicely, for newcomers."] = "O Kirin Tor também faz isto, {name}, que graça. Até que bem, para novatos."
L["A gift from under the dome, {name}. Kept fresh for a very, very long time."] = "Direto da cúpula, {name}. Conservado fresquinho por muito, muito tempo."
L["Enjoy this, {name}. I used to cast it on nobility. You're an improvement."] = "Aproveite, {name}. Eu lançava isto na nobreza. Você é uma melhoria."
L["I packed for the outside world like a gala, {name}. Four capes. Take this."] = "Fiz as malas para o mundo como quem vai a um baile, {name}. Quatro capas. Tome."
L["Here, {name}. Suramar work: overdesigned, overdecorated, and flawless."] = "Tome, {name}. Trabalho de Suramar: exagerado, rebuscado e impecável."
L["Here, {name}. In Suramar this came with a string quartet. Do hum something."] = "Tome, {name}. Em Suramar, isto vinha com quarteto de cordas. Cantarole algo."
L["Suramar's children shine together again, {name}."] = "Os filhos de Suramar brilham juntos outra vez, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "Shal'dorei, {name}! Trouxe vinho arcano? Vinho de fora é só... uva."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "Gente de Suramar, {name}. Tente não se impressionar demais com o resto do mundo."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "Sobrevivemos à Legião e ao definhamento, {name}. O resto é conversa fiada."
L["Our tailors made it out of Suramar too, {name}. Thank the stars."] = "Nossos alfaiates também saíram de Suramar, {name}. Graças às estrelas."
L["We both remember going hungry, {name}. Never again, for either of us."] = "Lembramos bem da fome, {name}. Nunca mais, para nenhum de nós."
L["Out from under the dome, {name}. Is the sky still this big for you too?"] = "Fora da cúpula, {name}. O céu ainda parece enorme para você também?"
L["Two shal'dorei in one place, {name}. The locals will assume it's a gala."] = "Shal'dorei em dobro, {name}. O povo daqui vai achar que é baile de gala."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "Uma expedição, {name}! Em Suramar, isso exigia seis licenças e um baile de máscaras."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "A cúpula nos protegia, {name}. Agora nos viramos uns com os outros. Com prazer."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "Arcano pra todo mundo, {name}. A corte chamaria de desperdício. Eu chamo de companhia."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "Siga meus passos, {name}. Tenho dez mil anos de prática em andar no compasso."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "Em grupo, divide-se a magia, {name}. Que novidade. Estou gostando."
L["An outing is like a masquerade, {name}: smile, keep moving, watch for knives."] = "Expedição é como baile de máscaras, {name}: sorria, não pare e cuidado com as facas."
L["Stay in the light of my spells, {name}. It's the most flattering in the party."] = "Fique na luz dos meus feitiços, {name}. É a iluminação mais lisonjeira do grupo."
L["After Elisande's court, {name}, a party of five is a holiday. Nobody plots."] = "Depois da corte de Elisande, {name}, um grupo de cinco é férias. Ninguém conspira."
L["Lost? Follow the one who glows, {name}. That's me. It's always me."] = "Perdeu o rumo? Siga quem brilha, {name}. Sou eu. Sempre sou eu."
L["If I start lecturing on ley lines, {name}, do interrupt. Politely."] = "Se eu der palestra sobre linhas ley, {name}, interrompa. Com educação."
L["I watched my people wither, {name}. I won't watch friends fade. Nobody falls."] = "Vi meu povo definhar, {name}. Não vou ver amigos sumirem. Ninguém cai."
L["Tell me if I'm being grand, {name}. I lose track. It's the millennia."] = "Avise se eu exagerar na pompa, {name}. Perco a noção. São os milênios."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "Enfim a noite, {name}. Com mais uns mil lampiões, é quase Suramar."
L["Under the dome it was always night, {name}. I feel quite at home."] = "Sob a cúpula era sempre noite, {name}. Eu me sinto em casa."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "As estrelas saíram, {name}. Em Suramar eram melhores. Estas servem."
L["Nightborne, {name}, and here's the night. At last I'm dressed for the hour."] = "Filhos da Noite, {name}, e enfim a noite. Finalmente minha roupa combina com a hora."
L["At this hour, {name}, Suramar was only just getting dressed for dinner."] = "A esta hora, {name}, Suramar mal começava a se vestir para o jantar."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "Luz do dia, {name}. Dez mil anos sob uma cúpula, e isso ainda me assusta."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "Que cedo, {name}. A corte nunca levantava antes do meio-dia. Estou me corrigindo."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "Bom dia, {name}. O sol aqui é tão... sem encanto. Tome isto no lugar."
L["Morning, {name}. We warded Suramar against every threat but the sun."] = "Bom dia, {name}. Protegemos Suramar de toda ameaça, menos do sol."
L["Dawn, {name}: when the court's gossip went to bed. Here's mine: you look well."] = "Amanhecer, {name}: a fofoca da corte ia dormir. Eis a minha: você está radiante."
L["A favour for a favour, {name}! Pleasure doing business."] = "Favor com favor se paga, {name}! Um prazer fazer negócio."
L["Thanks, {name}! Consider your account settled in full."] = "Valeu, {name}! Pode considerar sua conta quitada."
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "Ah, {name}. Eu te mandaria um boleto, mas bateu a emoção. Já passa."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "Valeu, {name}! Procurei as letras miúdas. Não tinha nenhuma. Estranho!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "Devolvido com juros, {name}. Sem os juros. Não se acostume."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "Valeu mesmo, {name}! Você acabou de virar cliente VIP."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "Eu daria seu nome a um foguete, {name}, mas meus foguetes duram pouco. Valeu!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "Eu cobraria cinquenta de ouro por isso, {name}. Estamos quites."
L["Gave first, {name}? Bold business model. I'll match it. Don't tell Undermine."] = "Deu primeiro, {name}? Modelo de negócio ousado. Vou cobrir. Não conta pros cartéis."
L["A deal where both sides profit, {name}! I'd heard of those. Never seen one."] = "Um ganha-ganha, {name}! Já tinha ouvido falar. Nunca tinha visto um."
L["First free gift since Kezan blew up, {name}. Returning it before I price it."] = "Primeiro brinde desde que Kezan explodiu, {name}. Devolvo antes de pôr preço."
L["Thanks, {name}! I appraised it at priceless. Here's one appraised the same."] = "Valeu, {name}! Avaliei em 'não tem preço'. Toma um com a mesma avaliação."
L["Kindness in, kindness out, {name}. Best returns since the kaja'mite boom."] = "Gentileza entra, gentileza sai, {name}. Melhor retorno desde o boom da kaja'mita."
L["Even trade, {name}? My accountant just fainted. He does that around fair deals."] = "Troca justa, {name}? Meu contador desmaiou. Ele faz isso perto de negócio honesto."
L["Thanks, {name}! I'd shake on it, but I count my fingers after. Habit, not you."] = "Valeu, {name}! Apertaria sua mão, mas depois conto os dedos. Mania, não é com você."
L["No haggling at all? Thanks, {name}. I feel cheated. In a nice way."] = "Sem pechincha nenhuma? Valeu, {name}. Parece até golpe. Do tipo bom."
L["You got it, {name}! Time is money, friend!"] = "É pra já, {name}! Tempo é dinheiro, sabe como é!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "Fechado, {name}! Vou pôr na sua conta. Brincadeira!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "É pra já, {name}! Satisfação garantida ou {buff} de volta."
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff}, {name}! Gorjeta opcional. Recomendada. Opcional."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "Rápido, barato ou bom, {name}? Hoje leva os três. Não espalha."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "Claro, {name}! Sem explosões dessa vez, prometo. Quase prometo."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "Pra você, {name}? De graça. Põe isso por escrito e eu nego."
L["Sure, {name}! Quote's zero gold. Lowest I've ever quoted. It stings a little."] = "Claro, {name}! Orçamento: zero ouro. O menor da minha vida. Até dói um pouco."
L["Coming up, {name}! Full warranty included. Valid until it wears off."] = "Saindo, {name}! Garantia total inclusa. Válida até o efeito acabar."
L["Sure, {name}! Sign here, initial there... joking. Mostly. Hold still."] = "Claro, {name}! Assina aqui, rubrica ali... brincadeira. Quase. Não se mexe."
L["Free of charge, {name}. If anybody from Bilgewater asks, you paid double."] = "De graça, {name}. Se alguém do cartel perguntar, você pagou o dobro."
L["Gadgetzan's got the water trade, {name}. I've got this. Better margins."] = "Geringontzan tem o comércio de água, {name}. Eu tenho isto. Margem melhor."
L["Kezan standard, {name}: fast, loud, and done before you read the terms."] = "Padrão Kezan, {name}: rápido, barulhento e pronto antes de você ler o contrato."
L["Order received, {name}! Delivery instant, wrapping optional, refunds imaginary."] = "Pedido recebido, {name}! Entrega na hora, embrulho opcional, reembolso imaginário."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "Essa é por conta da casa, {name}. Não conta pro Príncipe Mercante."
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "Produto de primeira, taxa zero, {name}. Só hoje!"
L["Free sample, {name}! If you like it, you know where to find me."] = "Amostra grátis, {name}! Se gostar, já sabe onde me achar."
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "Toma, {name}. Se algo explodir perto de você hoje, não tem nada a ver."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "Boa vontade é patrimônio, {name}. Toma um pouco de {buff} pro meu balanço."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "Toma, {name}. Segurança em primeiro lugar! Ou em terceiro. Tá na lista."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "Lançado em tempo recorde, {name}! O recorde é meu. Acabei de bater."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "Kaja'Cola dá ideias, {name}. Isto faz o resto. Toma!"
L["Limited-time offer, {name}! Limited mostly by how long it lasts."] = "Oferta por tempo limitado, {name}! Limitado, no caso, pela duração."
L["Free trial, {name}! No obligation. Well, a small emotional one."] = "Teste grátis, {name}! Sem compromisso. Bom, só um emocional."
L["Here, {name}. Patent pending. Try it out and tell your rich friends."] = "Toma, {name}. Patente pendente. Experimenta e conta pros seus amigos ricos."
L["Consider this an investment, {name}. In you. I expect heroic returns."] = "Considere isto um investimento, {name}. Em você. Espero um retorno heroico."
L["Take it, {name}! My last shipment sank off Kezan, so everything's clearance."] = "Leva, {name}! Minha carga afundou perto de Kezan; tá tudo em queima de estoque."
L["The Venture Company charges for this, {name}. I'm the competition. Here."] = "Os cartéis cobram por isso, {name}. Eu sou a concorrência. Toma."
L["Every goblin has a soft spot, {name}. Mine's small and guarded. You found it."] = "Todo goblin tem um ponto fraco, {name}. O meu é pequeno e tem alarme. Você achou."
L["Take this, {name}. It's the only thing I own with no lien on it."] = "Toma, {name}. É a única coisa minha que não tá penhorada."
L["You'll be rich someday, {name}. I can tell. Remember who gave you this."] = "Você ainda vai ter muito ouro, {name}. Dá pra ver. Lembra quem te deu isso."
L["Anything for a fellow entrepreneur, {name}!"] = "Tudo por alguém do ramo, {name}!"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "A nata de Kezan reunida de novo, {name}. Segura a carteira."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "Goblin também, {name}? Então sabe que esse desconto é muito, muito raro."
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "Goblin cuida de goblin, {name}. Sai mais barato que contratar guarda."
L["Kezan's gone, {name}, but the hustle made it out. Look at us."] = "Kezan já era, {name}, mas a malandragem escapou. Olha a gente."
L["Between goblins, {name}, this never happened. I have a reputation."] = "Entre goblins, {name}, isso nunca aconteceu. Tenho uma reputação."
L["Bilgewater or Steamwheedle, {name}, we always float to the top. Like oil."] = "Seja qual for o cartel, {name}, a gente sempre boia por cima. Igual óleo."
L["Remember the volcano, {name}? We sold tickets to it. Proud times."] = "Lembra do vulcão, {name}? A gente vendeu ingresso. Bons tempos."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "Tarifa de grupo, {name}! Meia-entrada pra todo mundo. Meia do grátis."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "Ninguém morre no meu contrato, {name}. A papelada é um pesadelo."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "A gente divide o saque igualzinho, {name}. Eu faço as contas. Confia."
L["Team-building, {name}! You make everybody stronger, and they all owe you."] = "Dinâmica de grupo, {name}! Você fortalece todo mundo, e todo mundo te deve."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "Todo mundo unido, {name}. Mercenário custa ouro; amigo custa só isto."
L["Everybody's covered, {name}. Not insured, mind. Covered. Different price."] = "Todo mundo coberto, {name}. Coberto, não segurado. Preço diferente."
L["I read the risk report on this outing, {name}. Short read. It just says 'no'."] = "Li o relatório de risco desta saída, {name}. Leitura curta. Só diz 'não'."
L["Nobody touches the big red lever, {name}. There's always a big red lever."] = "Ninguém mexe na alavanca vermelha, {name}. Sempre tem uma alavanca vermelha."
L["If this goes south, {name}, I've got a rocket. Seats one. I'm working on it."] = "Se der ruim, {name}, tenho um foguete. Cabe um. Tô trabalhando nisso."
L["We're a company now, {name}. I'm treasurer. The vote was unanimous. Mine."] = "Agora somos uma empresa, {name}. O caixa é comigo. Votação unânime: a minha."
L["Stay alive, {name}. Nobody's found a way to sell resurrections yet. I'm trying."] = "Não morre, {name}. Ninguém achou um jeito de vender ressurreição ainda. Tô tentando."
L["Stay close, {name}. I've already sold the story of this trip. Make it good."] = "Fica perto, {name}. Já vendi a história dessa viagem. Capricha."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "O lucro ajuda quem cedo madruga, {name}! Toma um brinde. Não conta pros outros."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "Bom dia, {name}! O mercado abre daqui a uma hora. Até lá, bateu a generosidade."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "De pé cedo, {name}? Boa. Tempo é dinheiro, e de manhã sai mais barato."
L["Up early, {name}? Me too. Rich goblins sleep in. I'm working on it."] = "Madrugou, {name}? Eu também. Goblin rico dorme até tarde. Tô chegando lá."
L["Fresh day, fresh ledger, {name}. You're the first entry. The good column."] = "Dia novo, caixa novo, {name}. Você é o primeiro lançamento. Na coluna boa."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "Valeu, {name}! A caravana sempre retribui uma gentileza. Geralmente com barbante."
L["How kind, {name}! You're on the caravan's good list now."] = "Que gentileza, {name}! Você entrou na lista boa da caravana."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "Ah, vou guardar isso, {name}! Eu guardo tudo. Toma um pra você."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "Valeu, {name}! Toma de volta. Bom, um seminovo. Quase sem uso."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "Minhas orelhas ficaram em pé, {name}. Quer dizer que fiquei muito feliz."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "Na fogueira de hoje, {name}, essa história vai ganhar um verme-da-areia. Valeu!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "Eu embrulharia o seu, {name}, mas meu papel de presente é o mapa velho de alguém."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "As alpacas viram, {name}. Vão contar pra todo mundo como você é gente boa. Valeu!"
L["Thank you, {name}! I'd give you my best button, but this is better. Slightly."] = "Valeu, {name}! Eu te daria meu melhor botão, mas isto é melhor. Um pouquinho."
L["Ooh, a present! Swapsies, {name}. Here's mine. No takebacks."] = "Oba, presente! Troca-troca, {name}. Toma o meu. Não vale destrocar."
L["Thanks, {name}! That goes in the good pouch. Not the rock pouch. The good one."] = "Valeu, {name}! Isso vai pra bolsinha boa. Não a das pedras. A boa."
L["In Vol'dun that would've cost a whole waterskin, {name}. Thank you!"] = "Em Vol'dun, isso custaria um cantil inteiro, {name}. Valeu!"
L["Thanks, {name}! Your name goes on the wagon. Between the alpaca and the dent."] = "Valeu, {name}! Seu nome vai pra carroça. Entre a alpaca e o amassado."
L["Kindness is the one thing the desert never buried, {name}. Thank you."] = "Gentileza é a única coisa que o deserto nunca enterrou, {name}. Valeu."
L["Rakera says repay quick, {name}, before you forget which pocket it's in. Here!"] = "A Rakera diz pra retribuir rápido, {name}, antes de esquecer em que bolso tá. Toma!"
L["Nobody's given me anything I didn't dig up first, {name}. Thank you!"] = "Ninguém me deu nada que eu não tivesse desenterrado antes, {name}. Valeu!"
L["Of course, {name}! Shake the sand out and hold still."] = "Claro, {name}! Sacuda a areia e não se mexa."
L["Coming right up, {name}! Caravan service, no waiting."] = "Saindo, {name}! Serviço de caravana, sem fila."
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "Claro, {name}! Deixa eu achar... corda, pedras, uma pedra bonita... achei!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "Peraí, {name}! O rabo tá no caminho, um instante... pronto!"
L["One {buff}, {name}! Only slightly sandy."] = "{buff} pra você, {name}! Só um pouquinho de areia."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "Peça a um vulpera e ganha alguma coisa, {name}. Geralmente esquisita. Hoje não!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "É seu, {name}! Vulpera adora dar coisas. Quase tanto quanto achar."
L["Here, {name}! Patched it up myself. Holds better than it looks."] = "Toma, {name}! Remendo meu. Segura melhor do que parece."
L["Sure, {name}! Stand upwind. Sandstorm last week; I'm still shedding it."] = "Claro, {name}! Fica do lado do vento. Teve tempestade; ainda tô soltando areia."
L["YES! Sorry, {name}, too loud? The desert's very big. You have to shout in it."] = "SIM! Foi mal, {name}, alto demais? O deserto é enorme. Lá tem que gritar."
L["Of course, {name}. Caravan rule: nobody asks twice for water or for help."] = "Claro, {name}. Regra da caravana: ninguém pede duas vezes água nem ajuda."
L["On it, {name}! Small spell, big fox, bigger ears. Wait. Other way round."] = "Opa, {name}! Feitiço pequeno, raposa grande, orelha maior. Pera. Ao contrário."
L["For you, {name}? Easy! Easier than getting sand out of an alpaca."] = "Pra você, {name}? Moleza! Mais fácil que tirar areia de alpaca."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "Todo viajante precisa de algo pra estrada, {name}. Conferi: não é pedra."
L["Keep this, {name}. The desert is long and the water is short."] = "Guarde isto, {name}. O deserto é longo e a água é pouca."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "Achei isso jogado por aí, {name}. Brincadeira! É fresquinho. Toma!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "Toma, {name}. A melhor coisa da minha mochila, e minha mochila é enorme."
L["In the dunes you share your shade and your spells, {name}. Here."] = "Nas dunas, a gente divide a sombra e os feitiços, {name}. Toma."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "{buff} pra você, {name}. Eu pechincharia, mas você tá com pressa."
L["A gift from the whole caravan, {name}! They'll never know."] = "Presente da caravana inteira, {name}! Eles nunca vão saber."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "Pra estrada, {name}. Estrada é a melhor parte. Estrada e lanchinho."
L["Here, {name}! I swapped a hat for a thing, and the thing for this. Good trade!"] = "Toma, {name}! Troquei um chapéu por um treco, e o treco por isto. Negócio bom!"
L["Nobody walks past anybody in the dunes, {name}. Bad luck, and rude. Here."] = "Nas dunas ninguém passa reto por ninguém, {name}. Dá azar e é feio. Toma."
L["My nose says trouble's ahead of you, {name}. Take this. My nose is never wrong."] = "Meu focinho diz que tem encrenca na sua frente, {name}. Toma. Meu focinho nunca erra."
L["Too many spells in my pack, {name}. They jingle. Take one, please."] = "Feitiço demais na mochila, {name}. Tão chacoalhando. Pega um, vai."
L["If you find anything shiny later, {name}, you know where my ears are. Here!"] = "Se achar algo brilhante depois, {name}, já sabe onde ficam minhas orelhas. Toma!"
L["Wait, {name}! You nearly left without this. Deserts eat people who do that."] = "Peraí, {name}! Quase saiu sem isto. O deserto engole quem faz isso."
L["Stew's not ready yet, {name}, so this is the starter."] = "O ensopado ainda não saiu, {name}, então isto é a entrada."
L["A fellow wanderer! The caravan is never far, {name}."] = "Gente da estrada! A caravana nunca está longe, {name}."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "Orelhas em pé, {name}! Sempre bom dividir um feitiço com outra raposa."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "De vulpera pra vulpera, {name}: tenho três colheres sobrando, se precisar."
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "Vol'dun criou a gente, {name}. Areia no pelo, sorte na mochila."
L["Ears to ears, {name}: between us we've heard everything said in this place."] = "Orelha com orelha, {name}: juntando as nossas, já ouvimos tudo que se disse aqui."
L["Remember the caravan fires, {name}? Everybody sang badly. It was perfect."] = "Lembra das fogueiras da caravana, {name}? Todo mundo cantava mal. Era perfeito."
L["Vol'dun's far behind us, {name}. Half of it followed us here in our fur."] = "Vol'dun ficou pra trás, {name}. Metade veio junto no nosso pelo."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "Regras da caravana, {name}: todo mundo junto, divide a água, ninguém vende a alpaca."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "Tudo que brilhar aí dentro, {name}, eu vi primeiro. Lei da caravana."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "Um pro grupo, {name}! Caravana só anda no ritmo da alpaca mais lenta."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "Deixa sua mochila fechada, {name}. Não pego as coisas por querer. Elas me seguem."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "Me perco em cidade, {name}, nunca em caverna. Caverna é só casa sem aluguel."
L["I'm small, {name}, so I'll check the tiny tunnels. You lot take the big ones."] = "Eu caibo nos túneis pequenos, {name}, deixa comigo. Vocês ficam com os grandes."
L["Shout if you need anything, {name}. I've probably got it. It's probably dented."] = "Grita se precisar de algo, {name}. Provavelmente eu tenho. Provavelmente amassado."
L["I'll walk at the back and pick up whatever we drop, {name}. Finders keepers."] = "Vou no fim da fila catando o que cair, {name}. Achado não é roubado."
L["A caravan with no wagon, {name}! Very fast. Very light. Nowhere to nap."] = "Caravana sem carroça, {name}! Rápida, levinha e sem lugar pra cochilar."
L["Scouted ahead, {name}. By nose. Smells of danger and very old cheese."] = "Fui na frente, {name}. De focinho. Cheira a perigo e a queijo vencido."
L["Everybody fed? Everybody watered? Good. Now this, {name}. Caravan order."] = "Comeram? Beberam água? Ótimo. Agora isto, {name}. Ordem da caravana."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "Vulpera viaja à noite, {name}. Areia fresca, escorpídeos com sono."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "Noite no deserto esfria, {name}. Toma, algo meio quentinho."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "Estrelas no céu, {name}. Cada uma é uma placa, se você souber ler. Eu não sei."
L["Good hour for foxes, {name}. The ears work best when everything's quiet."] = "Hora das raposas, {name}. No silêncio, estas orelhas ouvem até pensamento."
L["Past dark and I'm just waking up, {name}. In the dunes, noon's for napping."] = "Escureceu e eu mal acordei, {name}. Nas dunas, meio-dia é hora da sesta."
L["I'll curl up in my tail later, {name}. Best blanket I own. First, this."] = "Depois me enrolo no rabo, {name}. É meu melhor cobertor. Primeiro, isto."
L["A kindness returned is a kindness doubled, {name}."] = "Gentileza retribuída é gentileza em dobro, {name}."
L["Thank you, {name}. You have restored my balance."] = "Agradeço, {name}. Você restaurou meu equilíbrio."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "Em algum lugar, um Sha acabou de passar fome. Agradeço, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "Agradeço, {name}. Aysa faria reverência, Ji comemoraria. Eu faço os dois, mal."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "Agradeço, {name}. Vou pensar em você na próxima refeição, e na seguinte."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "Chen sempre dizia: nunca recuse um presente. Nem uma bebida. Agradeço, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "Eu ia tirar um cochilo, {name}, mas isto é melhor. Um pouco. Agradeço."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "Um hozen teria jogado alguma coisa, {name}. Tive outra criação. Agradeço."
L["That was very pandaren of you, {name}. All that's missing is a dumpling."] = "Isso foi muito pandaren da sua parte, {name}. Só faltou um bolinho."
L["At Halfhill that earns a prize turnip, {name}. I left mine at home. Thank you."] = "Em Meia Colina isso ganha nabo premiado, {name}. O meu ficou em casa. Agradeço."
L["Grandmother kept a jar of kindnesses, {name}. Yours goes in; this comes out."] = "Vovó guardava um pote de gentilezas, {name}. A sua entra; esta aqui sai."
L["Thank you, {name}. In the Jade Forest my door is open, and my pantry more so."] = "Agradeço, {name}. Na Floresta de Jade, porta aberta e despensa escancarada."
L["You move like the Shado-Pan, {name}. I never saw that coming. Thank you."] = "Você se move como os Shado-Pan, {name}. Nem vi chegar. Agradeço."
L["Like rain on a rice paddy, {name}. The paddy never says thank you. I do."] = "Como chuva no arrozal, {name}. O arrozal nunca agradece. Eu agradeço."
L["Thank you, {name}. Li Li would put this in her travel journal. With drawings."] = "Agradeço, {name}. Li Li poria isto no diário de viagem dela. Com desenhos."
L["Thank you, {name}. The August Celestials are busy, so I thank you for all four."] = "Os Celestiais Majestosos estão ocupados, {name}, então agradeço pelos quatro."
L["Stormstout ale knocks a pandaren flat, {name}. So did that. Thank you."] = "Cerveja Malte do Trovão derruba um pandaren, {name}. Isso também. Agradeço."
L["Now we are square, {name}. The first time anyone has called a pandaren square."] = "Agora estamos quites, {name}. Conta redondinha, como todo bom pandaren."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "Claro, {name}. Paciência, e está feito. A paciência é a parte lenta."
L["With pleasure, {name}. A kind deed is never wasted."] = "Com prazer, {name}. Uma boa ação nunca é desperdiçada."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "Agora mesmo, {name}. Rápido pra um pandaren, o que não quer dizer muito."
L["Master Shang Xi said: help whoever asks, {name}. He also said: duck."] = "Mestre Shang Xi disse: ajude quem pedir, {name}. Também disse: abaixe-se."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "Um mestre Tushui te faria meditar antes, {name}. Vou pular essa parte."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "Tudo por você, {name}. Menos o último bolinho. Aí também não."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff} bem forte, {name}. A receita é segredo."
L["Stand like a crane, {name}: one leg, calm face. Two legs is also fine."] = "Fique feito garça, {name}: uma perna, rosto calmo. Duas pernas também serve."
L["We never refuse a request, {name}. Only second helpings. No, not those either."] = "Pandaren não recusa pedido, {name}. Só repeteco. Não, repeteco também não."
L["The last to ask me for help, {name}, was an island-sized turtle. You're easier."] = "O último a pedir minha ajuda, {name}, foi uma tartaruga-ilha. Você é mais fácil."
L["Pandaren help like we cook, {name}: slowly, generously, and far too much of it."] = "Pandaren ajuda como cozinha, {name}: devagar, com fartura e sempre demais."
L["Certainly, {name}. Let me put down my bowl. ...There. That was the hard part."] = "Claro, {name}. Deixe-me largar a tigela. ...Pronto. Essa era a parte difícil."
L["Yes, {name}. Grandfather said never make guests ask twice. He said it twice."] = "Sim, {name}. Vovô dizia: visita não pede duas vezes. Dizia isso duas vezes."
L["Hold still, {name}. I am calm, you are calm, the spell is calm. Nobody panic."] = "Não se mexa, {name}. Eu na calma, você na calma, o feitiço na calma. Sem pânico."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "Tome, {name}. E depois, quem sabe, uma xícara de chá?"
L["Balance in all things, {name}. Now go with a light heart."] = "Equilíbrio em tudo, {name}. Agora vá de coração leve."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "Tome, {name}. Um grummle te venderia isto por um amuleto da sorte."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "Os jinyu dizem que as águas previram isso, {name}. Eles dizem muito isso."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "Os Huojin dizem: aja primeiro. Os Tushui: pense primeiro. Eu digo: tome, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "Levantei pra te dar isto, {name}. Pandaren de pé é raro. Dê valor."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "Lute como um monge, {name}: calma, rapidez e depois um almoço demorado."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "Vá com calma, {name}. Devagar se vai ao longe; que o diga a tartaruga."
L["You looked like you needed a hug, {name}. This is next best, and less furry."] = "Você parecia precisar de um abraço, {name}. Isto chega perto, e solta menos pelo."
L["If a fight finds you, {name}, roll away. Rolling is very underrated."] = "Se o combate te achar, {name}, role para longe. Rolar é muito subestimado."
L["For you, {name}. It is warm, round and full of good intentions. Like me."] = "Para você, {name}. É quentinho, redondo e cheio de boas intenções. Como eu."
L["Take this, {name}. My kite is stuck in a tree, so I have time for good deeds."] = "Tome, {name}. Minha pipa ficou presa na árvore; sobrou tempo pra boas ações."
L["I carried this from Pandaria, {name}. Also a keg. The keg is mine."] = "Trouxe isto de Pandária, {name}. E um barril. O barril é meu."
L["The virmen stole my carrots, {name}, but this they will never get. Here."] = "Os virmen roubaram minhas cenouras, {name}, mas isto nunca vão pegar. Tome."
L["On the Wandering Isle, {name}, strangers get soup. This travels better."] = "Na Ilha Errante, {name}, estranho ganha sopa. Isto viaja melhor."
L["Pandaren look soft, {name}. So does a sack of rice, until it lands on you."] = "Pandaren parece fofo, {name}. Saco de arroz também, até cair em cima de você."
L["Chi-Ji says there is always hope, {name}. I say there is always a spare. Here."] = "Chi-Ji diz que sempre há esperança, {name}. Eu digo que sempre sobra um. Tome."
L["We must share a brew when the road allows, {name}!"] = "Vamos dividir uma cerveja quando der, {name}!"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "Shen-zin Su teria orgulho de nós, {name}. Ou estaria dormindo. Difícil saber."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "Pandaren em dobro, {name}. Em algum lugar, um estalajadeiro sentiu um calafrio."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "Liu Lang aprovaria, {name}: a gente aqui, tão longe de casa."
L["Tushui or Huojin, {name}, we both left the turtle, and we both miss the food."] = "Tushui ou Huojin, {name}, saímos da tartaruga e sentimos falta da comida."
L["One pandaren to another, {name}: the brews out here are thin. Share mine later."] = "De pandaren pra pandaren, {name}: a cerveja daqui é aguada. Depois prove a minha."
L["We both smell of rice wine and road dust, {name}. The smell of home."] = "Cheiramos a vinho de arroz e poeira de estrada, {name}. Cheiro de casa."
L["Pandaren look after pandaren, {name}. Mostly by feeding them. This comes first."] = "Pandaren cuida de pandaren, {name}. Quase sempre com comida. Isto é a entrada."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "Primeiro o combate, depois a comida, {name}. Nessa ordem. Nunca ao contrário."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "Todo mundo junto, {name}, como bolinhos no vapor. Quentinhos e no ponto."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "Nos movemos como um só, {name}. Devagar, talvez, mas como um só."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "Equilíbrio, {name}: um luta, um cura e um carrega os petiscos. Eu."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "Se cairmos, {name}, caímos juntos e depois cochilamos. Melhor não."
L["Stay behind me, {name}. I am soft, but I am very wide."] = "Atrás de mim, {name}. Sou pura fofura e muita largura."
L["If we win, {name}, I will cook. If we lose, I will also cook, but sadly."] = "Vencendo, {name}, eu cozinho. Perdendo, cozinho também, só que chorando."
L["Everyone breathe, {name}. In, and out. Now hit things, calmly."] = "Respirem, {name}. Inspira... expira. Agora batam em tudo, com calma."
L["Keep up, {name}. I am in a hurry. It happens to pandaren about once a decade."] = "Acompanhe, {name}. Estou com pressa. Acontece com pandaren uma vez por década."
L["A party is like a brew, {name}: odd ingredients, wonderful together. Mostly."] = "Grupo é como cerveja, {name}: ingredientes estranhos, ótimos juntos. Quase sempre."
L["If I fall, {name}, roll me somewhere safe. Carrying me is not an option."] = "Se eu cair, {name}, me role para um lugar seguro. Me carregar não é opção."
L["Pandaren fight like water, {name}: calm, patient, and then suddenly everywhere."] = "Pandaren luta como a água, {name}: calmo, paciente e, de repente, em todo lugar."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "De pé antes do chá, {name}? Que coragem. Tome, no lugar do chá."
L["Morning, {name}. First this, then breakfast, then the second breakfast."] = "Bom dia, {name}. Primeiro isto, depois o café da manhã, depois o segundo café."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "Um novo dia, {name}, e ninguém derramou nada ainda. Vamos começar com calma."
L["Halfhill's farmers have been up for hours, {name}. I have been up for minutes."] = "Os fazendeiros de Meia Colina estão de pé há horas, {name}. Eu, há minutos."
L["Morning mist, {name}. It looked just like home. Then a kobold walked by."] = "Névoa da manhã, {name}. Parecia até minha terra. Aí passou um kobold."
L["Good morning, {name}. My stomach woke first and has been giving orders since."] = "Bom dia, {name}. Meu estômago acordou primeiro e está dando ordens desde então."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "Depois do primeiro cochilo e antes do segundo, {name}. Rápido, enquanto não durmo."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "Tarde, {name}. Os mestres cervejeiros dormem. As cervejas, suspeito, não."
L["Midnight snack time, {name}. This is the appetiser."] = "Hora do lanchinho da meia-noite, {name}. Isto é o aperitivo."
L["Dark already, {name}? Back home, Grandfather's stories would just be starting."] = "Já escureceu, {name}? Lá em casa, as histórias do vovô estariam só começando."
L["The moon is round and full tonight, {name}. We have a great deal in common."] = "A lua está redonda e cheia hoje, {name}. Temos muito em comum."
L["Your kindness is noted, {name}. Dragons do not forget."] = "Sua gentileza foi notada, {name}. Dragões não esquecem."
L["Thank you, {name}. Returned on swift wings."] = "Agradeço, {name}. De volta em asas velozes."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "Asas, fogo e escamas, {name}, e ainda achou que eu precisava de ajuda. Comovente."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "Faria uma reverência, {name}, mas na última minhas asas varreram a mesa. Agradeço."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "Isso vai direto pro meu tesouro, {name}. Boas ações são o único ouro que guardo."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "Me criaram para ser arma, {name}. Prefiro muito esta parte. Agradeço."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "Agradeço, {name}. Wrathion faria um discurso disso. Eu não."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "Retribuído com um pouco de fogo, {name}. Só um pouco. Estou treinando."
L["A mortal gift, {name}: small, brief and kind. I am learning to like all three."] = "Um presente de mortal, {name}: pequeno, breve e gentil. Aprendo a gostar dos três."
L["Thank you, {name}. Mortal customs are new to me. Do I pay you? No? Then this."] = "Agradeço, {name}. Ainda aprendo os costumes mortais. Eu pago? Não? Então, isto."
L["Thank you, {name}. I have scales where most have feelings. That got through."] = "Agradeço, {name}. Onde os outros têm sentimentos, tenho escamas. Essa passou."
L["You're on my list of favourite mortals, {name}. It was empty until today."] = "Você está na minha lista de mortais favoritos, {name}. Estava vazia até hoje."
L["The red in me is grateful, {name}. The black in me is suspicious. The red wins."] = "O vermelho em mim agradece, {name}. O negro em mim desconfia. O vermelho vence."
L["Thank you, {name}. My wings would clap, but wings don't do that. I checked."] = "Agradeço, {name}. Minhas asas aplaudiriam, mas asas não fazem isso. Já testei."
L["A dragon's thanks comes with a roar, {name}. I will spare the neighbours."] = "Agradecimento de dragão vem com rugido, {name}. Vou poupar os vizinhos."
L["Very well, {name}. Stand still, I would hate to singe you."] = "Muito bem, {name}. Não se mexa, eu odiaria te chamuscar."
L["Granted, {name}. A dragon keeps its word."] = "Concedido, {name}. Um dragão honra a palavra."
L["Certainly, {name}. Stand clear of the tail."] = "Certamente, {name}. Cuidado com a cauda."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "Claro, {name}. Ainda é assim que se faz? Dormi por um tempinho."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "Com prazer, {name}. As cinco revoadas vivem em mim, e as cinco dizem sim."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "É pra já, {name}. Ajuda do tamanho de um dragão, em formato de bolso."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "Claro, {name}. Neltharion só dava ordens. Um pedido é bem mais agradável."
L["Right away, {name}. Stand back a little; I am still learning how big I am."] = "É pra já, {name}. Afaste-se um pouco; ainda estou aprendendo meu tamanho."
L["Certainly, {name}. Hold still. I have excellent aim and very little practice."] = "Certamente, {name}. Não se mexa. Tenho ótima mira e pouquíssima prática."
L["Of course, {name}. Dragons usually demand tribute. I'm waiving it, this once."] = "Claro, {name}. Dragões costumam exigir tributo. Desta vez, dispenso."
L["Of course, {name}. Please don't scream. Mortals often do. It's the horns."] = "Claro, {name}. Por favor, não grite. Mortais costumam gritar. São os chifres."
L["My breath is fire, {name}, so we will do this the other way."] = "Meu sopro é de fogo, {name}, então vamos fazer do outro jeito."
L["Gladly, {name}. In my day... no. I promised to stop saying 'in my day'. Here."] = "Com prazer, {name}. No meu tempo... não. Jurei parar com o 'no meu tempo'. Tome."
L["A small magic, {name}, but I cast it with enormous dignity."] = "Uma magia pequena, {name}, mas lançada com enorme dignidade."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "Tome, {name}. Até um dragão precisa de aliados. Ainda mais um desse tamanho."
L["A gift from the Dragon Isles, {name}. Fly well."] = "Um presente das Ilhas do Dragão, {name}. Bom voo."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "Alexstrasza diz que toda vida é preciosa, {name}. Começo pela sua."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "Dormi dez mil anos de boas ações, {name}. Estou tirando o atraso."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "Diga que foi um dragão, {name}. Soa bem mais grandioso do que foi."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "Ordens de comandante, {name}. Não sou comandante, mas vale assim mesmo."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "Tome, {name}. Magia dracônica ancestral, só um pouquinho fora da validade."
L["A dragon giving, {name}, not taking. I am trying something new."] = "Um dragão que doa em vez de tomar, {name}. Estou experimentando algo novo."
L["In visage form I look harmless, {name}. So did Lady Prestor. I really am."] = "Em visagem pareço um doce, {name}. Lady Prestor também parecia. Eu sou mesmo."
L["A gift from above, {name}. I landed specially. It took two tries."] = "Presente dos céus, {name}. Pousei só para isso. Na segunda tentativa."
L["Here, {name}. Every dragon should guard something. I have chosen you, for now."] = "Tome, {name}. Todo dragão precisa guardar algo. Escolhi você, por enquanto."
L["Take this, {name}. It's from five dragonflights, so it clashes with everything."] = "Tome, {name}. Vem de cinco revoadas, então não combina com nada."
L["I'd fly you there myself, {name}, but I'm told that is 'kidnapping'. Take this."] = "Eu te levaria voando, {name}, mas dizem que isso é 'sequestro'. Tome isto."
L["Dragons gifted the world at its dawn, {name}. Mine is smaller, and later."] = "Dragões presentearam o mundo na aurora, {name}. O meu é menor, e atrasado."
L["A little essence for you, {name}. It is what I'm made of, so handle it gently."] = "Um pouco de essência para você, {name}. É minha matéria-prima; trate com carinho."
L["Take this, {name}. It will feel warm. Most things do, after I touch them."] = "Tome, {name}. Vai parecer quentinho. Quase tudo fica, depois que eu toco."
L["The Forbidden Reach feels far behind us now, {name}."] = "Os Confins Proibidos parecem tão distantes agora, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "Dois dracthyr no mesmo lugar, {name}. Cuidado com as asas; não cabem quatro."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "Lembra quando o mundo todo era novidade, {name}? Ainda é, quase todo."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "Em visagem ninguém percebe, {name}. Cá entre nós: de escamas ficamos melhor."
L["Made for war, {name}, and look at us: sharing. Somebody's plans went wrong."] = "Nascemos para a guerra, {name}, e olha só: dividindo. O plano de alguém falhou."
L["Visage or scales, {name}, I would know one of us anywhere. It is the posture."] = "Visagem ou escamas, {name}, reconheço um dos nossos em qualquer lugar. É a postura."
L["Mortals always ask us the same thing, {name}: will we fly them. Still no."] = "Mortais sempre pedem a mesma coisa, {name}: uma carona voando. Ainda é não."
L["Between two dracthyr, {name}: the horns never get any easier with hats."] = "Cá entre dracthyr, {name}: chapéu com chifre nunca fica mais fácil."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "Me avise quando cuspir fogo, {name}. E, por favor, quando não."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "Acordei numa caverna cheia de estranhos, {name}. Esta companhia é bem melhor."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "Neltharion nos fez para lutar sozinhos, {name}. Melhoramos o projeto dele."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "Cuidado com minha cauda, {name}. Ela ainda não aprendeu de que lado está."
L["A flight of our own, {name}. So this is what the dragons meant."] = "Uma revoada só nossa, {name}. Então era disso que os dragões falavam."
L["If I say 'take cover', {name}, I mean behind my wings. They are good for that."] = "Se eu gritar 'abriguem-se', {name}, é atrás das minhas asas. Servem pra isso."
L["Stand beside me, {name}, never in front. I cannot aim my breath politely."] = "Fique do meu lado, {name}, nunca na frente. Meu sopro não tem boas maneiras."
L["Leave the big ones to me, {name}. Well, the ones smaller than me. That is most."] = "Deixe os grandes comigo, {name}. Bem, os menores que eu. Quase todos."
L["Stay close, {name}. I can glide us all down from anywhere. Up is your problem."] = "Fique perto, {name}. Desço todo mundo planando de onde for. Subir é com você."
L["Keep moving, {name}. A dragon in a hurry is grand. One waiting is just big."] = "Não pare, {name}. Dragão com pressa impressiona. Dragão parado só ocupa espaço."
L["Tell me the plan slowly, {name}. I was made for battles, not for plans."] = "Explique o plano devagar, {name}. Me criaram para batalhas, não para planos."
L["Mortals live so briefly, {name}. Let us not make today any shorter."] = "Mortais vivem tão pouco, {name}. Não vamos encurtar o dia de hoje."
L["It is good to see one of our own, {name}."] = "É bom ver alguém do nosso povo, {name}."
L["Our people are few, {name}. That makes each of us count."] = "Somos poucos, {name}. Por isso cada um de nós conta."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "Agradeço, {name}. A Aliança cuida dos seus, e hoje foi a minha vez."
L["Kindness answered, {name}. For the Alliance!"] = "Gentileza retribuída, {name}. Pela Aliança!"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "Ventobravo tem estátua para cada herói, {name}. Vou indicar a sua."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "O jeito da Aliança, {name}: você me ajuda, eu te ajudo, e um anão paga a rodada."
L["Genn would growl, Muradin would hug, {name}. I'll just return it."] = "Genn rosnaria, Muradin daria um abraço, {name}. Eu só retribuo."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "Se a Aliança desse medalha por educação, {name}, você precisaria de outro tabardo."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "Retribuído por inteiro, {name}. Quem dá primeiro vale uma guarnição inteira."
L["Thank you, {name}. I'll mention you in my letter home. Mother reads them aloud."] = "Agradeço, {name}. Vou citar você na carta para casa. Mamãe lê em voz alta."
L["The Lion's Pride will hear of this, {name}. At length. Thank you."] = "No Orgulho do Leão vão ouvir tudo, {name}. Tim-tim por tim-tim. Agradeço."
L["The Alliance at its finest, {name}: nobody asked, somebody helped. Thanks."] = "A Aliança no seu melhor, {name}: ninguém pediu, alguém ajudou. Agradeço."
L["I'll tell everyone on the Deeprun Tram, {name}. It's a long tram. Thank you."] = "Vou contar a todos no Metrô Correfundo, {name}. A viagem é longa. Agradeço."
L["Most gallant, {name}. If I had a lion on my tabard, it would be purring."] = "Que galanteria, {name}. Se meu tabardo tivesse um leão, estaria ronronando."
L["Our kings bicker, {name}, but their people get on splendidly. Thank you."] = "Nossos reis vivem brigando, {name}, mas o povo se dá muito bem. Agradeço."
L["The Alliance was forged by folk keeping their word, {name}. Here's mine."] = "A Aliança foi forjada por gente de palavra, {name}. Aqui está a minha."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "Claro, {name}. Aliados se ajudam. Está praticamente no nome."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "Agora mesmo, {name}. A Aliança não deixa nenhum amigo na mão."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "Claro, {name}. Está no estatuto da Aliança. Lá pelas últimas páginas."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "Por ordem da Aliança, {name}: {buff}, com efeito imediato."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "Tudo por um aliado, {name}. Dentro do razoável. E isto é bem razoável."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "É pra já, {name}. O SI:7 sabia que você ia pedir. Eu acabei de saber."
L["Straight away, {name}. The Alliance marches on requests like yours. And bread."] = "Agora mesmo, {name}. A Aliança marcha movida a pedidos como o seu. E a pão."
L["Yes, {name}. From Stormwind to Ironforge, 'please' opens every gate."] = "Sim, {name}. De Ventobravo a Altaforja, 'por favor' abre qualquer portão."
L["Right away, {name}. I've worn the blue all day hoping somebody would ask."] = "É pra já, {name}. Passei o dia de azul esperando alguém pedir."
L["Hold still, {name}. I learned this faster than the Alliance anthem."] = "Não se mexa, {name}. Aprendi isto mais rápido que o hino da Aliança."
L["Of course, {name}. Armies win wars; small favours win allies. Here's one."] = "Claro, {name}. Exércitos vencem guerras; favores ganham aliados. Aqui vai um."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "Pela Aliança, {name}! Força lá fora. Agora, mais força ainda."
L["Onward, {name}. The Alliance is with you."] = "Avante, {name}. A Aliança está com você."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "Tome, {name}. Se fosse obra de gnomo, viria com doze alavancas."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "Cortesia da Aliança, {name}. Fazemos isso desde a Segunda Guerra."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "Ânimo, {name}. Em Ventobravo, um bardo já está compondo sobre isto."
L["Every ally counts, {name}. I counted, actually. You're my favourite so far."] = "Todo aliado conta, {name}. Eu contei, aliás. Você está no topo da lista."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "Anduin ia querer que eu dividisse, {name}, e eu odiaria decepcioná-lo."
L["Take this, {name}. Stormwind's walls can't follow you, so this will have to."] = "Tome, {name}. As muralhas de Ventobravo não podem te seguir, então isto segue."
L["Here, {name}. The gryphons get you there; this gets you back."] = "Tome, {name}. O grifo te leva; isto te traz de volta."
L["Alliance rule, {name}: keep your word, your walls, your friends. Here, friend."] = "Regra da Aliança, {name}: guarde a palavra, as muralhas e os amigos. Começo por você."
L["Every ally deserves a lion at their back, {name}. I'm the nearest lion."] = "Todo aliado merece um leão na retaguarda, {name}. Sou o leão mais próximo."
L["A gift from the Alliance, {name}. Signed, sealed and hand-delivered."] = "Presente da Aliança, {name}. Assinado, selado e entregue em mãos."
L["The Alliance never forgets the brave, {name}. Give it something to remember."] = "A Aliança nunca esquece os bravos, {name}. Dê a ela algo para lembrar."
L["Together we stand, {name}. For the Alliance!"] = "Juntos, ninguém nos derruba, {name}. Pela Aliança!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "Certo, {name}: escudos no alto, cabeças baixas, e ninguém avança antes do plano."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "A melhor tropa que a Aliança já teve, {name}. Ou pelo menos a mais perto."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "Juntos, {name}, somos quase um regimento. Um regimento pequeno e bem-vestido."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "Um cuida das costas do outro, {name}. A Aliança foi erguida por quem fazia isso."
L["Shields together, {name}. The Alliance never won anything in single file."] = "Escudos juntos, {name}. A Aliança nunca venceu nada em fila indiana."
L["If this goes in the history books, {name}, let's be a chapter, not a footnote."] = "Se isto for parar na história, {name}, que seja capítulo, não nota de rodapé."
L["Whoever carries the banner, {name}, gets painted looking noble. Volunteers?"] = "Quem levar o estandarte, {name}, sai no quadro com cara de nobre. Voluntários?"
L["Dwarven nerve, elven patience, human stubbornness, {name}: the Alliance recipe."] = "Coragem de anão, paciência de elfo, teimosia humana, {name}: a receita da Aliança."
L["Keep the lion roaring, {name}. Softly, mind. We're sneaking."] = "Mantenha o leão rugindo, {name}. Baixinho. Estamos na surdina."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "Força e honra, {name}. E gentileza, pelo visto. Retribuída por inteiro."
L["The Horde takes care of its own, {name}."] = "A Horda cuida dos seus, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "Força dada, força devolvida, {name}. Essa é toda a diplomacia da Horda."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "Eu gravaria seu nome nos portões de Orgrimmar, {name}, mas estão lotados. Valeu."
L["Gallywix would've sent you an invoice, {name}. I'm sending this instead."] = "Gallywix teria mandado uma fatura, {name}. Eu mando isto."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "Você não precisava fazer isso, {name}. Por isso a Horda não esquece."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "Na Horda não se agradece duas vezes, {name}. Então: uma vez, e de verdade."
L["In the Horde a debt is carried like an axe, {name}: openly, and not for long."] = "Na Horda, dívida se carrega como machado, {name}: à vista, e por pouco tempo."
L["The gate grunts will hear of you, {name}. They'll grunt. It means respect."] = "Os guardas do portão vão saber de você, {name}. Vão grunhir. É respeito."
L["The Horde keeps two lists, {name}: grudges and favours. Yours is the short one."] = "A Horda tem duas listas, {name}: rancores e favores. A sua é a curta."
L["Honour says repay you, {name}. Manners say smile. I'm working on the smile."] = "A honra manda retribuir, {name}. A educação manda sorrir. O sorriso tá em treino."
L["That landed softer than any zeppelin I've ridden, {name}. Thank you."] = "Pousou mais suave que qualquer zepelim em que já andei, {name}. Valeu."
L["Thanks, {name}, in Orcish, Zandali, Thalassian and Gutterspeak. Pick one."] = "Valeu, {name}, em órquico, zandali, talassiano e língua dos Renegados. Escolha."
L["Thrall taught the Horde honour, {name}. Nobody had to teach you. Thank you."] = "Thrall ensinou honra à Horda, {name}. Ninguém precisou te ensinar. Valeu."
L["You gave first, {name}. In the Horde that earns first cut of the roast. Here."] = "Você deu primeiro, {name}. Na Horda, isso vale a primeira fatia do assado. Tome."
L["The Warchief can't thank everyone himself, {name}. He's delegated it to me."] = "O Chefe Guerreiro não pode agradecer a todos, {name}. Delegou a tarefa para mim."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "Considere feito, {name}. Pela Horda, e por quem pede com educação."
L["You only had to ask, {name}. The Horde answers."] = "Era só pedir, {name}. A Horda responde."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "A Horda costuma ajudar com machados, {name}. Hoje, com {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "Feito, {name}. Sem discurso. A Horda já tem discurso de sobra."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "Você pediu, {name}. Em Orgrimmar, isso vale como tratado formal."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "Pedir não é fraqueza, {name}. Recusar um aliado seria."
L["No need to bang a war drum, {name}. You asked; it's done."] = "Nem precisa bater o tambor de guerra, {name}. Pediu, tá feito."
L["Of course, {name}. In the Horde, 'please' outranks everyone but the Warchief."] = "Claro, {name}. Na Horda, 'por favor' só perde em patente para o Chefe Guerreiro."
L["In Orgrimmar we'd have argued about it first, {name}. Tradition. Here."] = "Em Orgrimmar, a gente ia discutir isso antes, {name}. Tradição. Tome."
L["Consider it requisitioned, {name}. The quartermaster needn't hear about it."] = "Considere requisitado, {name}. O intendente não precisa ficar sabendo."
L["Done, {name}. If anyone asks, I scowled the whole time. I've a reputation."] = "Feito, {name}. Se perguntarem, fiz cara feia o tempo todo. Tenho uma reputação."
L["Of course, {name}. Horde hospitality: rough edges, full helpings."] = "Claro, {name}. Hospitalidade da Horda: modos brutos, pratos cheios."
L["The Horde came together because somebody always said yes, {name}. Yes."] = "A Horda se uniu porque alguém sempre disse sim, {name}. Sim."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "Pela Horda, {name}! Vá com força. Acabei de te dar um pouco."
L["Go with honour, {name}. Victory awaits."] = "Vá com honra, {name}. A vitória espera."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "Vá fazer algo digno de canção, {name}. Canção alta. A Horda gosta de barulho."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "Cabeça erguida, {name}. A Horda sempre abriu espaço para quem o mundo rejeitou."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "Tome, {name}, e um conselho da Horda: bata primeiro, peça desculpas nunca."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "Vitória ou morte, {name}. Prefiro a vitória, então tome isto."
L["Like a mak'gora, {name}, except everybody wins. Here."] = "Tipo um mak'gora, {name}, só que todo mundo ganha. Tome."
L["For the Horde, {name}, and for you. The Horde's big; you're closer."] = "Pela Horda, {name}, e por você. A Horda é grande; você está mais perto."
L["Here, {name}. Stronger together, they say, and I've just done my half."] = "Tome, {name}. Dizem que juntos somos mais fortes. Minha metade, feita."
L["Carry this, {name}. It weighs less than a Horde banner and flies just as proud."] = "Leve isto, {name}. Pesa menos que o estandarte da Horda e tremula com igual orgulho."
L["Here, {name}. The Horde feeds its own, arms its own, and now enchants them."] = "Tome, {name}. A Horda alimenta os seus, arma os seus, e agora encanta os seus."
L["Take this, {name}. Whatever's out there is about to meet the Horde."] = "Tome, {name}. Seja o que for que está lá fora, vai conhecer a Horda."
L["Here, {name}. Wherever you're headed, arrive looking like the Horde sent you."] = "Tome, {name}. Aonde for, chegue como se a Horda tivesse te mandado."
L["The Crossroads never turned a traveller away, {name}. It overcharged a few."] = "A Encruzilhada nunca recusou um viajante, {name}. Só cobrou caro de alguns."
L["The Horde raises you tough, {name}. This is for the days tough isn't enough."] = "A Horda cria a gente na raça, {name}. Isto é pros dias em que raça não basta."
L["Take this, {name}. A Horde gift: no ribbon, no speech, no refunds."] = "Tome, {name}. Presente da Horda: sem laço, sem discurso, sem devolução."
L["Stand tall, {name}. Taller than that. The Horde has tauren to keep up with."] = "Postura, {name}. Mais alto que isso. A Horda tem tauren para acompanhar."
L["Our strength is each other, {name}. For the Horde!"] = "Nossa força está na união, {name}. Pela Horda!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "Avante, {name}. A Horda avança unida. Recuar... nunca, oficialmente."
L["Together we're a war band, {name}. Apart, we're just loud."] = "Juntos somos um bando de guerra, {name}. Separados, só um bando barulhento."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "Ombro a ombro, {name}. Quem avançar primeiro paga o grogue."
L["Nobody gets left behind, {name}. I've counted us twice."] = "Ninguém fica para trás, {name}. Já contei todo mundo duas vezes."
L["Rule of the warband, {name}: nobody eats until everybody's back."] = "Regra do bando, {name}: ninguém come até todo mundo voltar."
L["Drums up, {name}. If we can't be quiet, we'll be terrifying."] = "Tambores, {name}! Se não dá pra ter silêncio, que seja terror."
L["The Horde never won a thing alone, {name}. Let's not start now."] = "A Horda nunca venceu nada sozinha, {name}. Não vamos começar agora."
L["We fight like the Horde, {name}: all at once, and nobody waits for the signal."] = "Lutamos como a Horda, {name}: todo mundo junto, e ninguém espera o sinal."
L["Right, {name}. Loot shared, blame shared, glory to whoever shouts first."] = "Certo, {name}. Saque dividido, culpa dividida, glória a quem gritar primeiro."
L["Look at us, {name}. The Warchief would be proud. Mildly. From a distance."] = "Olha a gente, {name}. O Chefe Guerreiro teria orgulho. Um pouco. De longe."
L["Tusks, horns, long ears and bare bone, {name}. Finest warband going."] = "Presas, chifres, orelhões e osso exposto, {name}. Melhor bando do mundo."
L["The war stories get bigger after, {name}. Let's give them a head start."] = "As histórias de guerra crescem depois, {name}. Vamos dar um empurrãozinho."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "Agradeço, {name}. Há bons corações em todo lado, e pelo visto aqui também."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "Agradeço, {name}. Sem lado, sem título, só gentileza. Lendas começam assim."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "Agradeço, {name}. Gentileza não tem facção. Que bom, porque eu também não."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "Agradeço, {name}. O lado que ficar com você vai fazer um ótimo negócio."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "Qualquer que seja meu lado no fim, {name}, você vem primeiro. Agradeço."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "Neutralidade total, {name}, mas gratidão não conta. Agradeço."
L["Thank you, {name}. I carry no banner, so both hands are free to return this."] = "Agradeço, {name}. Sem estandarte, fico com as duas mãos livres pra retribuir."
L["The Steamwheedle stay neutral for gold, {name}. I do it for moments like this."] = "Os goblins ficam neutros por ouro, {name}. Eu, por momentos assim."
L["Neither side has taught me their thanks yet, {name}, so here's the plain kind."] = "Nenhum lado me ensinou seu jeito de agradecer, {name}, então vai o simples."
L["Thank you, {name}. I stand between two great banners, and still you noticed me."] = "Agradeço, {name}. Entre dois estandartes enormes, e mesmo assim você me notou."
L["Two sides at war, {name}, and us being lovely right in the middle. Thank you."] = "Dois lados em guerra, {name}, e a gente sendo um amor bem no meio. Agradeço."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "Com prazer, {name}, seja qual for sua bandeira. Eu nem tenho uma."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "Certamente, {name}. Ajudo todo mundo. É a única coisa que já decidi."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "Todo mundo pergunta de que lado estou, {name}. Bem melhor me pedirem ajuda."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "Claro, {name}. Sem conselho de guerra para consultar; só eu, e eu digo sim."
L["Here you are, {name}. No oath, no colours, no fee."] = "Aqui está, {name}. Sem juramento, sem bandeira, sem taxa."
L["I can't pick a side yet, {name}, but I can pick a good cause. This is one."] = "Lado eu ainda não escolho, {name}, mas causa boa, sim. Esta é uma."
L["At once, {name}. I have no side to be on, so for now I am entirely on yours."] = "Agora mesmo, {name}. Não tenho lado, então por enquanto meu lado é o seu."
L["Of course, {name}. Nobody pays me to take sides, so I take requests instead."] = "Claro, {name}. Ninguém me paga para tomar partido, então tomo pedidos."
L["Neutral does not mean unwilling, {name}. It means I help first and argue never."] = "Neutralidade não é má vontade, {name}. É ajudar primeiro e discutir nunca."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "Amigos podem vir de qualquer lado, {name}. Ou, como eu, de lado nenhum."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "Logo vão nos dar tabardos, {name}. Até lá, cuidamos um do outro."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "Ainda não escolhi um lado, {name}, então sou gentil com os dois. Tome."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "Presente sem rabo preso, {name}. Eu nem tenho facção para me prender."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "Vá em frente, {name}. Duas facções inteiras esperam para brigar por nós."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "Ainda sem intendente, {name}, ninguém está contando. Pode pegar à vontade."
L["Take this, {name}. Neutral ground travels with me; you're standing on some."] = "Tome, {name}. Terreno neutro anda comigo; você está pisando nele."
L["The Argent Dawn helps whoever needs it, {name}. I'm learning from the best."] = "A Aurora Argêntea ajuda quem precisar, {name}. Aprendo com os melhores."
L["Booty Bay's rule: no fighting on the docks, {name}. Mine: no refusing a gift."] = "Regra de Angra do Butim, {name}: sem briga no cais. A minha: sem recusar presente."
L["The one thing both factions agree on, {name}. They just don't know it yet."] = "A única coisa em que as duas facções concordam, {name}. Só não sabem ainda."
L["This goes with any tabard, {name}. I made sure by giving it no colours at all."] = "Combina com qualquer tabardo, {name}. Por garantia, vem sem cor nenhuma."
L["For you, {name}. Neither Orgrimmar nor Stormwind sent it. It works anyway."] = "Para você, {name}. Nem Orgrimmar nem Ventobravo mandaram. Funciona mesmo assim."
L["Here, {name}. I belong to no nation yet, so I practise belonging to everyone."] = "Tome, {name}. Ainda não pertenço a nenhuma nação, então treino pertencer a todas."
L["Side by side, {name}, whatever comes."] = "Lado a lado, {name}, venha o que vier."
L["No flag over this party, {name}, just us. That's plenty."] = "Nenhuma bandeira sobre este grupo, {name}, só nós. E basta."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "Um dia vamos escolher lados, {name}. Hoje escolhemos brigas, juntos."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "Seja qual for o lado do resto do mundo, {name}, eu sou do lado deste grupo."
L["Neutral in the war, {name}, but very partial to this group."] = "Imparcial na guerra, {name}, mas bem parcial com este grupo."
L["They call us a neutral party, {name}. Nobody said it had to be a quiet one."] = "Grupo neutro, {name}, não quer dizer grupo no mudo."
L["Whatever we fight today, {name}, it's nothing personal. Just very thorough."] = "Contra o que for hoje, {name}, nada pessoal. Só muito bem-feito."
L["One side in this party, {name}: ours. Smallest faction on Azeroth. The best."] = "Um lado só neste grupo, {name}: o nosso. A menor facção de Azeroth. A melhor."
L["No orders from any capital, {name}. We choose our road. Let's choose quickly."] = "Sem ordens de capital, {name}. O caminho é escolha nossa. Então, rápido."
L["No war to win today, {name}, just this one fight. Much more manageable."] = "Nenhuma guerra para vencer hoje, {name}, só este combate. Bem mais tranquilo."
L["One good turn deserves another, {name}."] = "Uma boa ação merece outra, {name}."
L["Have some {buff} in return, {name}."] = "Um pouco de {buff} em troca, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "Gentileza é via de mão dupla, {name}. Agradeço."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "Você começou, {name}, eu continuo, e a isso chamamos amizade."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "Eu te faria uma canção, {name}, mas {buff} desafina menos."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "Presente por presente, {name}. Nesse ritmo, até o jantar ninguém nos segura."
L["All square, {name}. Unless you'd like to make it best of three."] = "Empatamos, {name}. A não ser que você queira uma melhor de três."
L["You started it, {name}. I'm only finishing it."] = "Você começou, {name}. Eu só estou terminando."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "Que gentileza, {name}. O dia ficou visivelmente melhor. Aqui vai minha metade."
L["I was about to do that for you, {name}. Honestly. Here's proof."] = "Eu ia fazer isso por você, {name}. Juro. Aqui está a prova."
L["Thank you, {name}. I'll sleep better tonight, and I sleep in a ditch."] = "Agradeço, {name}. Vou dormir melhor hoje, e olha que durmo numa vala."
L["Two good things today, {name}: your kindness, and the chance to return it."] = "Duas coisas boas hoje, {name}: sua gentileza e a chance de retribuir."
L["You had me in your debt for all of three seconds, {name}. There."] = "Fiquei te devendo por uns três segundos, {name}. Pronto."
L["Gratitude is best served quickly, {name}. Here it is, still warm."] = "Gratidão se serve quente, {name}. Aqui está, saindo do forno."
L["Well, {name}, now I have to be a better person all day. Thanks for that."] = "Pois é, {name}, agora tenho que ser uma pessoa melhor o dia todo. Valeu, hein."
L["Returned with a bow, {name}. A figurative one. My back isn't what it was."] = "Retribuído com reverência, {name}. Simbólica. Minha coluna já não é a mesma."
L["Thank you, {name}. I'd hoped somebody would start. I'm hopeless at starting."] = "Agradeço, {name}. Torcia para alguém começar. Começar nunca foi meu forte."
L["Thank you, {name}. You've rescued a day I'd written off at breakfast."] = "Agradeço, {name}. Salvou um dia que dei por perdido no café da manhã."
L["You asked, {name}, and here it is."] = "Você pediu, {name}, e aqui está."
L["{buff}, coming right up, {name}."] = "{buff} saindo agorinha, {name}."
L["Gladly, {name}. One moment."] = "Com prazer, {name}. Um momento."
L["Asked and answered, {name}. Next question?"] = "Perguntou, respondi, {name}. Próxima pergunta?"
L["Say the word and it's yours, {name}. You said several. Here."] = "Bastava uma palavra, {name}. Você disse várias. Tome."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "Para você, {name}? Com prazer. Estava torcendo para alguém pedir."
L["Of course, {name}. Easiest yes I'll say all day."] = "Claro, {name}. O sim mais fácil do meu dia."
L["Right away, {name}. Finally, a question I know the answer to."] = "É pra já, {name}. Finalmente uma pergunta que eu sei responder."
L["Of course, {name}. Nobody asks me for anything these days. This is lovely."] = "Claro, {name}. Ninguém me pede nada hoje em dia. Que delícia."
L["Hold still, {name}. It works best on people who aren't fidgeting. So, nobody."] = "Não se mexa, {name}. Funciona melhor em quem não fica se mexendo. Ou seja, ninguém."
L["Here you are, {name}. I'd make you wait for effect, but that seems rude."] = "Aqui está, {name}. Faria suspense, mas seria falta de educação."
L["Yes, {name}. I'd have said it sooner if you'd asked sooner."] = "Sim, {name}. Teria dito antes se você tivesse pedido antes."
L["Say no more, {name}. Well, say thank you. Then no more."] = "Não diga mais nada, {name}. Quer dizer, diga valeu. Depois, nada."
L["There, {name}. Next time, don't ask; just stand near me looking hopeful."] = "Pronto, {name}. Da próxima, nem peça: pare do meu lado com olhar pidão."
L["Coming up, {name}. This is the one part of my day that goes to plan."] = "Saindo, {name}. A única coisa do meu dia que sai como planejado."
L["Asking nicely works, {name}. Tell everyone. The world could use the news."] = "Pedir com educação funciona, {name}. Espalhe. O mundo precisa dessa notícia."
L["At once, {name}. Stay put, or this lands on your shadow instead."] = "Agora mesmo, {name}. Não se mexa, senão acerto sua sombra."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "Boa viagem, {name}. {buff} pesa menos na mochila que uma espada."
L["A small blessing for the road, {name}."] = "Uma pequena bênção para a estrada, {name}."
L["Go well, {name}, and come back in one piece."] = "Vá em paz, {name}, e volte sem nenhum arranhão."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "Sem motivo, {name}. Só pareceu um dia de {buff}."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "Não liga pra mim, {name}. Só de passagem, com {buff} sobrando."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "Considere um presente, {name}. Eu embrulharia, mas brilha através do papel."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "Tome, {name}. Passe adiante quando encontrar alguém que precise."
L["Whatever brings you here, {name}, may it go better than planned."] = "Seja lá o que te trouxe aqui, {name}, que dê mais certo que o planejado."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "Só boa vizinhança, {name}. Uma vizinhança bem, bem temporária."
L["You looked about to do something brave, {name}. Here, for that."] = "Cara de quem vai fazer algo corajoso, {name}. Tome, pra isso."
L["No need to stop, {name}. It works while you walk."] = "Não precisa parar, {name}. Funciona até andando."
L["Nothing asked, nothing owed, {name}. Nothing to do but go and be splendid."] = "Nada pedido, nada devido, {name}. Nada a fazer além de ir lá e arrasar."
L["Call it a wager, {name}, that you'll do something worthwhile with it."] = "É uma aposta, {name}: aposto que você vai fazer bom uso disso."
L["A gift from a passing stranger, {name}. The best kind, the old stories say."] = "Presente de alguém de passagem, {name}. O melhor tipo, dizem as lendas."
L["It's rude to pass someone without a greeting, {name}. This is mine."] = "Passar sem cumprimentar é falta de educação, {name}. Eis o meu."
L["I'm not following you, {name}. We're just going the same way. Here."] = "Não estou te seguindo, {name}. Só vamos pro mesmo lado. Tome."
L["If today goes well, {name}, remember me. If it goes badly, I was never here."] = "Se hoje der certo, {name}, lembre de mim. Se der errado, eu nunca estive aqui."
L["Hold still a moment, {name}. There. Best-prepared person in sight."] = "Não se mexa, {name}. Pronto. A pessoa mais preparada à vista."
L["Everyone ready? You are now, {name}."] = "Todo mundo pronto? Agora sim, {name}."
L["A little something for the party, {name}."] = "Um agrado para o grupo, {name}."
L["Stay close, {name}. We go further together."] = "Fique por perto, {name}. Juntos vamos mais longe."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "Regras da casa, {name}: ninguém morre, ninguém emburra, todo mundo come depois."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "Pronto, {name}. Agora, se der errado, a culpa não é minha."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "Tudo pronto, {name}. Faria um discurso, mas ia levar o dia todo."
L["Look after that, {name}. It's the only one I brought for you."] = "Cuide bem disso, {name}. Só trouxe um para você."
L["Now we look the part, {name}. Let's go and be it."] = "Já temos a pose, {name}. Agora falta o heroísmo."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff} para todo mundo, {name}. O resto é sorte e cotovelada."
L["Right, {name}. If anyone has a plan, now's the time. No? Wonderful. Onward."] = "Certo, {name}. Se alguém tem um plano, a hora é agora. Ninguém? Maravilha. Avante."
L["One each, {name}. Don't swap; they're fitted."] = "Um para cada, {name}. Não troquem; é sob medida."
L["Whoever starts the fight, {name}, has to tell the story afterwards."] = "Quem puxar a briga, {name}, é quem conta a história depois."
L["Good friends, sharp steel, {buff}. What else is there, {name}?"] = "Bons amigos, aço afiado, {buff}. Precisa de mais o quê, {name}?"
L["Stay where I can see you, {name}. I can't help what I can't find."] = "Fique onde eu possa te ver, {name}. Não dá pra ajudar quem eu não acho."
L["If this ends up a legend, {name}, I want a line in it. Just the one."] = "Se isso virar lenda, {name}, quero uma fala nela. Uma só."
L["Brace yourselves, {name}. And each other, if it comes to that."] = "Segurem-se, {name}. Uns nos outros, se for preciso."
L["Chin up, {name}. Whatever's ahead has never met this lot before."] = "Cabeça erguida, {name}. O que vem aí nunca enfrentou esta turma."
L["Do try to stay in one piece, {name}. I'm only equipped for small repairs."] = "Tente não se partir em pedaços, {name}. Só faço pequenos reparos."
L["Well, {name}, we look ready. Let's go before we find out otherwise."] = "Bem, {name}, parecemos prontos. Vamos antes que se prove o contrário."
L["If we get lost, {name}, we're exploring. Nobody ever scolded an explorer."] = "Se a gente se perder, {name}, é exploração. Ninguém briga com explorador."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "Agradeço, {name}. Eu conjuraria um presente em troca, mas só sairia água."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "Fico em dívida, {name}. Depois registro tudo direitinho. Várias páginas."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "Agradeço, {name}. Dalaran nunca ensinou gratidão. Sou autodidata."
L["Kind of you, {name}. I'd say it went to my head, but that's my job."] = "Gentileza sua, {name}. Diria que me subiu à cabeça, mas esse é o meu ofício."
L["Thank you, {name}. I nearly Counterspelled that on reflex. So glad I didn't."] = "Agradeço, {name}. Quase dei Contrafeitiço por reflexo. Ainda bem que não."
L["Even a frost mage would thaw at that, {name}. Thank you."] = "Até um mago de gelo derreteria com essa, {name}. Agradeço."
L["Thank you, {name}. Noted in my spellbook, between Frost Nova and lunch."] = "Agradeço, {name}. Anotado no grimório, entre Nova Congelante e almoço."
L["Repaid at once, {name}, before I pass a bookshop. I've lost weeks that way."] = "Retribuo já, {name}, antes de passar numa livraria. Já sumi semanas assim."
L["Twenty years in the library, {name}, and no book mentioned people like you."] = "Vinte anos de biblioteca, {name}, e nenhum livro falava de gente como você."
L["Arcane theory says nothing comes free, {name}. Theory was wrong. Thank you."] = "A teoria arcana diz que nada é de graça, {name}. A teoria errou. Agradeço."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "Claro, {name}. E sim, imagino que você também vá querer água."
L["As requested, {name}. Side effects may include footnotes."] = "Como pedido, {name}. Efeitos colaterais podem incluir notas de rodapé."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "Agora mesmo, {name}. Com cuidado; hoje já dei Lampejo em duas paredes."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "Com prazer, {name}. Conhecimento se compartilha. O Kirin Tor concorda, a contragosto."
L["Certainly, {name}. I'll cast it slowly. The hand movements are the best part."] = "Certamente, {name}. Vou lançar devagar. O gestual é a melhor parte."
L["Of course, {name}. Think of it as homework, and I've done it for you."] = "Claro, {name}. Pense num dever de casa que eu já fiz por você."
L["Of course, {name}. Antonidas taught me this. He also taught me to duck."] = "Claro, {name}. Antonidas me ensinou isso. E também a me abaixar."
L["At once, {name}. Arcane, not fire. I did check. I always check. Nearly always."] = "Agora mesmo, {name}. Arcano, não fogo. Conferi. Sempre confiro. Quase sempre."
L["Certainly, {name}. It's this or a lecture on ley lines, and you've been kind."] = "Certamente, {name}. Era isto ou uma aula sobre linhas de ley, e você foi gentil."
L["You asked a mage, {name}. The spell is instant; the explanation is not."] = "Pediu magia, {name}? O feitiço é instantâneo; a explicação, não."
L["I've cast this a thousand times, {name}. Nine hundred and ninety went well."] = "Já lancei isto mil vezes, {name}. Novecentas e noventa deram certo."
L["Certainly, {name}. Stand still. Fidgeters have been known to end up woolly."] = "Certamente, {name}. Não se mexa. Quem se remexe às vezes acaba balindo."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "Tome, {name}. Sobrou uma ideia e eu não tinha onde guardar."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "Tome, {name}. Daria pão também, mas pão conjurado não tem gosto de nada."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{buff} para você, {name}. De graça, ao contrário dos portais."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "Tome, {name}. Quem eu miro costuma virar ovelha. Hoje é seu dia de sorte."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "Nada pegando fogo, nada congelado, {name}. Estou diversificando."
L["For you, {name}. I was practising, and you happened to be the nearest head."] = "Para você, {name}. Eu estava treinando, e sua cabeça era a mais próxima."
L["Here, {name}. I'd have portalled it over, but you were standing right there."] = "Tome, {name}. Eu mandaria por portal, mas você estava bem aqui."
L["Kings once hired Dalaran for this, {name}. You get it for nothing."] = "Reis já pagaram Dalaran por isso, {name}. Você leva de graça."
L["Take this, {name}. It wears off, unlike my last experiment."] = "Tome, {name}. Isto passa; meu último experimento, não."
L["For you, {name}: everything I learned in Dalaran, minus the essays."] = "Para você, {name}: tudo o que aprendi em Dalaran, menos as redações."
L["Here, {name}. Arcane magic is best shared, before it gets ideas of its own."] = "Tome, {name}. Magia arcana é melhor dividida, antes que crie ideias próprias."
L["Evocation takes an age, {name}, so I spend my mana where it counts. Here."] = "Evocação demora uma eternidade, {name}, então gasto mana onde vale. Tome."
L["Here, {name}. A mage who walks past without helping is just a very tall hat."] = "Tome, {name}. Mago que passa sem ajudar é só um chapéu pontudo com pernas."
L["Now that you're clever, {name}, stand between me and the angry things."] = "Mente afiada, {name}? Então fique entre mim e as coisas furiosas."
L["For the record, {name}, I only blink away when it's tactically sound."] = "Para constar, {name}, só dou Lampejo pra longe quando é taticamente sensato."
L["Water's on me after, {name}. Please don't ask for it mid-fight."] = "Água por minha conta depois, {name}. Só não peça no meio do combate."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "Mentes afiadas, {name}. Eu cuido do fogo, do gelo e do pânico."
L["Right, {name}: if I say 'Frost Nova', run. If I say 'run', also run."] = "Certo, {name}: se eu disser 'Nova Congelante', corra. Se disser 'corra', também."
L["Pyroblast takes a while, {name}. Whatever interrupts it, I take personally."] = "Ignimpacto demora, {name}. Se algo interromper, levo para o lado pessoal."
L["If I ice-block, {name}, I'm not frozen with fear. I'm frozen on purpose."] = "Se eu virar Bloco de Gelo, {name}, não congelei de medo. Foi de propósito."
L["Portals home are on me after, {name}. Getting there alive is on all of us."] = "Portal pra casa por minha conta depois, {name}. Sair com vida é por conta de todos."
L["Anything you'd rather not fight, {name}, point at it. It'll be wool by teatime."] = "O que você não quiser enfrentar, {name}, é só apontar. Vira lã até o café da tarde."
L["I'll drop a Blizzard on them, {name}. You're welcome to watch, from outside it."] = "Vou soltar uma Nevasca neles, {name}. Pode assistir à vontade, de fora dela."
L["If I start counting under my breath, {name}, that's mana, not nerves."] = "Se eu começar a contar baixinho, {name}, é mana, não nervosismo."
L["If I go quiet, {name}, it's Evocation, not sulking. Usually."] = "Se eu ficar em silêncio, {name}, é Evocação, não birra. Geralmente."
L["If this goes badly, {name}, I've a teleport home. I'd never use it. Probably."] = "Se der errado, {name}, tenho um teleporte pra casa. Jamais usaria. Provavelmente."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "Quanta consideração, {name}. A Luz faz as contas; eu quito as minhas adiantado."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "Agradeço, {name}. Vou falar bem de você para a Luz. Ela me deve várias."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "Agradeço, {name}. Um pequeno milagre, e eu nem precisei rezar."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "Agradeço, {name}. Minha fé nas pessoas foi restaurada. Estava só descansando."
L["Thank you, {name}. You're in tonight's prayers. Near the top."] = "Agradeço, {name}. Você está nas orações de hoje à noite. Lá no topo."
L["Healers are rarely on this end of it, {name}. I'd forgotten how nice it is."] = "Quem cura raramente fica deste lado, {name}. Tinha esquecido como é bom."
L["Thank you, {name}. You've saved me a prayer, and I'm always one short."] = "Agradeço, {name}. Você me poupou uma prece, e sempre me falta uma."
L["Thank you, {name}. I'd give a sermon on generosity, but you've just given it."] = "Agradeço, {name}. Ia pregar sobre generosidade, mas você deu o exemplo antes."
L["Thank you, {name}. I'll light a candle for you. Two. I'm feeling reckless."] = "Agradeço, {name}. Vou acender uma vela por você. Duas. Hoje eu chuto o balde."
L["Even my shadowy side is smiling, {name}. It has no face, so take my word."] = "Até meu lado sombrio está sorrindo, {name}. Ele não tem rosto, então confie em mim."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "Claro, {name}. A Luz não tem expediente, e eu, infelizmente, também não."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "Agora mesmo, {name}. A maioria das preces demora mais; você achou um atalho."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "Certamente, {name}. A Luz brilha sobre quem pede. Eu só miro."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "Com prazer, {name}. A fé move montanhas; eu começo por algo menor."
L["Of course, {name}. Confessions are extra, and I'd rather not hear them."] = "Claro, {name}. Confissão é à parte, e prefiro não ouvir."
L["Of course, {name}. Consider this sermon abridged. Very abridged. There, done."] = "Claro, {name}. Considere o sermão resumido. Bem resumido. Pronto, acabou."
L["Certainly, {name}. A warm glow means the Light. A cold one, tell me at once."] = "Certamente, {name}. Brilho quente é a Luz. Se for frio, me avise na hora."
L["Of course, {name}. I'll pray it lasts. I'm told I have an in."] = "Claro, {name}. Vou rezar pra durar. Tenho costas quentes lá em cima."
L["Certainly, {name}. I heal, I smite, I do funerals. This is the cheerful bit."] = "Certamente, {name}. Eu curo, castigo e faço velório. Esta é a parte alegre."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "Saúde, {name}! Não, você não espirrou; é só zelo profissional."
L["Here, {name}. Think of it as a prayer that arrived early."] = "Tome, {name}. Considere uma prece que chegou adiantada."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "A Luz pediu que eu te entregasse isto, {name}. Estou parafraseando."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "Tome, {name}. Poupa nós dois de uma ressurreição constrangedora depois."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "De graça, {name}. A fé não custa nada. Já as vestes, infelizmente, custaram."
L["Here, {name}. Think of me as a small, walking temple. No steps to climb."] = "Tome, {name}. Pense em mim como um templinho ambulante. Sem escadaria."
L["A blessing for a stranger, {name}. The Light insists there's no such thing."] = "Uma bênção a quem nem conheço, {name}. Para a Luz, não existe desconhecido."
L["Take this, {name}. No collection plate follows. Look: empty hands."] = "Tome, {name}. Não vou passar a sacolinha. Olha: mãos vazias."
L["Here, {name}. I'd preach, but you look like somebody with somewhere to be."] = "Tome, {name}. Eu pregaria, mas você tem cara de quem tem compromisso."
L["I do weddings, funerals and resurrections, {name}. Mostly the last. Here."] = "Faço casamentos, velórios e ressurreições, {name}. Mais a última. Tome."
L["Here, {name}. I'd float over properly, but levitating in public draws a crowd."] = "Tome, {name}. Eu viria flutuando, mas levitar em público junta gente."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "Sua vez, {name}. Agora imploro a todos: deixem meu trabalho chato."
L["Everyone stay near me, {name}. The Light has a limited range."] = "Todo mundo perto de mim, {name}. A Luz tem alcance limitado."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "Pronto, {name}. Se alguém cair, primeiro vem a decepção, depois o conserto."
L["Done, {name}. I'll be at the back, praying loudly."] = "Feito, {name}. Vou estar lá atrás, rezando bem alto."
L["If I scream, {name}, it's a spell, and everything runs. Please don't join in."] = "Se eu gritar, {name}, é feitiço, e tudo sai correndo. Por favor, não corram junto."
L["If I Fade, {name}, I haven't gone. I've just become deeply uninteresting."] = "Se eu Desvanecer, {name}, não sumi. Só fiquei muito desinteressante."
L["One shield each, {name}. After that, souls need a lie-down. Pace yourselves."] = "Um escudo por cabeça, {name}. Depois, a alma pede um cochilo. Vão com calma."
L["Let's all come back from this the usual way, {name}: walking."] = "Vamos todos voltar do jeito normal, {name}: andando."
L["I'll keep you alive, {name}. You keep me from having to say 'I told you so'."] = "Eu te mantenho com vida, {name}. Você me poupa de dizer 'eu avisei'."
L["I prayed over this group, {name}. The Light said 'good luck'. I'll take it."] = "Rezei por este grupo, {name}. A Luz respondeu 'boa sorte'. Já é alguma coisa."
L["Thank you, {name}. I'd purr, but I'm not in the right shape for it."] = "Agradeço, {name}. Eu ronronaria, mas não estou na forma certa."
L["Thanks, {name}. My bear form sends a grateful grunt."] = "Valeu, {name}. Minha forma de urso manda um grunhido de gratidão."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "Fico em dívida, {name}. Minha forma de felino quer te trazer um coelho. Eu disse não."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "Agradeço, {name}. Vou plantar uma árvore em sua honra. Volte em um século."
L["Thank you, {name}. I'd send an owl with a note, but I'd have to be the owl."] = "Agradeço, {name}. Mandaria um bilhete por coruja, mas a coruja teria que ser eu."
L["Kindly done, {name}. I felt that in my roots, and I haven't any at the moment."] = "Que gentileza, {name}. Senti até na raiz, e no momento nem tenho uma."
L["Nature returns everything eventually, {name}. I'm quicker. Thank you."] = "A natureza devolve tudo um dia, {name}. Eu devolvo na hora. Agradeço."
L["Barkskin keeps most things out, {name}. Kindness got straight through. Thanks."] = "Pele de Árvore barra quase tudo, {name}. A gentileza passou direto. Valeu."
L["Thank you, {name}. As a bear this would be a hug. Be glad I'm in this shape."] = "Agradeço, {name}. Em forma de urso, seria um abraço de urso. Sorte sua."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "Certamente, {name}. Um momento para eu lembrar qual forma tem mãos."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "Claro, {name}. Não se mexa, como um carvalho. Carvalhos são ótimos nisso."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "Com prazer, {name}. A mata divide tudo. Bom, os ursos não."
L["Right away, {name}. Pardon the feathers; I've just come from being an owl."] = "É pra já, {name}. Perdão pelas penas; acabei de ser coruja."
L["Of course, {name}. Nature doesn't take requests, but I do."] = "Claro, {name}. A natureza não aceita pedidos, mas eu aceito."
L["Gladly, {name}. Ask a tree and you'll wait a year. Ask a druid and it's now."] = "Com prazer, {name}. Peça a uma árvore e espere um ano. Peça a um druida e é agora."
L["Of course, {name}. The balance tips a little your way. Don't tell the balance."] = "Claro, {name}. O equilíbrio pende um pouco pro seu lado. Não conte pro equilíbrio."
L["I'd have run over, {name}, but as a cheetah, and you'd have screamed. Here."] = "Eu viria correndo, {name}, mas de chita, e você ia gritar. Tome."
L["Of course, {name}. The wild is kind to all who ask. Midges excepted."] = "Claro, {name}. A mata é gentil com quem pede. Já os borrachudos..."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "Direto do Sonho Esmeralda, {name}. Desculpe se eu bocejar."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "Tome, {name}. A natureza provê, e hoje eu faço as entregas dela."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "A natureza agora está do seu lado, {name}. Ótimo, já que quase toda ela tem dentes."
L["I brought you flowers as well, {name}, but I was a stag at the time. Sorry."] = "Eu tinha trazido flores, {name}, mas estava de cervo na hora. Foi mal."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "Tome, {name}. Cenarius ia querer que fosse seu. Tenho quase certeza."
L["Nature wants you to have this, {name}. I'm its hands. Today I have hands."] = "A natureza quer que isto seja seu, {name}. Sou as mãos dela. Hoje tenho mãos."
L["Take this, {name}. The wild has been watching you, and it's decided you'll do."] = "Tome, {name}. A natureza andou te observando e decidiu que você serve."
L["If a cat follows you today, {name}, it's only me checking this took."] = "Se um gato te seguir hoje, {name}, sou só eu vendo se pegou."
L["For you, {name}. The Moonglade sends its regards. It sends very few."] = "Para você, {name}. A Clareira da Lua manda lembranças. Ela quase nunca manda."
L["Nature is cruel, lovely and damp, {name}. This helps with two of those."] = "A natureza é cruel, linda e úmida, {name}. Isto ajuda com duas dessas coisas."
L["I tie strangers up in roots most days, {name}. This is the nicer part."] = "Vivo prendendo desconhecidos em raízes, {name}. Esta é a parte simpática."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "Tudo certo, {name}? Aconteça o que acontecer, ninguém assusta o urso."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "Pronto, {name}. Serei o gato, o urso ou, se tiver que nadar, a foca."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "Só tenho um Renascimento, {name}. Por favor, não me façam escolher."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "Cerrem fileiras, {name}. A floresta está de olho, e é torcedora de raiz."
L["If I turn into a tree, {name}, things are going badly and I'm fixing them."] = "Se eu virar árvore, {name}, a coisa está feia e estou consertando."
L["I've one Innervate, {name}. Whoever looks most desperate gets it. No acting."] = "Só tenho um Estimular, {name}. Vai pra quem estiver mais no desespero. Sem teatrinho."
L["If I start glowing and hooting, {name}, that's moonkin. It's a serious form."] = "Se eu começar a brilhar e piar, {name}, é Forma de Luniscante. Forma séria, viu?"
L["If it gets crowded, {name}, I'll call a Hurricane. Hold on to your hats."] = "Se lotar, {name}, eu chamo um Furacão. Segurem os chapéus."
L["We move like a herd, {name}. A mixed herd. One of us is sometimes a bear."] = "A gente anda em bando, {name}. Um bando variado. Um de nós às vezes é urso."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "Gentileza, {name}? Minha virtude favorita. Logo acima de polir armadura."
L["For that, {name}, my best blessing. Not the second best. The best."] = "Por isso, {name}, minha melhor bênção. Não a segunda melhor. A melhor."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "Virtude recompensada na hora, {name}! Adoro quando isso acontece."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "Agradeço, {name}. Meu juramento manda retribuir. Eu faria mesmo sem ele."
L["I'll judge you favourably, {name}. I judge most things harshly. Thank you."] = "Vou te julgar com bons olhos, {name}. Quase tudo eu julgo com rigor. Agradeço."
L["Thank you, {name}. My aura just brightened. It does that when I'm touched."] = "Agradeço, {name}. Minha aura acabou de brilhar. Faz isso quando me emociono."
L["A kindness, {name}! I'll have it engraved on my shield, beside the dents."] = "Que gentileza, {name}! Vou gravar no meu escudo, ao lado dos amassados."
L["Much obliged, {name}. My warhorse sends thanks as well. He's more reserved."] = "Fico em dívida, {name}. Meu corcel também agradece. Ele é mais reservado."
L["I swore to protect the good, {name}. You've just gone to the top of the list."] = "Jurei proteger os bons, {name}. Você acaba de ir pro topo da lista."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "Pela Luz, {name}, claro! Eu só esperava alguém pedir."
L["You have my blessing, {name}. Literally, this time."] = "Você tem minha bênção, {name}. Literalmente, desta vez."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "Certamente, {name}. Ajoelhe-se se quiser. Não vou insistir. Mas vou adorar."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "Com prazer, {name}. Bênção nunca me falta. Mana, às vezes."
L["Certainly, {name}. Hold still. My aim is righteous; my gauntlets are clumsy."] = "Certamente, {name}. Não se mexa. Minha mira é justa; minhas manoplas, desastradas."
L["Gladly, {name}. Helping is the oath. Shining while I do it is a bonus."] = "Com prazer, {name}. Ajudar é o juramento. Brilhar enquanto isso é brinde."
L["Of course, {name}. Stand fast, chin up, and look deserving. There. You do."] = "Claro, {name}. Postura firme, queixo erguido, cara de quem merece. Pronto. Merece."
L["Of course, {name}. You'd be amazed how rarely anyone asks the tin can for help."] = "Claro, {name}. Nem imagina como é raro pedirem ajuda à lata de sardinha."
L["Of course, {name}. A moment while I pick the blessing. I do have favourites."] = "Claro, {name}. Um momento para eu escolher a bênção. Tenho minhas favoritas."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "A Luz não pede nada em troca, {name}. Já eu aceito agradecimentos."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "Vá com a Luz, {name}. Estarei logo atrás, tilintando."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "A bênção é de graça, {name}. O sermão eu te poupo. Desta vez."
L["There, {name}. It won't last forever, so be heroic while it does."] = "Pronto, {name}. Não dura para sempre, então faça heroísmos enquanto dura."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "Peito estufado, {name}. A Luz caminha com você, e tem uma postura impecável."
L["Take this, {name}. I'd give you my hammer too, but it's very attached to me."] = "Tome, {name}. Daria meu martelo também, mas ele é muito apegado a mim."
L["Blessings are for handing out, {name}. Hoarding them is frowned upon. By me."] = "Bênção é pra distribuir, {name}. Acumular é malvisto. Por mim."
L["Justice for the wicked, blessings for the rest, {name}. You're the rest."] = "Justiça aos perversos, bênção aos demais, {name}. Adivinha qual é a sua."
L["Take this, {name}. My libram says to share. It says a lot; this bit I like."] = "Tome, {name}. Meu livro sagrado manda dividir. Manda muita coisa; dessa eu gosto."
L["Chivalry isn't dead, {name}. It's in heavy armour, and it brought you this."] = "O cavalheirismo não morreu, {name}. Está de armadura pesada e te trouxe isto."
L["Wear it with pride, {name}. Pride's a sin, but only in large amounts."] = "Use com orgulho, {name}. Orgulho é pecado, mas só em grandes doses."
L["You're blessed, {name}. If I bubble later, it's strictly tactical."] = "Bênção dada, {name}. Se eu soltar a bolha depois, é pura tática."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "Firmes, {name}. Temos a Luz, e eu tenho um martelo bem grande."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "Uma bênção para cada, {name}. A Luz é generosa, mas exige fila."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "Esplêndido, {name}. Agora, ninguém olhe direto para mim. Estou bem radiante hoje."
L["Stay inside my aura, {name}. It's warmer than it looks."] = "Fique na minha aura, {name}. É mais quentinha do que parece."
L["If I stun something, {name}, hit it while it's thinking things over."] = "Se eu atordoar algo, {name}, bata enquanto ele repensa a vida."
L["The glowing ground is mine, {name}. Stand in it freely; it only bites them."] = "O chão brilhante é meu, {name}. Pode pisar à vontade; só morde eles."
L["I'll judge them, {name}, and you sentence them. A very efficient court."] = "Eu julgo, {name}, você dá a sentença. Um tribunal eficiente, coisa rara."
L["If I shout 'for the Light', {name}, it means charge. Or pray. Usually both."] = "Se eu gritar 'pela Luz', {name}, é pra atacar. Ou rezar. Geralmente os dois."
L["Armour polished, hammer blessed, {name}, and my horse is sulking. We're ready."] = "Armadura polida, martelo abençoado, {name}, e meu cavalo emburrado. Estamos prontos."
L["Righteous Fury's up, {name}. Everything wants to hit me now. That's the idea."] = "Fúria Justa ativada, {name}. Agora tudo quer me bater. A ideia é essa."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "Que gentileza, {name}. Meu diabrete também agradece. Ele está mentindo, eu não."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "Agradeço, {name}. Faz tempo que ninguém me dá algo sem maldição."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "Agradeço, {name}. Retribuo com algo que não achei numa cripta."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "Muita bondade, {name}. Pedi ao emissário do caos para parar de te encarar."
L["Thank you, {name}. I'll tell my demons about you. They'll be baffled."] = "Agradeço, {name}. Vou falar de você aos meus demônios. Não vão entender nada."
L["No blood, no bargain, no binding, {name}? What a strange way to trade. Thanks."] = "Sem sangue, sem selo, sem sacrifício, {name}? Que negócio estranho. Valeu."
L["Thank you, {name}. I'll be nicer to my felhunter tonight, in your honour."] = "Agradeço, {name}. Vou ser mais legal com meu caçador vil hoje, em sua honra."
L["How thoughtful, {name}. Everything I'm given, I return. Except souls. Here."] = "Quanta consideração, {name}. Tudo que me dão, eu devolvo. Menos almas. Tome."
L["Of course, {name}. No soul required. This time."] = "Claro, {name}. Não precisa de alma. Desta vez."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "Pedir ajuda a um bruxo, {name}? Que ousadia. Já gostei de você."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "Claro, {name}. O diabrete quis ajudar, e eu disse não, pelo bem de todos."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "Certamente, {name}. De todos os meus feitiços, é o único que dá pra fazer em festa."
L["Gladly, {name}. A good deed on my record; the Shadow Council would be appalled."] = "Com prazer, {name}. Uma boa ação na ficha; o Conselho das Sombras ficaria horrorizado."
L["Of course, {name}. Please don't read the book I'm holding. For your own sake."] = "Claro, {name}. Por favor, não leia o livro na minha mão. Para o seu próprio bem."
L["Certainly, {name}. Feel watched? That's only the Eye of Kilrogg. Hold still."] = "Certamente, {name}. Sente um olhar em você? É só o Olho de Kilrogg. Não se mexa."
L["Of course, {name}. I only curse people who don't ask nicely. You're quite safe."] = "Claro, {name}. Só amaldiçoo quem não pede com educação. Você não corre risco."
L["Yes, {name}, it's the one without screaming. Hold still."] = "Sim, {name}, é o que não tem gritaria. Não se mexa."
L["Of course, {name}. Going somewhere wet? I won't ask. Warlocks never ask."] = "Claro, {name}. Vai pra algum lugar molhado? Não pergunto. Bruxo nunca pergunta."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "Tome, {name}. Não pergunte de onde veio. Sério, não pergunte."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "Se um dia cair num lago, {name}, vai se lembrar de mim com carinho."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "Respire em paz, {name}. Odiaria perder você para algo tão sem graça quanto água."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "Tome, {name}. Você vai querer uma Pedra da Alma também, mas aí é outra conversa."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "Tome, {name}. É o único feitiço meu que os sacerdotes aprovam."
L["Take this, {name}. My mother still thinks I'm a mage. Let's keep it that way."] = "Tome, {name}. Minha mãe ainda acha que estudo em Dalaran. Deixe ela pensar assim."
L["Here, {name}. It isn't green, it doesn't whisper, and it won't follow you home."] = "Tome, {name}. Não é verde, não sussurra e não vai te seguir até em casa."
L["Here, {name}. Dark magic, used for good. Do tell my old tutor; he'll hate it."] = "Tome, {name}. Magia sombria usada para o bem. Conte ao meu antigo mestre; ele vai odiar."
L["Random acts of kindness, {name}. I'm trying them. The imp has complained."] = "Gentileza gratuita, {name}. Estou experimentando. O diabrete reclamou."
L["Here, {name}. I'm not all curses and fear. Mostly, but not all."] = "Tome, {name}. Não sou só maldição e medo. Quase só, mas não só."
L["My grimoire has a chapter on kindness, {name}. It's short, but I've read it."] = "Meu grimório tem um capítulo sobre gentileza, {name}. É curto, mas eu li."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "Todo mundo pronto, {name}? Almas intactas? Ótimo. Vamos manter assim."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "Fique por perto, {name}. O emissário do caos leva os golpes; eu levo o crédito."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "Nade à vontade, {name}. Se alguém se perder, eu invoco de volta."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "Pode fazer carinho no caçador vil, {name}. Só tire os feitiços antes."
L["If I fear something, {name}, don't chase it. It comes back. Angrier."] = "Se eu der Medo em algo, {name}, não corra atrás. Ele volta. Mais bravo."
L["If my health drops for no reason, {name}, it's Life Tap. Sorry, healer."] = "Se minha vida cair do nada, {name}, é mana paga com sangue. Foi mal, curador."
L["Healthstones after, {name}. For a crisis, mind, not as a snack."] = "Pedras de Vida no fim, {name}. Para emergências, não de lanchinho."
L["Keep clear when I cast Hellfire, {name}. I burn too. That's the tragic part."] = "Distância no Fogo do Inferno, {name}. Eu queimo junto. Essa é a tragédia."
L["My imp is on fire, {name}, and he's on our side. Please stop dousing him."] = "Meu diabrete está pegando fogo, {name}, e ele é do nosso lado. Parem de apagá-lo."
L["If something green falls from the sky, {name}, that's mine. Cheer."] = "Se cair algo verde do céu, {name}, é meu. Comemorem."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "Valeu, {name}! Desculpa, foi alto? Só tenho um volume."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "Valeu mesmo, {name}. Não sei feitiço de volta, mas meu grito é muito sincero."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "Valeu, {name}. Agora estou com o dobro de raiva. Do jeito bom."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "Valeu, {name}. Você ganhou um lugar logo atrás de mim. O mais seguro que existe."
L["Thank you, {name}. Kindness makes me soft. Luckily I've plenty of armour."] = "Valeu, {name}. Gentileza me amolece. Sorte que tenho armadura de sobra."
L["Thank you, {name}. My armourer thanks you too. I paid for his house."] = "Valeu, {name}. Meu armeiro também agradece. Paguei a casa dele."
L["Thanks, {name}. I'd bandage something for you, but you look annoyingly fine."] = "Valeu, {name}. Faria um curativo em você, mas não tem um arranhão. Que irritante."
L["Thank you, {name}. I switched to my grateful stance for that. It's rarely used."] = "Valeu, {name}. Troquei pra minha Postura de Gratidão. Quase nunca uso."
L["You've given me magic, {name}. No idea where to keep it. I'll wear it. Thanks."] = "Você me deu magia, {name}. Não sei onde guardar. Vou vestir. Valeu."
L["Owing folk makes me restless, {name}, and restless makes me charge things."] = "Dever favor me dá agonia, {name}, e agonia me faz dar Investida nas coisas."
L["You want a shout, {name}? I was going to shout anyway."] = "Quer um brado, {name}? Eu ia berrar de qualquer jeito."
L["Of course, {name}. Cover your ears; this is the only way I know how."] = "Claro, {name}. Tape os ouvidos; é o único jeito que eu sei fazer."
L["Right away, {name}. Stay in earshot. For me that's a generous distance."] = "É pra já, {name}. Fique ao alcance da minha voz. No meu caso, é bem longe."
L["Happily, {name}! Words aren't my strength. Volume is."] = "Com prazer, {name}! Palavras não são meu forte. Volume é."
L["Right, {name}. Deep breath. Not you. Me."] = "Certo, {name}. Respira fundo. Você não. Eu."
L["Happy to, {name}. First request today that didn't involve lifting something."] = "Com prazer, {name}. Primeiro pedido do dia que não envolve carregar peso."
L["Coming up, {name}. It's all in the diaphragm. And the anger. Mostly the anger."] = "Saindo, {name}. É tudo no diafragma. E na raiva. Principalmente na raiva."
L["Of course, {name}. Most folk only ask me to stop. This is a nice change."] = "Claro, {name}. Geralmente só me pedem pra parar. Que mudança boa."
L["Of course, {name}. Took me years to learn. Years of yelling at trees, mostly."] = "Claro, {name}. Levei anos pra aprender. Anos gritando com árvores, principalmente."
L["Consider yourself shouted at, {name}. Affectionately."] = "Isso foi um berro para você, {name}. Com carinho."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "Sem incenso, sem reza, {name}. Só eu, gritando palavras de incentivo."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "Levanta essa cabeça, {name}! Se algo te incomodar, eu dou uma Investida."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "Pronto, {name}! Quem não sentiu mais coragem agora não estava ouvindo."
L["Here, {name}, some courage. Warriors make it by yelling. Don't ask how."] = "Tome, {name}, coragem. Guerreiro fabrica no grito. Não pergunte como."
L["Here, {name}. Something sharper than a whetstone: morale."] = "Tome, {name}. Algo que afia mais que pedra de amolar: moral."
L["Take this, {name}. Warriors don't carry spells, so we carry each other."] = "Tome, {name}. Guerreiro não tem feitiço; a gente carrega uns aos outros."
L["Here, {name}. You look about to walk into something big. Walk in harder."] = "Tome, {name}. Cara de quem vai entrar em algo grande. Entre chutando a porta."
L["Here, {name}. No magic in it. Just a warrior believing in you, very firmly."] = "Tome, {name}. Nada de magia. Só fé de guerreiro em você, fé bem firme."
L["Take this, {name}. Trainers charge for it. I charge at things. Different job."] = "Tome, {name}. Instrutor cobra por isso. Eu só cobro dos monstros. Outro serviço."
L["Here, {name}. Tell whatever you fight that a warrior vouched for you."] = "Tome, {name}. Diga a quem você enfrentar que tem um guerreiro de fiador."
L["That one was for you, {name}. The next one's for whatever's in your way."] = "Esse foi pra você, {name}. O próximo é pra quem estiver no seu caminho."
L["Listen up, {name}! That's it. That was the whole speech."] = "Atenção, {name}! Pronto. Esse foi o discurso inteiro."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "Cadê o perigo, {name}? Deixa, eu acho. De cara."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "Certo, {name}! Eu vou na frente, eu grito mais alto, e ninguém encosta no curador."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "Todos com mais raiva? Ótimo. Avante, {name}, e cuidado com meu machado."
L["I need to be hit before I'm any use, {name}. Nobody panic when it happens."] = "Preciso apanhar pra servir de algo, {name}. Quando acontecer, sem pânico."
L["Bandages are in my pack, {name}. I tied the knots, so they're very secure."] = "As ataduras estão na mochila, {name}. Eu dei os nós, então estão bem seguras."
L["Right, {name}: I take the hits, you take the credit, and we split the repairs."] = "Certo, {name}: eu apanho, você leva a fama, e a gente racha o conserto."
L["If I go red and quiet, {name}, that's Berserker Rage. Red and loud, all's well."] = "Cara vermelha e calada, {name}: Raiva Incontrolada. Vermelha e berrando: tudo normal."
L["My shield's seen worse than this, {name}. So has my face. Onward."] = "Meu escudo já viu coisa pior, {name}. Minha cara também. Avante."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "Mente afiada para você, {name}. A minha custou uma sobrancelha em Dalaran."
L["A clearer head for you, {name}. What you fill it with is your own affair."] = "Cabeça arejada pra você, {name}. O recheio fica por sua conta."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "Pensamentos zumbindo, {name}? Normal. Se eles responderem, venha me procurar."
L["A little arcane for your thoughts, {name}. Keep the change."] = "Um pouco de arcano pelos seus pensamentos, {name}. Fique com o troco."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "Genialidade engarrafada, {name}. O Kirin Tor cobraria até a garrafa."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "Raciocínio afiado, {name}. Gaste em feitiços, fechaduras ou charadas; não julgo."
L["On loan from the Violet Citadel, {name}. Late returns are fined in sheep."] = "Empréstimo da Cidadela Violeta, {name}. Atrasou a devolução, vira ovelha."
L["Clever enough to spot the trap now, {name}. Avoiding it is a separate spell."] = "Agora você enxerga a armadilha, {name}. Desviar dela é outro feitiço."
L["There, {name}. Wiser already: look, you're standing further from me."] = "Pronto, {name}. A sabedoria já age: veja, você se afastou de mim."
L["The one spell of mine that's never set anything alight, {name}. Enjoy."] = "O único feitiço meu que nunca pôs fogo em nada, {name}. Aproveite."
L["A gnome's instructions make sense now, {name}. Still don't follow them."] = "Agora até manual de gnomo faz sentido, {name}. Mesmo assim, não siga."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "Fortitude, {name}: o jeito educado de um sacerdote dizer 'vai na frente'."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "Cada ponto de vigor é uma prece desesperada a menos para mim, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "Já com mais resistência, {name}. Por favor, não encare como desafio."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "Há outras Palavras de Poder, {name}. 'Escudo' e, em emergências, 'Corre'."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "Mais robustez agora, {name}. Quedas, ursos e más decisões doem um pouco menos."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. Tanta palavra, quando 'aguenta firme' bastava."
L["A little more of you to go round, {name}. Spend it slowly."] = "Mais de você pra dar e vender, {name}. Gaste com calma."
L["Sturdier, {name}. Not invincible. I expect I'll be saying that again later."] = "Mais resistente, {name}, não invencível. Aposto que vou repetir isso daqui a pouco."
L["Stubbornness, really, {name}. Dwarves are born with it; the rest of us pray."] = "É teimosia, no fundo, {name}. Anão nasce com ela; o resto de nós reza."
L["The only armour that never needs repairing, {name}. The smiths hate it."] = "A única armadura que nunca vai pro reparo, {name}. Ferreiros odeiam!"
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "Considere seu espírito elevado, {name}. Divinamente, por sinal."
L["Like a good night's sleep, {name}, without all the lying down."] = "Como uma boa noite de sono, {name}, sem precisar deitar."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "Uma segunda porção de espírito, {name}. A Luz sempre manda repetir o prato."
L["Keep your spirit where it is, {name}. The Spirit Healers are busy enough."] = "Mantenha o espírito no corpo, {name}. O cemitério anda lotado."
L["Cheer up, {name}. That's not advice this time; it's a spell."] = "Ânimo, {name}. Desta vez não é conselho; é feitiço."
L["Recover faster, {name}: from fights, from long casts and from my jokes."] = "Recupere-se rápido, {name}: de combates, feitiços longos e das minhas piadas."
L["A deep breath's worth of calm, {name}, without having to take one."] = "A calma de um respiro fundo, {name}, sem precisar respirar."
L["The Light's own second wind, {name}. Don't waste it on arguments."] = "O segundo fôlego da própria Luz, {name}. Não gaste discutindo."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "À prova de sombra, {name}. Conheço os truques dela; peguei uns emprestados."
L["Should the Void call, {name}, you can now pretend you're out."] = "Se o Caos chamar, {name}, agora dá pra fingir que saiu."
L["For when the dark gets personal, {name}. It usually does."] = "Para quando o escuro levar pro pessoal, {name}. E costuma levar."
L["The shadows will have to knock first now, {name}."] = "Agora as sombras vão ter que bater antes de entrar, {name}."
L["The dark still bites, {name}, but now it has to chew."] = "A escuridão ainda morde, {name}, mas agora tem que mastigar."
L["A lining against the dark, {name}. Like a cloak, only on the inside."] = "Um forro contra o escuro, {name}. Feito uma capa, só que por dentro."
L["Curses slide right off you now, {name}. The cultists will take it personally."] = "Maldição agora escorrega em você, {name}. Os cultistas vão levar pro pessoal."
L["Priests study the Shadow to guard against it, {name}. Mostly."] = "Sacerdote estuda a Sombra pra se proteger dela, {name}. Quase sempre."
L["For crypts, cults and Scholomance, {name}. The dark gets chatty in all three."] = "Pra criptas, cultos e Scolomântia, {name}. O escuro fica tagarela nos três."
L["It won't keep off gloom, {name}. For that you want company. Here I am."] = "Contra baixo-astral não adianta, {name}. Pra isso, só companhia. Cá estou."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "Com a marca do Indomado, {name}. Os cervos vão tirar a galhada quando você passar."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "Talvez você fique com um leve cheiro de musgo, {name}. É sinal de que funcionou."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "Marca do Indomado, {name}. Os lobos ainda vão morder, mas com peso na consciência."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "O selo de aprovação da natureza, {name}. Os esquilos foram consultados."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "Um pouco de selvageria em você agora, {name}. Resista à vontade de uivar."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "Couro, garra e pelagem grossa, {name}. A natureza viaja leve, mas completa."
L["Cenarius signs every one of these, {name}. Well, a tree does, on his behalf."] = "Cenarius assina cada uma destas, {name}. Quer dizer, uma árvore assina por ele."
L["The forest's own armour, {name}. It doesn't clank, and it smells of rain."] = "A armadura da própria floresta, {name}. Não faz clanc e tem cheiro de chuva."
L["A tougher hide in seconds, {name}. The oaks took centuries and are furious."] = "Couro grosso em segundos, {name}. Os carvalhos levaram séculos e estão furiosos."
L["It's a loan from the wild, {name}. Try not to bring it back chewed."] = "É um empréstimo da natureza, {name}. Tente não devolver mastigado."
L["Anything that bites you now gets a mouthful, {name}."] = "Quem te morder agora leva uma boca cheia de espinhos, {name}."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "Deixe o javali avançar, {name}. Ele vai sair com arrependimento e farpas."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "Feito uma rosa, {name}: linda de ver, um erro de pegar."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "Espinhos, {name}. Cultivo próprio, então trate-os com educação."
L["A hedge you can wear, {name}. Neatly trimmed; I'm not a barbarian."] = "Uma cerca viva pra vestir, {name}. Bem podada; selvageria tem limite."
L["Nature never turns the other cheek, {name}. It grows spikes on it."] = "A natureza não oferece a outra face, {name}. Oferece espinhos."
L["Raptors learn slowly, {name}. This teaches them one bite at a time."] = "Raptor aprende devagar, {name}. Isto ensina uma mordida por vez."
L["Prickly on the outside, {name}. What's inside is your own business."] = "Espinhos por fora, {name}. O que tem por dentro é assunto seu."
L["Mind your cloak, {name}. Wool and brambles never did get along."] = "Cuidado com a capa, {name}. Lã e espinheiro nunca se deram bem."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "Bênção dos Reis, {name}. Sem coroa, sem trono, sem imposto."
L["Long may you reign, {name}. For the next while, anyway."] = "Vida longa ao seu reinado, {name}. Pelo menos por um tempinho."
L["A little more of everything, {name}. Kings never did settle for less."] = "Um pouco mais de tudo, {name}. Reis nunca se contentaram com menos."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "Uma bênção de rei, {name}. Já usada por cabeças melhores que a minha, e piores."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "Cada atributo um pouco maior, {name}. Reis gostam de apostar em todos os cavalos."
L["Crown not included, {name}. Everything else is, a little."] = "Coroa não inclusa, {name}. Todo o resto vem incluso, um pouquinho."
L["All of you, only more so, {name}. That's what they mean by the royal 'we'."] = "Você, só que mais, {name}. Daí o tal plural majestático."
L["A blessing fit for royalty, {name}. You'll have to do your own waving."] = "Uma bênção digna da realeza, {name}. O aceno fica por sua conta."
L["Stronger, cleverer, hardier, {name}. Kings had advisers for that; you have me."] = "Mais força, mais juízo, mais fibra, {name}. Reis tinham conselheiros; você tem a mim."
L["Royal treatment, {name}, minus the courtiers and the poisoned wine."] = "Tratamento de realeza, {name}, sem puxa-sacos nem vinho envenenado."
L["Might doesn't make right, {name}, but it does help the argument."] = "Poder não dá razão, {name}, mas ajuda bastante na discussão."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "Um golpe mais firme para você, {name}. A Luz adora quem vai até o fim."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "Braços mais fortes, {name}. Por gentileza, aponte para algo que mereça."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "Bênção do Poder, {name}. Vai te surpreender. Vai surpreendê-los bem mais."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "Pode bater, {name}. Se der certo, a Luz leva o crédito."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "Bata mais forte, {name}. Neles, digo. Não em mim. Nunca no paladino."
L["More weight behind every swing, {name}. The Light calls it conviction."] = "Mais peso em cada golpe, {name}. A Luz chama isso de convicção."
L["Doors, crates and ogres will all give way easier now, {name}."] = "Portas, caixotes e ogros vão ceder mais fácil agora, {name}."
L["Your weapon will feel lighter, {name}. It isn't. You're just holier."] = "Sua arma vai parecer mais leve, {name}. Não está. É santidade mesmo."
L["The Light's own elbow grease, {name}. Put it somewhere useful."] = "O muque da própria Luz, {name}. Use em algo útil."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "Sabedoria para você, {name}. Guardei um pouco para mim. Bem pouquinho."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "Sabedoria para sua mana, {name}. A outra ainda vem das más decisões."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "Sua mana agora volta sozinha, {name}, feito um gato que já te perdoou."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "Menos goles entre combates, {name}. Os estalajadeiros vão ficar arrasados."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "Beba menos, lance mais, {name}. Dica de economia da própria Luz."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "Bênção da Sabedoria, {name}: a única bênção que se paga sozinha."
L["Mana, {name}, not judgement. Judgement's a separate seal, and I'm keeping it."] = "Mana, {name}, não juízo. O Julgamento é outro selo, e esse fica comigo."
L["Wisdom usually comes with age, {name}. This comes with a paladin. Quicker."] = "Sabedoria costuma vir com a idade, {name}. Esta vem com paladino. Mais rápido."
L["The blessing is wise, {name}. The decisions are still entirely ours."] = "A bênção é sábia, {name}. As decisões, infelizmente, continuam nossas."
L["A wise blessing for a wise choice, {name}: keeping a paladin around."] = "Bênção sábia pra uma escolha sábia, {name}: manter um paladino por perto."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "Uma bênção de silêncio, {name}. Os monstros vão esquecer de quem foi a culpa."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "Bênção da Salvação, {name}. Agora você é problema de outra pessoa."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "Salvação, {name}. Da alma, não. Só da pele."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "Bata forte, {name}. Se algo se virar, faça cara de inocente. A Luz vai fazer igual."
L["The monsters will find you forgettable now, {name}. Today, that's a compliment."] = "Os monstros vão achar você esquecível agora, {name}. Hoje, isso é elogio."
L["Go on, hit it, {name}. It'll blame whoever's wearing the most plate."] = "Pode bater, {name}. Ele vai culpar quem estiver com mais placa."
L["The art of being in the fight, {name}, and out of the argument."] = "A arte de estar no combate, {name}, e fora da treta."
L["The Light's kindest alibi, {name}. Use it often."] = "O álibi mais gentil da Luz, {name}. Use à vontade."
L["The Light will find you easier now, {name}. Try not to squint."] = "A Luz vai te achar mais fácil agora, {name}. Tente não apertar os olhos."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "Luz Sagrada agora rende mais em você, {name}. Por favor, não me faça provar."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "Você vai sarar mais fácil, {name}. A Luz adora paciente que colabora."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "Bênção da Luz, {name}. Agora é mais fácil te salvar. Não que você vá precisar."
L["The Light knows the way to you now, {name}. Let's keep its visits social."] = "A Luz agora sabe o caminho até você, {name}. Que sejam só visitas de cortesia."
L["A blessing that makes my job easier, {name}. Generous and lazy all at once."] = "Bênção que facilita meu trabalho, {name}. Generosidade e preguiça numa tacada só."
L["Holy Light fits you better now, {name}, like a well-cut tabard."] = "Luz Sagrada agora te cai melhor, {name}, feito tabardo sob medida."
L["Mending you just got cheaper, {name}. Not that I'd ever send a bill."] = "Te consertar ficou mais barato, {name}. Não que eu vá mandar a conta."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "Bloqueie um golpe agora, {name}, e a Luz revida por você. Ela é rancorosa."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "Todo golpe chega mais fraco agora, {name}. Reclamações, com a Luz."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "Toda a proteção de um templo, {name}, sem precisar consertar o telhado."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "Peça santuário, {name}. Fica mais fácil quando você traz o seu."
L["Every blow is a little less rude now, {name}. The Light teaches manners."] = "Todo golpe fica menos grosseiro agora, {name}. A Luz ensina boas maneiras."
L["Nobody can evict you from this sanctuary, {name}. I checked the deeds."] = "Ninguém te despeja deste santuário, {name}. Conferi a escritura."
L["An ogre's club lands like a pillow now, {name}. A heavy, angry pillow."] = "Porrete de ogro agora cai feito travesseiro, {name}. Pesado e bravo."
L["Instructions, {name}: hit things harder. There is no page two."] = "Instruções, {name}: bata mais forte nas coisas. Não tem página dois."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "Braço da espada resolvido, {name}. Para o resto, procure um sacerdote."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "Brado de Batalha, {name}. Não é bem um feitiço. É uma sugestão bem gritada."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "RAAAGH! Esse foi pra você, {name}. O resto só ouviu sem querer."
L["Priests pray, mages study, {name}. I clear my throat."] = "Sacerdote reza, mago estuda, {name}. Eu pigarreio."
L["Words matter, {name}. Mostly the loud ones."] = "Palavra tem poder, {name}. Mais ainda berrada."
L["The shout lasts a few minutes, {name}. The ringing in your ears, rather longer."] = "O brado dura uns minutos, {name}. O zumbido no ouvido, bem mais."
L["There were words in that shout once, {name}. They slowed it down."] = "Esse brado já teve palavras, {name}. Atrasavam tudo."
L["A little breath from the damned, {name}. They weren't using it."] = "Um pouco de fôlego dos condenados, {name}. Eles não estavam usando."
L["Unending Breath, {name}. The fish will have so many questions."] = "Fôlego sem fim, {name}. Os peixes vão ter tantas perguntas."
L["Stay down as long as you like, {name}. Something else is holding its breath."] = "Fique no fundo o quanto quiser, {name}. Outra coisa está prendendo a respiração."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "Nade fundo, {name}. Se um murloc perguntar, você está só de visita."
L["Air from a place where air isn't strictly air, {name}. Breathe it anyway."] = "Ar de um lugar onde ar não é bem ar, {name}. Respire assim mesmo."
L["The Vile Reef awaits, {name}. Try not to find out how it earned the name."] = "O Recife Vil espera por você, {name}. Tente não descobrir de onde veio o nome."
L["Dropped something in a lake, {name}? Now's your chance."] = "Deixou algo cair num lago, {name}? Chegou a hora."
L["No gills, {name}. I read the small print; gills were extra."] = "Sem guelras, {name}. Li as letras miúdas: guelra é cobrada à parte."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "Vão achar que é duelo, {name}. Valeu por {gift}."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} por {buff}. Sem a taxa do leiloeiro, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "Chegou antes, {name}! {gift} venceu minha educação na corrida."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "Entra {gift}, sai {buff}. A melhor economia de Azeroth."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}, pra mim? Só tenho isto, {name}, mas é de coração."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "{gift} caiu como uma luva, {name}. Tirou minhas medidas?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "Um tratado em feitiços, {name}: {gift} por {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}! Já sinto que cresci. Tome um pouco de {buff}."
L["I was about to ask for {gift}, {name}. You read my mind."] = "Eu ia pedir {gift}, {name}. Você leu minha mente."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "{gift} ainda borbulha, {name}. Tome umas borbulhas de volta."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "{gift}, que gentileza, {name}. Vou contar pra estalagem toda. Duas vezes."
L["You cast {gift} first, {name}? My mother would despair of me."] = "Você lançou {gift} primeiro, {name}? Minha mãe teria vergonha de mim."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "Vou me lembrar de {gift} com carinho, {name}. Até o efeito passar."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} por {buff}, de graça. Em algum lugar, um goblin chora."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "Eu com {gift}, você com {buff}. Agora ninguém nos aguenta."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "Valeu por {gift}, {name}. Vou fazer por merecer antes que acabe."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "Por {gift} eu te daria as duas luas, {name}. Isto vai ter que servir."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "Você trouxe {gift}, eu trouxe {buff}. Agora virou festa."
L["{gift} means 'good luck'. {buff} means 'you too'."] = "{gift} é 'boa sorte'. {buff} é 'pra você também'."
L["Your {gift} came first; my {buff} tries twice as hard."] = "{gift} chegou primeiro; {buff} se esforça em dobro."
L["If anyone asks, {buff} came before {gift}. Deal?"] = "Se perguntarem, {buff} veio antes de {gift}. Combinado?"
L["{gift} made my day; {buff} should make your hour."] = "{gift} salvou meu dia; {buff} deve salvar sua hora."
L["Saved my {buff} for someone special. Then came {gift}."] = "Guardei {buff} pra alguém especial. Aí veio {gift}."
L["Your {gift} went to my head; my {buff} goes to yours."] = "{gift} me subiu à cabeça; {buff} vai pra sua."
L["{gift} on me, {buff} on you. We wear each other's work."] = "{gift} em mim, {buff} em você. Um veste o trabalho do outro."
L["{gift} and {buff} fade. Kindness lasts. Well, longer."] = "{gift} e {buff} acabam. Gentileza dura. Bom, dura mais."
L["You shared {gift}; I share {buff}. Next, snacks."] = "Você dividiu {gift}; eu divido {buff}. Depois, petiscos."
L["{gift} caught me empty-handed. Not any more: {buff}."] = "{gift} me pegou de mãos abanando. Não mais: {buff}."
L["{gift}, best thing all day. {buff}, my bid for second."] = "{gift}, o melhor do dia. {buff}, meu lance pelo vice."
L["{gift} deserves a statue. I'm no sculptor, so: {buff}."] = "{gift} merece uma estátua. Não sei esculpir, então: {buff}."
L["{gift} for {buff}? Keep this up and we'll draw a queue."] = "{gift} por {buff}? Desse jeito vai formar fila."
L["{gift} was kind. {buff} is kind back, and competitive."] = "{gift} foi gentileza. {buff} também é, e das competitivas."
L["{gift} came like good news. {buff}, by return post."] = "{gift} veio feito boa notícia. {buff}, na volta do correio."
L["{gift}, meet {buff}. Do get along, you two."] = "{gift}, conheça {buff}. Comportem-se, hein."
L["Trade you {buff} for {gift}? Ah, you've already paid."] = "Troco {buff} por {gift}? Ah, você já pagou."
L["{gift} and {buff}. The inn will say we rehearsed."] = "{gift} e {buff}. Na estalagem vão dizer que ensaiamos."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}! Acabei de ter três ideias geniais, {name}. Esta foi uma."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "Com {gift}, {name}, finalmente entendo minhas próprias anotações. Valeu."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "Minha mente já clareou, {name}. O bastante para saber que te devo uma. Tome."
L["Your {gift} found me the word for this, {name}: 'thanks'."] = "{gift} me deu a palavra certa pra isso, {name}: 'valeu'."
L["{gift}! I understood a goblin contract, {name}. I'm appalled."] = "{gift}! Entendi um contrato goblin, {name}. Que horror."
L["{gift}! I finally get last week's mage joke, {name}. Thanks."] = "{gift}! Enfim entendi a piada de mago da semana passada, {name}. Valeu."
L["I'll use your {gift} for more than arguing, {name}. Probably."] = "Vou usar {gift} pra mais que discutir, {name}. Provavelmente."
L["Thank you, {name}. My next spell gets three extra syllables, just to show off."] = "Agradeço, {name}. Meu próximo feitiço ganha três sílabas extras, só pra me exibir."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name}? Vou ficar na frente, pra variar. Rapidinho."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "Joelhos, cotovelos e orgulho, {name}: tudo fortificado. Agradeço."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "Pode me bater agora, {name}. Melhor não. Mas agradeço; eu aguentaria."
L["Nigh unbreakable now, {name}. Let's never test the 'nigh'. Thank you."] = "Quase inquebrável agora, {name}. Nunca vamos testar o 'quase'. Agradeço."
L["{gift}! My healer owes you a letter, {name}. I owe you this."] = "{gift}! Meu curador te deve uma carta, {name}. Eu te devo isto."
L["Every bruise I don't get today, {name}, I owe to your {gift}."] = "Cada hematoma que eu não levar hoje, {name}, devo a {gift}."
L["I could lose an argument with an ogre now and live, {name}. Thank you."] = "Agora eu perderia uma discussão com um ogro e sobreviveria, {name}. Agradeço."
L["Thank you, {name}. I feel like a castle wall. A grateful one."] = "Agradeço, {name}. Virei muralha de castelo. Das agradecidas."
L["Thank you, {name}. The next boar to charge me is in for a long afternoon."] = "Agradeço, {name}. O próximo javali que me atacar vai ter uma tarde longa."
L["{gift}! My spirits are lifted, {name}. Literally, it seems."] = "{gift}! Meu espírito se elevou, {name}. Literalmente, pelo visto."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "Com o dobro de calma e metade do mau humor, {name}. Agradeço."
L["Your {gift} nearly made me sing, {name}. Take this. It's kinder."] = "{gift} quase me fez cantar, {name}. Tome isto; seus ouvidos agradecem."
L["{gift}, {name}? I've forgiven three people already. Thank you."] = "{gift}, {name}? Já perdoei três pessoas. Agradeço."
L["I was on fumes, {name}. Your {gift} was a hot meal and a hearth."] = "Eu estava na reserva, {name}. {gift} foi comida quente e lareira."
L["I've stopped counting mana between fights, {name}. Thank you."] = "Parei de contar mana entre combates, {name}. Agradeço."
L["My spirit's topped up, {name}, and the rest of me is grateful too."] = "Meu espírito está no máximo, {name}, e o resto de mim também agradece."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "À prova de sombra, graças a você, {name}. Os sussurros estão furiosos."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "Nada sombrio entra agora, {name}. Aqui vai algo luminoso no sentido contrário."
L["{gift}! Shadowfang Keep can keep its shadows, {name}. Thank you."] = "{gift}! A Bastilha da Presa Negra que guarde suas sombras, {name}. Valeu."
L["The next shadow bolt's in for a letdown, {name}. Thank you."] = "A próxima Seta Sombria vai se decepcionar, {name}. Agradeço."
L["On your {gift} I'll brave Duskwood tonight, {name}. Or tomorrow."] = "Com {gift} encaro a Floresta do Crepúsculo hoje, {name}. Ou amanhã."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}! Um esquilo acabou de acenar pra mim, {name}. Tome, em troca."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "Couro grosso, faro apurado, {name}. Difícil segurar a vontade de fuçar o mato."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "Sinto a natureza brotando, {name}. Agradeço. Desculpe se eu soltar casca."
L["Thicker skin from your {gift}, {name}. Arrows and insults both."] = "Couro mais grosso com {gift}, {name}. Aguenta flecha e desaforo."
L["{gift}! A bird tried to nest on me, {name}. Thanks, I think."] = "{gift}! Um pássaro tentou fazer ninho em mim, {name}. Valeu, acho."
L["Half a tree now, {name}, the better half. Thanks for the {gift}."] = "Virei meia árvore, {name}. A metade boa. Valeu por {gift}."
L["Thank you, {name}. I've an urge to stand in the rain and grow. I'll resist."] = "Agradeço, {name}. Deu vontade de ficar na chuva e crescer. Vou resistir."
L["Every bramble in the Barrens will think twice now, {name}. Thank you."] = "Todo espinheiro dos Sertões vai pensar duas vezes agora, {name}. Agradeço."
L["Thank you, {name}. Even my boots feel like they've put down roots."] = "Agradeço, {name}. Até minhas botas parecem ter criado raízes."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name}! Hoje ninguém me abraça. Tome isto no lugar."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "Agora tenho espinhos, graças a você, {name}. Mais do que o normal, digo."
L["Your {gift}, {name}! Let the next kobold try for my candle."] = "{gift}, {name}! Agora quero ver kobold pegar minha vela."
L["{gift}! I'm a thicket with opinions now, {name}. Thank you."] = "{gift}! Virei uma moita com opinião própria, {name}. Agradeço."
L["Thank you, {name}. The next thing that bites me will need a moment to reflect."] = "Agradeço, {name}. O próximo que me morder vai precisar de um momento pra refletir."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift} vindo de você, {name}? Vou tentar não fundar uma dinastia."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "Um pouco melhor em tudo, {name}. É assim que os reis se sentem? Explica muita coisa."
L["Your {gift}! My first decree, {name}: thank you."] = "{gift}! Primeiro decreto real, {name}: valeu."
L["{gift} on a commoner, {name}? I'll try to look regal."] = "{gift} pra plebe, {name}? Vou tentar pose de realeza."
L["With your {gift} I could rule a small kingdom, {name}. Westfall."] = "Com {gift} eu governaria um reino pequeno, {name}. O Cerro Oeste."
L["Thank you, {name}. I'm a little better at everything now, gratitude included."] = "Agradeço, {name}. Estou um pouco melhor em tudo, inclusive em agradecer."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "Braços já mais fortes, {name}. Vou evitar abraçar alguém. Agradeço."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "Com {gift} eu levantaria um kodo, {name}. Não vou, mas agradeço."
L["Your {gift} has my arms very confident, {name}. Thank you."] = "{gift} deixou meus braços muito confiantes, {name}. Agradeço."
L["{gift}! Opened a jar I've fought since Stranglethorn, {name}."] = "{gift}! Abri um pote que me vencia desde a Selva do Espinhaço, {name}."
L["Thank you, {name}. My next swing is dedicated to you. So is the dent."] = "Agradeço, {name}. Meu próximo golpe é dedicado a você. O amassado também."
L["{gift} from you, {name}, and my first wise act is this."] = "{gift} vindo de você, {name}, e meu primeiro ato sábio é este."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "Já com mais sabedoria, {name}. O bastante para reconhecer uma gentileza."
L["My mana thanks you for {gift}, {name}. It's the shy one of us."] = "Minha mana agradece por {gift}, {name}. Ela é a tímida da dupla."
L["Your {gift} refills me faster than I spend, {name}. Nearly."] = "{gift} me enche mais rápido do que eu gasto, {name}. Quase."
L["Your {gift}, {name}: mana back, and an urge to give advice."] = "{gift}, {name}: mana de volta e uma vontade de dar conselhos."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}! Os monstros me esqueceram na hora, {name}. Eu não esqueço."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "Nada quer brigar comigo agora, {name}. Que delícia. Agradeço."
L["{gift}! Nothing's glared at me in minutes, {name}. Thank you."] = "{gift}! Faz minutos que nada me encara feio, {name}. Agradeço."
L["{gift}! A mouse at a dragon's feast, {name}: unseen, well fed."] = "{gift}! Rato no banquete do dragão, {name}: ninguém vê, e come bem."
L["Thanks to {gift} I'm just a rumour in a fight, {name}."] = "Graças a {gift}, em combate sou só um boato, {name}."
L["The Light finds me easier now, {name}. It says thank you, and so do I."] = "A Luz me acha mais fácil agora, {name}. Ela agradece, e eu também."
L["Easier to heal now, thanks to you, {name}. My healer thanks you too."] = "Mais fácil de curar agora, graças a você, {name}. Meu curador também agradece."
L["With your {gift}, {name}, every heal feels like a homecoming."] = "Com {gift}, {name}, cada cura parece uma volta pra casa."
L["{gift}! The Light and I are on first-name terms now, {name}."] = "{gift}! Agora a Luz e eu nos tratamos por apelido, {name}."
L["With {gift} the Light hears me first, {name}. No need to shout."] = "Com {gift} a Luz me ouve primeiro, {name}. Nem preciso gritar."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "Os golpes chegam mais fracos agora, {name}. Meus hematomas agradecem, e eu também."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "Cada golpe mais leve, graças a você, {name}. Vou garantir que notem."
L["Your {gift} softens every blow, {name}. I'm upholstered."] = "{gift} amacia cada golpe, {name}. Virei um estofado."
L["{gift}! Now the Light takes every hit personally, {name}."] = "{gift}! Agora a Luz leva cada golpe pro lado pessoal, {name}."
L["With your {gift} I'm half fortress, half chapel, {name}."] = "Com {gift} sou metade fortaleza, metade capela, {name}."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "Você gritou comigo, {name}, e nunca tive tanto ânimo. Tome."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "Meus ouvidos estão zumbindo, {name}, e meus braços, com o dobro de força. Valeu!"
L["{gift}, {name}! I felt that in my teeth. In a good way."] = "{gift}, {name}! Senti isso nos dentes. No bom sentido."
L["I'll answer your {gift} quietly, {name}. Somebody should."] = "Vou responder {gift} em silêncio, {name}. Alguém precisa."
L["Your {gift} nearly had me charging a wall, {name}. Here, calmly."] = "{gift} quase me fez dar Investida numa parede, {name}. Tome, com calma."
L["All Azeroth heard your {gift}, {name}. Only I get to thank you."] = "Azeroth inteira ouviu {gift}, {name}. Só eu posso agradecer."
L["Your shout's still ringing, {name}, and so is my sword arm. Thank you."] = "Seu brado ainda ecoa, {name}, e meu braço da espada também. Agradeço."
L["I didn't catch the words, {name}, but my arms did. Thank you!"] = "Não entendi as palavras, {name}, mas meus braços entenderam. Valeu!"
L["Thank you, {name}. I'll hit the next thing twice as hard and blame you."] = "Agradeço, {name}. Vou bater o dobro na próxima coisa e pôr a culpa em você."
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "Consigo respirar debaixo d'água, {name}! Talvez nunca precise, mas agradeço."
L["Lungs like a murloc, thanks to you, {name}. Mrgl. Sorry. Thank you."] = "Pulmões de murloc, graças a você, {name}. Mrgl. Desculpe. Agradeço."
L["With {gift} I'll raid every sunken wreck, {name}. Half's yours."] = "Com {gift} vou saquear todo naufrágio, {name}. Metade é sua."
L["I won't ask where {gift} gets its air, {name}. Just: thanks."] = "Não vou perguntar de onde {gift} tira o ar, {name}. Só: valeu."
L["With {gift} I'll cross Lordamere Lake, {name}. Underneath."] = "Com {gift} atravesso o Lago Lordamere, {name}. Por baixo."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "Precisamos parar de nos encontrar assim, {name}. Pensando bem, não precisamos."
L["Again, {name}? Splendid. I've been practising since last time."] = "De novo, {name}? Esplêndido. Estive praticando desde a última vez."
L["You again, {name}? People will start saying we're friends."] = "Você de novo, {name}? Vão começar a dizer que somos amigos."
L["Same face, same spell, {name}. I do love a tradition."] = "Mesma cara, mesmo feitiço, {name}. Adoro uma tradição."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "Outra rodada, {name}? No placar, nós dois estamos ganhando."
L["Ah, {name}! My favourite repeat customer."] = "Ah, {name}! Minha freguesia preferida."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "Nossos caminhos vivem se cruzando, {name}. A estrada está mandando indiretas."
L["Hello again, {name}. Do stop me if you've heard this one."] = "Olá de novo, {name}. Me interrompa se já ouviu essa."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "Guardei um pouco, {name}, caso você voltasse. Belo instinto o meu."
L["Back already, {name}? I'm starting to think you like me."] = "Já de volta, {name}? Estou começando a achar que você gosta de mim."
L["Again, {name}? At this rate I'll have to learn your middle name."] = "De novo, {name}? Desse jeito vou ter que aprender seu sobrenome."
L["Once is kindness, twice is a habit, {name}. I've never broken a habit yet."] = "Uma vez é gentileza, duas é costume, {name}. E costume eu nunca larguei."
L["Encore, {name}. The crowd demanded it. The crowd is you."] = "Bis, {name}. O público pediu. O público é você."
L["One more of these, {name}, and we'll have to draw up a guild charter."] = "Mais uma dessas, {name}, e vamos ter que assinar um alvará de guilda."
L["I'd know your footsteps anywhere now, {name}. Handy; I'm terrible with faces."] = "Reconheço seus passos em qualquer lugar, {name}. Ainda bem; rosto não é meu forte."
L["Us again, {name}. The world must be running out of other people."] = "Nós de novo, {name}. O mundo deve estar ficando sem gente."
L["Last time went so well, {name}, I've changed nothing. Not even my expression."] = "Da última vez foi tão bem, {name}, que não mudei nada. Nem a cara."
L["I know where you stand now, {name}. Literally; I've aimed at it before."] = "Já sei qual é a sua posição, {name}. Literalmente; já mirei nela antes."
L["Oh, it's you, {name}. Good. I hate giving these to strangers."] = "Ah, é você, {name}. Ótimo. Detesto dar isto pra desconhecidos."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, a essa altura a gente devia dividir uma bolsa de reagentes."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "Mesmo horário amanhã, {name}? Eu levo {buff}. Você leva você."
L["I've lost count, {name}, and I've decided that's a compliment."] = "Perdi a conta, {name}, e decidi que isso é um elogio."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "Continue assim, {name}, e os bardos vão escrever uma canção bem chata sobre nós."
L["I could do this one in my sleep by now, {name}. I may have."] = "Já consigo fazer isso dormindo, {name}. Talvez até tenha feito."
L["{name}, the usual? Of course the usual. It's always the usual."] = "{name}, o de sempre? Claro que o de sempre. É sempre o de sempre."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "Já devíamos ter um aperto de mão secreto, {name}. Quem sabe na próxima."
L["By now, {name}, I think we've built a small economy between us."] = "A essa altura, {name}, acho que já criamos uma pequena economia entre nós."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "Já somos velhos amigos, {name}. Bom, velhos conhecidos com ótima sincronia."
L["Let the record show: {name} and I, undefeated at being prepared."] = "Que fique registrado: {name} e eu, invencíveis em preparo."
L["My spellbook opens to your page on its own now, {name}."] = "Meu grimório já abre sozinho na sua página, {name}."
L["If you stopped turning up, {name}, I'd report you missing to the guards."] = "Se você sumisse, {name}, eu ia dar queixa de desaparecimento aos guardas."
L["So much has passed between us, {name}, I've lost track of whose is whose."] = "Já trocamos tanta coisa, {name}, que perdi a conta do que é de quem."
L["We're a local landmark now, {name}. Travellers give directions by us."] = "Viramos ponto de referência, {name}. Viajante já ensina caminho pela gente."
L["The innkeepers ask after you now when I come in alone, {name}."] = "Os estalajadeiros já perguntam por você quando chego só, {name}."
L["The guards wave us both through now, {name}. They assume we're a set."] = "Os guardas já liberam nós dois, {name}. Acham que viemos em kit."
L["Folk ask which of us taught the other, {name}. I say you, to be polite."] = "Perguntam quem ensinou quem, {name}. Digo que foi você, por educação."
L["I'd miss this if it stopped, {name}. So let's not stop."] = "Eu sentiria falta disso, {name}. Então que não acabe."
L["Somewhere a tavern has heard all about us, {name}. Mostly from me."] = "Alguma taverna já sabe tudo sobre nós, {name}. Quase tudo por mim."
L["I hum a little when I see you coming now, {name}. Nobody else gets the hum."] = "Agora eu cantarolo quando vejo você chegando, {name}. Só você ganha cantarolada."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "Muralhas seguras, camas quentinhas e agora {buff}. Que mordomia, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "Os guardas dão conta, {name}, mas eu gosto de caprichar."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "Cuidado, {name}. Com essa cara de competência na cidade, vão te pedir favores."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "Nenhum monstro por quilômetros, {name}. Mas com a comida daqui, nunca se sabe."
L["For the crowds, {name}. In town, they're the real danger."] = "Para as multidões, {name}. Na cidade, elas é que são o perigo."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "Relaxe, {name}. Boa ação do dia feita; vou atrás de uma cerveja."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "Até na cidade, {name}, às vezes um dragão aparece. Melhor prevenir."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "Melhor fazer aqui dentro, {name}. Lá fora, ninguém fica parado o bastante."
L["Mind the pickpockets, {name}. This is the one thing on you they can't lift."] = "Cuidado com os trombadinhas, {name}. Isto é a única coisa sua que eles não levam."
L["City rules, {name}: no blades drawn, no spells thrown. This one's allowed."] = "Regras da cidade, {name}: nada de lâmina à mostra nem feitiço lançado. Este pode."
L["Nothing to fight here but the queue at the mailbox, {name}. Take this anyway."] = "Aqui o único inimigo é a fila da caixa de correio, {name}. Tome assim mesmo."
L["For the walk to the bank, {name}. It's always further than it looks."] = "Pra caminhada até o banco, {name}. É sempre mais longe do que parece."
L["Put that on before the banker sees, {name}. They'll want to charge interest."] = "Use isto antes que o banqueiro veja, {name}. Ele vai querer cobrar juros."
L["The watch keeps the peace, {name}. I just keep you in one piece."] = "A guarda mantém a paz, {name}. Eu mantenho você num pedaço só."
L["For the stairs, {name}. Whoever built this place never met a short way up."] = "Pras escadas, {name}. Quem construiu isto nunca ouviu falar em atalho."
L["Everything else in town has a price, {name}. This slipped past the merchants."] = "Tudo na cidade tem preço, {name}. Isto passou batido pelos mercadores."
L["Buy nothing from anyone who calls you 'friend', {name}. Except me."] = "Não compre nada de quem te chama de 'amizade', {name}. Menos de mim."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "Aqui fora tudo quer você no jantar, {name}. Agora vai precisar de um garfo maior."
L["No guards for miles, {name}, and the boars know it. Take this."] = "Nenhum guarda por quilômetros, {name}, e os javalis sabem disso. Tome."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "Aqui fora só tem a gente e os bichos, {name}. Vamos ser a metade mais dura na queda."
L["If a bear asks, {name}, you were like this when I found you."] = "Se um urso perguntar, {name}, você já estava assim quando te encontrei."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "Os lobos estão de olho em você, {name}. Isto deve fazê-los pensar duas vezes."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "Terra selvagem, {name}. Melhor não encarar só com boas intenções."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "Mapa, cantil, {buff}. Agora dá pra se perder direito, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "O acampamento está longe, {name}. Considere isto um teto portátil."
L["Murlocs, raptors, bandits, rain, {name}. This handles one of those. You pick."] = "Murlocs, raptores, bandidos, chuva, {name}. Isto resolve um deles. Você escolhe."
L["Nearest inn's a day's walk, {name}. The nearest thing with teeth is closer."] = "Estalagem, só a um dia de caminhada, {name}. Coisa com dentes, bem mais perto."
L["Two hills and a swamp to the next town, {name}. The swamp has opinions."] = "Dois morros e um pântano até a próxima cidade, {name}. O pântano tem opinião."
L["Camp carefully, {name}. Every nice clearing has an owner, and it has claws."] = "Acampe com cuidado, {name}. Toda clareira bonita tem dono, e o dono tem garras."
L["Out here the only law is the food chain, {name}. You've just moved up a rung."] = "Aqui a única lei é a cadeia alimentar, {name}. Você acabou de subir um degrau."
L["Something's following you, {name}. Probably a boar. This is in case it isn't."] = "Tem algo te seguindo, {name}. Deve ser um javali. Isto é pro caso de não ser."
L["Stay on the road, {name}. The road has guards. Some of the time."] = "Fique na estrada, {name}. A estrada tem guardas. Às vezes."
L["Rain's coming, {name}, and so are the wolves. One of those I can help with."] = "Vem chuva por aí, {name}, e lobos também. Com um dos dois eu ajudo."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "Em algum lugar aqui dentro um vilão ensaia um discurso, {name}. Vamos interromper."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "Seja o que for que nos espera no fim, {name}, vai se arrepender."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "Dizem que ninguém sai vivo daqui, {name}. Vamos ser mal-educados e desmentir."
L["Our host had years to prepare, {name}. We have {buff}."] = "O anfitrião teve anos pra se preparar, {name}. Nós temos {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "Ninguém constrói masmorra com porta dos fundos, {name}. Tome isto no lugar."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "Breu, armadilhas velhas, gênios piores. Pelo menos você tem proteção, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "Melhor isto agora, {name}, do que um discurso fúnebre depois."
L["There's treasure in here, {name}, and something very large sat on it."] = "Tem tesouro aqui, {name}, e algo enorme sentado em cima dele."
L["If a door slams shut behind us, {name}, that's tradition. Take this first."] = "Se uma porta bater atrás da gente, {name}, é tradição. Tome isto antes."
L["Mind the patrols, {name}. They walk the same loop forever and resent it."] = "Cuidado com a patrulha, {name}. Ronda eterna, paciência zero."
L["Whoever built this place, {name}, spent it all on skulls and nothing on lamps."] = "Quem construiu isto aqui, {name}, gastou tudo em caveira e nada em lampião."
L["The last lot through here were never seen again, {name}. They lacked this."] = "O último grupo que entrou aqui nunca mais foi visto, {name}. Faltava isto."
L["Check the ceiling, {name}. In places like this, something always drops in."] = "Olhe pro teto, {name}. Num lugar desses, sempre tem alguém caindo de paraquedas."
L["If we meet a talking skull, {name}, let me do the talking."] = "Se aparecer caveira falante, {name}, deixa que eu falo."
L["If the walls start whispering, {name}, don't answer. It only encourages them."] = "Se as paredes começarem a sussurrar, {name}, não responda. Só dá corda."
L["Touch nothing that glows, pull nothing that clicks, {name}. Wear this."] = "Não toque no que brilha, não puxe o que faz clique, {name}. Vista isto."
L["Stick together in here, {name}. Echoes carry, and so do grudges."] = "Aqui dentro, fique perto, {name}. O eco vai longe, e o rancor também."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "Bandeiras, torres, cemitérios, {name}. Seja qual for o motivo da briga, tome isto."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "Ganhe ou perca, {name}, ninguém vai dizer que você entrou sem preparo."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "O cemitério é logo ali, {name}. Vamos combinar de não visitar."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "A honra está em jogo, {name}. A bandeira também. Principalmente a bandeira."
L["Stay with the group, {name}. Lone heroes end up in the other side's songs."] = "Fique com o grupo, {name}. Herói solitário acaba nas canções do outro lado."
L["Our banner looks better with you under it, {name}. Stand tall."] = "Nosso estandarte fica melhor com você embaixo, {name}. Cabeça erguida."
L["Keep your head down and your colours up, {name}."] = "Cabeça baixa e bandeira alta, {name}."
L["Hold the line, {name}. The songs are always about the ones who stood."] = "Mantenha a posição, {name}. As canções sempre falam de quem não arredou pé."
L["The spirit healer knows my face by now, {name}. Let's keep yours a stranger."] = "O Curandeiro Espiritual já sabe meu nome, {name}. Que o seu ele nunca aprenda."
L["Drums are for courage, {name}. This is for everything else."] = "Tambor é pra coragem, {name}. Isto é pro resto."
L["The quartermaster counts marks, {name}. I count friends. You're on my list."] = "O intendente conta marcas, {name}. Eu conto amigos. Você está na minha lista."
L["Fight for the banner, {name}, but come back for the singing. Mine's dreadful."] = "Lute pela bandeira, {name}, mas volte pra cantoria. Eu canto mal que dói."
L["Early bird, {name}? Here's something better than a worm."] = "Quem cedo madruga, {name}, ganha uma ajudinha. Tome."
L["Good morning, {name}. Consider this your first cup of something strong."] = "Bom dia, {name}. Considere isto seu primeiro café forte."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "Começando cedo, {name}. O dia ainda nem teve tempo de dar errado."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "Nem deu a hora do almoço, {name}, e você já tem mais preparo que eu."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "Bom dia, {name}. Em algum lugar, os monstros ainda estão bocejando."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "Dia novo e {buff} de novo, {name}. Não vamos desperdiçar nenhum dos dois."
L["Up with the sun, {name}? Show-off. Here; the sun doesn't get one."] = "De pé junto com o sol, {name}? Se exibindo, hein? Tome; o sol fica sem."
L["Rise and shine, {name}. Well, rise. The shining can wait till after breakfast."] = "Acorda pra vida, {name}. Bom, acorda. A vida pode esperar o café da manhã."
L["Dawn, {name}. Everything's golden and nobody's shouted yet. Let's enjoy it."] = "Amanhecer, {name}. Tudo dourado e ninguém gritou ainda. Vamos aproveitar."
L["Too early for heroics, {name}? Nonsense. Heroics go best before lunch."] = "Cedo pra heroísmo, {name}? Que nada. Heroísmo rende mais antes do almoço."
L["The birds are singing, {name}. They haven't seen what's out there yet."] = "Os passarinhos estão cantando, {name}. Ainda não viram o que tem lá fora."
L["Morning, {name}. Here's the first good deed of the day. It's all downhill now."] = "Bom dia, {name}. Eis a primeira boa ação do dia. Agora é só ladeira abaixo."
L["Still yawning, {name}? This works faster than tea."] = "Ainda bocejando, {name}? Isto é mais rápido que cafezinho."
L["Early, {name}. The dawn patrol looks at us like we've lost our minds."] = "Cedinho, {name}. A patrulha da alvorada acha que a gente pirou."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "Na rua a essa hora, {name}? A noite tem mais fome que o dia. Tome."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "Passou da hora de dormir, {name}. Gente sensata já dorme; sobramos nós."
L["Can't sleep either, {name}? Then let's be well-protected insomniacs."] = "Sem sono também, {name}? Então que sejamos insones com proteção."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "Cuidado com o escuro, {name}. Nem tudo lá fora é tão simpático quanto eu."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "Está tarde, {name}. Isto deve te segurar até o sol lembrar da gente."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "Só nós e as corujas de pé, {name}, e as corujas ficam sem {buff}."
L["The inns have locked up, {name}. This is the only thing still being served."] = "As estalagens fecharam, {name}. A saideira é por minha conta."
L["It's the hour for ghost stories, {name}. Take this, in case one is true."] = "É hora de história de fantasma, {name}. Tome isto, caso alguma seja verdade."
L["Candles low, stars high, {name}. A good hour for small kindnesses."] = "Velas baixas, estrelas altas, {name}. Boa hora para pequenas gentilezas."
L["Quiet hour, {name}. Every creak sounds like an ambush. Most of them aren't."] = "Hora do silêncio, {name}. Todo rangido parece emboscada. Quase nenhum é."
L["This late, {name}, even the guards are talking to themselves."] = "A essa hora, {name}, até os guardas estão falando sozinhos."
L["This is the hour things climb out of graves, {name}. Take this; walk briskly."] = "É a hora em que as coisas saem da cova, {name}. Tome isto e apresse o passo."
L["Tomorrow you'll wonder why you stayed up, {name}. This is one good reason."] = "Amanhã você vai se perguntar por que não foi dormir, {name}. Eis um bom motivo."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "Só quem é do ramo reconhece, {name}. E só quem é do ramo faz direito."
L["From one of our trade to another, {name}. No need to check my work."] = "De colega para colega, {name}. Não precisa conferir meu trabalho."
L["Professional courtesy, {name}. We don't charge each other."] = "Cortesia profissional, {name}. Entre colegas, não se cobra."
L["Two of a kind, {name}. Between us we could write the manual."] = "Somos da mesma escola, {name}. Juntos, dava pra escrever o manual."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "Não faça essa cara de surpresa, {name}. Mesmo instrutor, imagino."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "Eu criticaria sua técnica, {name}, mas a minha é igualzinha."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "Não conta pros outros, {name}, mas a nossa é mesmo a melhor vocação."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "Olha nós, {name}. Duas feras fazendo parecer fácil. Não é, né?"
L["Between colleagues, {name}: I also have no idea how half of it works."] = "Cá entre colegas, {name}: eu também não sei como metade disso funciona."
L["Same trade, {name}, so you know exactly how hard that was. Let's say very."] = "Mesmo ofício, {name}, então você sabe bem como isso foi difícil. Digamos: muito."
L["If anyone asks, {name}, we trained each other."] = "Se alguém perguntar, {name}, um treinou o outro."
L["Calling to calling, {name}. We should compare notes. Mine are mostly doodles."] = "Vocação com vocação, {name}: vamos comparar anotações. As minhas são rabiscos."
L["Colleague, {name}. We should found a society. Dues, minutes, a very small hat."] = "Colega, {name}. Vamos fundar uma sociedade. Mensalidade, ata, um chapeuzinho."
L["We'd be twins, {name}, if I were a touch better-looking."] = "Eu seria a sua cara, {name}, com um pouco mais de beleza."
L["I'd shout some encouragement, {name}, but you do that far better."] = "Eu gritaria umas palavras de incentivo, {name}, mas você grita bem melhor."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "Pode dar sua Investida, {name}. Agora fico com a consciência mais leve."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "Para quem entra primeiro, {name}. Alguém tem que entrar, e nunca sou eu."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "Você apanha para a gente não apanhar, {name}. É o mínimo que posso fazer."
L["Go on, {name}, charge. I'll be right behind you. Quite a long way behind."] = "Vai, {name}, avança. Estou logo atrás de você. Bem atrás, na verdade."
L["For the one who fixes every problem by hitting it, {name}. It usually works."] = "Para quem resolve tudo na base da pancada, {name}. E geralmente funciona."
L["I'd shake your hand, {name}, but both of yours are holding something sharp."] = "Eu apertaria sua mão, {name}, mas as duas estão segurando algo afiado."
L["A little help for a lot of armour, {name}. I hope it fits under there."] = "Uma ajudinha para muita armadura, {name}. Tomara que caiba aí dentro."
L["You'll charge something enormous soon, {name}. I'm just helping it lose."] = "Logo vem uma Investida em algo enorme, {name}. Eu só ajudo o coitado a perder."
L["Save the bubble for later, {name}. This one's from me."] = "Guarde a bolha para depois, {name}. Esta aqui é por minha conta."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "Você abençoa todo mundo o dia inteiro, {name}. Agora é na direção contrária."
L["The Light already likes you, {name}. Consider this a second opinion."] = "A Luz já gosta de você, {name}. Considere isto uma segunda opinião."
L["Even the Light's own champion needs a hand now and then, {name}."] = "Até o braço direito da Luz precisa de uma mãozinha às vezes, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "Eu pediria uma bênção de volta, {name}, mas aí ficaríamos nisso o dia todo."
L["For the one who carries a hammer and a conscience, {name}. Heavy load."] = "Para quem carrega um martelo e uma consciência, {name}. Carga pesada."
L["Don't thank the Light for this one, {name}. It had the day off. This was me."] = "Não agradeça à Luz por este, {name}. Ela está de folga. Fui eu."
L["No need to kneel, {name}. I know it's a habit."] = "Não precisa se ajoelhar, {name}. Eu sei que é mania."
L["One for you, {name}, and a pat on the head for your companion."] = "Isto para você, {name}, e um cafuné no seu mascote."
L["You watch everyone's back from range, {name}. I've got yours."] = "Você cuida das costas de todo mundo de longe, {name}. Das suas, cuido eu."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "Marca do Caçador para eles, {buff} para você, {name}. Bem mais simpático."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "Mire bem, {name}. E se vier pra cima mesmo assim, corra na nossa direção."
L["Your pet was looking at me hopefully, {name}. This is for you; tell it sorry."] = "Seu mascote me olhou com esperança, {name}. Isto é pra você; peça desculpas a ele."
L["Nothing for the pet this time, {name}. It's already had three of my sandwiches."] = "Nada pro mascote desta vez, {name}. Ele já comeu três sanduíches meus."
L["I'd have brought arrows, {name}, but I never know which kind you like."] = "Eu traria flechas, {name}, mas nunca sei de qual tipo você gosta."
L["You can track anything, {name}, but you never saw this one coming."] = "Você rastreia qualquer coisa, {name}, mas esta não viu chegar."
L["For the one I never see coming, {name}. Meant as the highest praise."] = "Para quem eu nunca vejo chegar, {name}. É o maior dos elogios."
L["Quick, {name}, before you vanish again."] = "Rápido, {name}, antes que você suma de novo."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "Veneno nas lâminas, {buff} em você. Tudo nos trinques, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "Eu passaria isto pro seu bolso, {name}, mas você ia notar. Você sempre nota."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "Para quem abre toda caixa trancada, {name}. Esta já vem destrancada."
L["Nobody sees you coming, {name}. Now it's even worse news when they do."] = "Ninguém te vê chegar, {name}. Agora, quando virem, é notícia ainda pior."
L["Take this, {name}. Very discreet. It even walks quietly."] = "Tome, {name}. Bem discreto. Anda até na ponta dos pés."
L["I'd have wrapped it, {name}, but you'd only pick the knot."] = "Eu teria embrulhado, {name}, mas você ia abrir o nó com gazua."
L["Keep this one, {name}. You don't even have to steal it."] = "Pode ficar com este, {name}. Nem precisa roubar."
L["For once, {name}, somebody's looking after the priest."] = "Pra variar, {name}, alguém cuida de quem cuida."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "Guarde suas preces para o resto de nós, {name}. Esta já foi atendida."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "Luz ou Sombra, {name}, nem pergunto. Isto serve para as duas."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "Ordens do paciente, {name}: depois deste combate, sente e beba."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "Você mantém todo mundo de pé, {name}. Aqui vai um pouco de volta."
L["You've knelt beside all of us, {name}. Stand tall a minute."] = "Você se ajoelhou por todos nós, {name}. Fique de pé um minutinho."
L["Something that needed no prayer, {name}. You've said plenty of those today."] = "Algo que não precisou de prece, {name}. Você já fez muitas hoje."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "Este não vem com voz na cabeça, {name}. Que alívio, né?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "A Lâmina de Ébano não pede favores, {name}. Estou fazendo um mesmo assim."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "Um pouco de calor, {name}. Sei que você não sente frio. O que vale é a intenção."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "Você voltou dos mortos, {name}. O mínimo que posso fazer é te ajudar a ficar por aqui."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "Runas, peste e gelo, {name}. Leve isto também; completa a coleção."
L["A skeletal horse and a sword that talks back, {name}. Here's something normal."] = "Um cavalo esquelético e uma espada que retruca, {name}. Tome algo normal."
L["No need to drag me over on a chain, {name}. I was coming anyway."] = "Não precisa me puxar pela corrente, {name}. Eu já estava indo."
L["Welcome back to the land of the living, {name}. Well, its general direction."] = "De volta à terra dos vivos, {name}. Bom, mais ou menos pro lado dela."
L["The elements look after you, {name}, but they don't make house calls."] = "Os elementos cuidam de você, {name}, mas não atendem em domicílio."
L["Tell the spirits I said hello, {name}. They never write back."] = "Manda um oi pros espíritos, {name}. Eles nunca respondem."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "Finque um totem em minha homenagem, {name}. Um pequeno. A modéstia manda."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "Terra, fogo, água, ar e eu, {name}. Reconheço: o elemento mais fraco."
L["Totems up already, {name}? Then this goes next to them. Don't plant it."] = "Totens já fincados, {name}? Então isto vai do lado. Não precisa fincar."
L["The wind would have brought you this, {name}, but it's flighty. I'm reliable."] = "O vento te traria isto, {name}, mas ele é meio avoado. Eu sou de confiança."
L["Tell the earth I said thanks, {name}. It's done so much for my feet."] = "Agradeça à terra por mim, {name}. Ela nunca me deixou sem chão."
L["The spirits said you'd earned this, {name}. I didn't ask; they volunteered."] = "Os espíritos dizem que você mereceu, {name}. Nem perguntei; foi espontâneo."
L["A gift for a mage, {name}? Like bringing water to... well, you."] = "Presente pra mago, {name}? É como levar água pra... bom, pra você."
L["You solve most problems with sheep, {name}. This covers the rest."] = "Você resolve quase tudo com ovelhas, {name}. Isto cobre o resto."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "Você se teleporta de qualquer encrenca, {name}. Isto é para a encrenca antes disso."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "Para a mente brilhante, {name}. Por favor, não agradeça me virando ovelha."
L["Blink wherever you like, {name}. This comes too."] = "Dê Lampejo pra onde quiser, {name}. Isto vai junto."
L["Stand a little back from the fire you're about to start, {name}. Here."] = "Afaste-se um pouco do incêndio que você vai causar, {name}. Tome."
L["You keep us all fed and watered, {name}. Your turn to be looked after."] = "Você dá comida e água pra todo mundo, {name}. Agora é a sua vez."
L["Portal fees are steep, {name}. Call this a down payment on my next one."] = "Portal anda caro, {name}. Considere isto a entrada do meu próximo."
L["Entirely demon-free, {name}. I checked."] = "Totalmente livre de demônios, {name}. Eu conferi."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "Seu diabrete pode ficar com ciúme, {name}. Diga que tem pra todo mundo."
L["No contract, no fine print, {name}. Just a gift."] = "Sem contrato, sem letras miúdas, {name}. Só um presente."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "Para quem distribui Pedras de Vida, {name}. Ninguém nunca te agradece."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "Tome, {name}. Depois invoque o resto de nós e ficamos quites."
L["Your voidwalker can stop hovering, {name}. I mean well."] = "Seu emissário do caos pode parar de rondar, {name}. Venho em paz."
L["Your felhunter eats magic, {name}. Keep it off this one; it's for you."] = "Seu caçador vil come magia, {name}. Deixe ele longe desta; é pra você."
L["Keep your imp downwind, {name}, and we'll call it even."] = "Deixe seu diabrete longe do meu nariz, {name}, e ficamos quites."
L["Carrying a bag of souls all day, {name}? Your shoulders must need this."] = "Carregando um saco de almas o dia todo, {name}? Seus ombros precisam disto."
L["Roll wherever you like, {name}. This rolls with you."] = "Role pra onde quiser, {name}. Isto rola junto."
L["Brew first or fight first, {name}? Either way, take this."] = "Primeiro a cerveja ou primeiro a briga, {name}? Tanto faz, tome isto."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "Paz interior para você, {name}, e exterior também, enquanto isto durar."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "O chi flui melhor com uma ajudinha, {name}. Ou foi o que um monge me disse."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "Chute, cambalhota, rolamento, {name}. Eu fico aqui e faço só esta parte."
L["Teach me to flip without spilling my drink, {name}, and we're even."] = "Me ensine cambalhota sem derramar a bebida, {name}, e ficamos quites."
L["Tea, meditation and this, {name}. The three pillars of a good day."] = "Chá, meditação e isto, {name}. Os três pilares de um bom dia."
L["Tell the bear this is for them too, {name}."] = "Avise o urso que isto é pra ele também, {name}."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "Não se mexa, {name}. Nunca consegui te alcançar em forma de chita."
L["Nature looks after you already, {name}. Today she sent me to help."] = "A natureza já cuida de você, {name}. Hoje ela me mandou ajudar."
L["Whatever shape you're in next, {name}, this goes with you."] = "Seja qual for sua próxima forma, {name}, isto vai junto."
L["For the forest's friend, {name}. Give my regards to the trees."] = "Para quem tem a floresta como amiga, {name}. Mande lembranças às árvores."
L["It's the least we can do for somebody who is also a bear, {name}."] = "É o mínimo que podemos fazer por alguém que também é um urso, {name}."
L["I'd hand it to the cat, {name}, but it would only knock it off the table."] = "Eu daria pro gato, {name}, mas ele só ia derrubar isto da mesa."
L["Say hello to your moonkin form for me, {name}. It always looks so startled."] = "Mande um oi pra sua forma de luniscante, {name}. Ela sempre parece tão assustada."
L["You were not prepared, {name}. Now you are."] = "Vocês não estão preparados? Você agora está, {name}."
L["Ten thousand years in a cell, {name}. You've earned a small kindness."] = "Dez mil anos numa cela, {name}. Você merece uma gentileza."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "Você abriu mão de tanto contra a Legião, {name}. Aqui vai um pouco de volta."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "Para quem salta primeiro, {name}. Tente cair em lugar amigável."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "Magia vil e fúria, {name}, e agora gentileza. Vai equilibrar."
L["I'd ask if you saw this coming, {name}, but you see everything."] = "Eu perguntaria se você viu isto chegando, {name}, mas você vê tudo."
L["You can see souls, {name}. Mine's the one being generous."] = "Você enxerga almas, {name}. A minha é a generosa aqui."
L["Illidan never let anyone help him, {name}. You're wiser than your teacher."] = "Illidan nunca aceitou ajuda, {name}. Você tem mais juízo que seu mestre."
L["A demon inside and a Legion outside, {name}. Here's one thing on your side."] = "Um demônio dentro e uma Legião fora, {name}. Eis algo do seu lado."
L["For you, {name}. Please don't breathe on it."] = "Para você, {name}. Por favor, não sopre fogo nisso."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "Uma ajudinha para um dragão, {name}. Vou contar pros meus netos."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "Os Aspectos te mandaram para o mundo, {name}. Estou deixando ele mais acolhedor."
L["Take to the skies after this, {name}. I'll wave from down here."] = "Depois disso, ganhe os céus, {name}. Eu aceno daqui de baixo."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "Um dragão do nosso lado, {name}. Nunca a generosidade foi tão segura."
L["A gift for a dragon, {name}. Normally folk bring gold and hope to leave again."] = "Presente pra dragão, {name}. Normalmente o povo traz ouro e reza pra sair vivo."
L["For the one who could fly me to the next town, {name}. Not asking. Hinting."] = "Pra quem me levaria voando à próxima cidade, {name}. Não é pedido, é indireta."
L["I've met a few dragons, {name}. You're the first I didn't run from."] = "Já vi alguns dragões, {name}. Só de você eu não saí correndo."
L["For the world's youngest ancient, {name}."] = "Para a lenda milenar mais novinha do mundo, {name}."
L["{buff} for a mage, {name}. Like lending a library a book."] = "{buff} para quem é mago, {name}. Feito emprestar livro pra biblioteca."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "De mago para mago, {name}: não te peço água se você não me pedir."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "Dois magos, {name}. Portal pra todo lado, e ainda assim chegamos tarde."
L["A mage for a mage, {name}. The Kirin Tor would call this peer review."] = "Um mago para outro, {name}. O Kirin Tor chamaria isso de revisão por pares."
L["A mage enchanting a mage, {name}. We'll both pretend we needed it."] = "Mago encantando mago, {name}. Vamos fingir que precisava."
L["Neither of us will admit which spells we still read off the page, {name}."] = "Ninguém aqui confessa quais feitiços ainda lança lendo a cola, {name}."
L["One mage is a scholar, {name}. Two is an argument. Here's my opening point."] = "Um mago é um erudito, {name}. Dois é uma discussão. Eis meu primeiro argumento."
L["We both know this spell backwards, {name}. Luckily I cast it forwards."] = "Sabemos este feitiço de trás pra frente, {name}. Sorte que lanço na ordem certa."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "Mais mana para você, {name}. Tente não gastar tudo numa Bola de Fogo só."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "De sacerdote para sacerdote, {name}: quem abençoa quem abençoa? Hoje, eu."
L["Between us priests, {name}, we'll both pretend the tank listens."] = "Cá entre nós, sacerdotes, {name}: vamos fingir que o tanque escuta."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "Sacerdote cuidando de sacerdote, {name}. Parece quase proibido."
L["Two priests, {name}. Twice the praying and half the panic."] = "Dois sacerdotes, {name}. O dobro de preces e metade do pânico."
L["Two priests, {name}. If it goes wrong, we're the last ones standing. Kneeling."] = "Dois sacerdotes, {name}. Se der errado, sobramos nós de pé. Digo, de joelhos."
L["Your prayers can take a break, {name}. Mine are covering the shift."] = "Suas preces podem tirar folga, {name}. As minhas cobrem o turno."
L["I'd preach to you, {name}, but you've heard it. You've probably given it."] = "Eu faria um sermão, {name}, mas você já ouviu. Provavelmente já até pregou."
L["Same vows and same sore knees, {name}. Here's something for yours."] = "Mesmos votos e mesmos joelhos doloridos, {name}. Tome algo pros seus."
L["If I fall, {name}, you know the words. If you fall, so do I. Let's neither."] = "Se eu cair, {name}, você sabe as palavras. Se você cair, eu também. Melhor não."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "Dois druidas, {name}. O Círculo Cenariano chamaria isso de quórum."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "De druida para druida, {name}: urso ou felino, te reconheço pelas folhas no cabelo."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "De metamorfo para metamorfo, {name}: este cabe em qualquer forma."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "Sem aperto de mão, {name}. Dois druidas, e nenhum na forma certa pra isso."
L["Between us, {name}, we've a shape for every problem. Mostly bears."] = "Cá entre nós, {name}, temos uma forma pra cada problema. Quase tudo urso."
L["Fellow druid, {name}? Then you know the trees told me you were coming."] = "Druida também, {name}? Então sabe que as árvores me avisaram da sua chegada."
L["If you see me as a cat later, {name}, pretend you don't know me. Dignity."] = "Se me vir de gato mais tarde, {name}, finja que não me conhece. Dignidade."
L["Paladin to paladin, {name}: I won't mention the bubble if you don't."] = "De paladino para paladino, {name}: não falo da bolha se você não falar."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "Bênção pra paladino, {name}. Agora somos dois radiantes insuportáveis."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "Dois paladinos, {name}. Em algum lugar, um sacerdote respira aliviado."
L["One of us should be humble about this, {name}. Neither of us will be."] = "Um de nós devia ter humildade nisso, {name}. Nenhum dos dois vai ter."
L["Same oath, different polish, {name}. Yours is shinier; I noticed."] = "Mesmo juramento, outro polimento, {name}. O seu brilha mais; reparei."
L["Between us, {name}, we could light a cathedral. Or a small, very holy room."] = "Com a gente, {name}, dá pra iluminar uma catedral. Ou uma salinha bem santa."
L["Two suits of plate, {name}. Nobody will hear us sneak up. Nobody ever does."] = "Duas armaduras de placa, {name}. Ninguém vai ouvir a gente chegar. Nunca ouvem."
L["Your libram and mine agree on this one, {name}. Rare, that."] = "Seu livro sagrado e o meu concordam nesta, {name}. Coisa rara."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "De bruxo para bruxo, {name}: mantenha seu diabrete longe do meu. Eles fofocam."
L["Fellow warlock, {name}? Then you know this one's actually harmless. Honestly."] = "Colega bruxo, {name}? Então sabe que este é inofensivo de verdade. Juro."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "Dois bruxos, {name}. Não vamos comparar fragmentos de alma em público."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "Cá entre nós, {name}, os demônios fazem todo o trabalho. Esta parte é comigo."
L["Another warlock, {name}. Let's be polite; I've seen what you summon."] = "Bruxo também, {name}? Melhor sermos educados; já vi o que você invoca."
L["A spell from one warlock to another, {name}. Check it for curses. I would."] = "Feitiço de bruxo pra bruxo, {name}. Confira se tem maldição. Eu conferiria."
L["Fellow warlock, {name}. The only one who won't ask where this came from."] = "Colega de pacto, {name}. A única pessoa que não pergunta de onde isto veio."
L["Two warlocks, one kind deed, {name}. The Burning Legion must be livid."] = "Dois bruxos, uma boa ação, {name}. A Legião Ardente deve estar possessa."
L["I'd summon you a drink, {name}, but we both know how summoning goes."] = "Eu te invocaria uma bebida, {name}, mas sabemos como invocação termina."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "Dois guerreiros, {name}. Algum curador acabou de suspirar."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "De guerreiro pra guerreiro, {name}: quem entra primeiro paga a bebida. Eu pago."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "Grito por grito, {name}. Juntos, vamos ensurdecer o lugar inteiro."
L["No plan, {name}? Perfect. We'll get along."] = "Sem plano, {name}? Perfeito. Vamos nos dar bem."
L["Warriors, {name}: the only folk who think shouting is a spell. We're right."] = "Guerreiros, {name}: o único povo que acha que grito é feitiço. E temos razão."
L["One warrior to another, {name}: whoever's hit first gets angriest. Lucky them."] = "Guerreiro pra guerreiro, {name}: quem apanha primeiro ganha mais Raiva. Que sorte."
L["You know this one, {name}. You've probably shouted it at me already."] = "Este você conhece, {name}. Aposto que já gritou ele na minha cara."
L["Our trainer would be proud, {name}. He'd shout it, but he'd be proud."] = "Nosso instrutor teria orgulho, {name}. Diria aos berros, mas teria."
L["Fellow warrior? Then you know the blacksmith's first name too, {name}."] = "Guerreiro também? Então você já trata o ferreiro pelo nome, {name}."
L["No mana to fill, {name}. It'll just stand about being clever, like me."] = "Sem mana pra encher, {name}. Vai ficar por aí posando de gênio, igual eu."
L["Intellect on a warrior, {name}. The Kirin Tor would call it research."] = "Intelecto num guerreiro, {name}. O Kirin Tor chamaria de pesquisa."
L["I only know the one spell for friends, {name}. Rage or mana, you're getting it."] = "Só sei um feitiço pra amigos, {name}. Raiva ou mana, você vai ganhar."
L["Your rage doesn't need this, {name}, but I'd feel rude walking past you."] = "Sua Raiva não precisa disso, {name}, mas passar direto seria grosseria."
L["No mana, I know, {name}. Use it on locks. They're only puzzles with opinions."] = "Sem mana, eu sei, {name}. Use nas fechaduras. São só quebra-cabeças com opinião."
L["It's meant for mana, {name}. You'll find a use. Rogues always find a use."] = "É pra mana, {name}. Você vai achar uma utilidade. Ladino sempre acha."
L["Energy, not mana, I know, {name}. Call it a very clever lockpick."] = "Energia, não mana, eu sei, {name}. Chame de gazua muito esperta."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "Opa, {name}, era só pedir! Agora não se mexe!"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "Toma, {name}, um trocinho pra te manter de pé."
L["My thanks, {name}. Allow me to return the kindness."] = "Agradeço, {name}. Permita-me retribuir a gentileza."
L["Of course, {name}. Stand fast a moment."] = "Claro, {name}. Fique firme só um instante."
L["The road ahead is long, {name}. Take this with you."] = "A estrada é longa, {name}. Leve isto com você."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. Sua gentileza é retribuída."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. Caminhe em paz sob as estrelas."
L["The Light rewards kindness, {name}, and so shall I."] = "A Luz recompensa a bondade, {name}, e eu também."
L["Of course, {name}. May the Naaru guide your steps."] = "Claro, {name}. Que os Naarus guiem seus passos."
L["The Light is with you, {name}. Go in peace."] = "A Luz está com você, {name}. Vá em paz."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "Fico em dívida, {name}. Guilnéas nunca esquece uma gentileza."
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar, {name}! Leve isto para a batalha."
L["The Earth Mother sees your kindness, {name}. I return it."] = "A Mãe Terra vê sua bondade, {name}. Eu a retribuo."
L["Of course, {name}. Stand tall and be at peace."] = "Claro, {name}. Cabeça erguida e fique em paz."
L["Walk with the Earth Mother, {name}."] = "Caminhe com a Mãe Terra, {name}."
L["Sure ting, {name}. Hold still now."] = "Firmeza, {name}. Agora não se mexe."
L["Da loa be watchin' over ya, {name}."] = "Os loa tão de olho em você, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "Tanta cortesia honra você, {name}. Anar'alah belore."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. Que o sol te guie."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "Sua generosidade foi notada, {name}. Suramar se lembra dos amigos."
L["Thank you, {name}! The caravan always repays a kindness."] = "Valeu, {name}! A caravana sempre retribui uma gentileza."
L["Every traveller needs something for the road, {name}."] = "Todo viajante precisa de algo para a estrada, {name}."
L["Of course, {name}. Patience, and it is done."] = "Claro, {name}. Paciência... e pronto."
L["Take this, {name}. Even a dragon needs allies."] = "Tome, {name}. Até um dragão precisa de aliados."
L["Thank you, {name}. The Alliance looks after its own."] = "Agradeço, {name}. A Aliança cuida dos seus."
L["Of course, {name}. Allies help each other."] = "Claro, {name}. Aliados se ajudam."
L["For the Alliance, {name}! Stay strong out there."] = "Pela Aliança, {name}! Força lá fora."
L["Strength and honour, {name}. Your kindness is repaid."] = "Força e honra, {name}. Sua gentileza está retribuída."
L["Consider it done, {name}. For the Horde."] = "Considere feito, {name}. Pela Horda."
L["For the Horde, {name}! Go with strength."] = "Pela Horda, {name}! Vá com tudo."
L["Thank you, {name}. Good hearts are found everywhere."] = "Agradeço, {name}. Há bons corações em toda parte."
L["Gladly, {name}, whatever banner you fly."] = "Com prazer, {name}, seja qual for sua bandeira."
L["Friends can come from any side, {name}."] = "Amigos podem vir de qualquer lado, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "Boa viagem, {name}. Leve um pouco de {buff} com você."
L["Returning a favour:"] = "Retribuindo um favor:"
L["Answering a request:"] = "Atendendo a um pedido:"
L["In your group:"] = "No seu grupo:"
L["Offering unasked:"] = "Oferecendo por conta própria:"
L["Returning a favour of %s:"] = "Retribuindo um favor de %s:"
L["Meeting somebody a third time:"] = "Encontrando alguém pela terceira vez:"
