L["Close (Escape works too)"] = "Fechar (Esc também funciona)"
L["No favours recorded today."] = "Nenhum favor registrado hoje."
L["Nothing you cast could return today's favours."] = "Nenhum feitiço seu poderia retribuir os favores de hoje."
L["Returned %d of 1 favour today."] = "Você retribuiu %d de 1 favor hoje."
L["Returned %d of %d favours today."] = "Você retribuiu %d de %d favores hoje."
L["1 favour still owed."] = "1 favor pendente."
L["%d favours still owed."] = "%d favores pendentes."
L["You gave 1 buff unprompted today."] = "Você deu 1 bônus por conta própria hoje."
L["You gave %d buffs unprompted today."] = "Você deu %d bônus por conta própria hoje."
L["All time -- received: %d, returned: %d, given to your group: %d, to strangers: %d"] = "Desde o início -- recebidos: %d, retribuídos: %d, dados ao seu grupo: %d, a desconhecidos: %d"
L["All time"] = "Desde o início"
L["received"] = "recebidos"
L["returned"] = "retribuídos"
L["to your group"] = "ao seu grupo"
L["to strangers"] = "a desconhecidos"
L["%d-%d of %d"] = "%d-%d de %d"
L["Everything"] = "Tudo"
L["Favours"] = "Favores"
L["Buffs you gave"] = "Bônus que você deu"
L["Nothing recorded. When somebody buffs you it is listed here, and so is what you give back and who you buff unprompted."] = "Nada registrado. Quando alguém dá bônus a você, isso aparece aqui, assim como o que você retribui e a quem você dá bônus por conta própria."
L["No favours recorded. When somebody buffs you, they are listed here."] = "Nenhum favor registrado. Quando alguém dá bônus a você, essa pessoa aparece aqui."
L["No buffs given unprompted. When the prompt buffs somebody who did not buff you first, it is listed here."] = "Nenhum bônus dado por conta própria. Quando o lembrete dá bônus a alguém que não deu bônus a você antes, isso aparece aqui."
L["Nothing is recorded while Manners is switched off."] = "Nada é registrado enquanto o Manners está desativado."
L["Nothing is recorded while the prompt has nothing to cast on this character."] = "Nada é registrado enquanto o lembrete não tem nada para lançar neste personagem."
L["Favours are not recorded while \"People who buff me\" is off, on the Who to buff tab."] = "Os favores não são registrados enquanto \"Quem me dá bônus\" está desativado, na aba Quem recebe bônus."
L["Clear"] = "Limpar"
L["Click again to clear"] = "Clique de novo para limpar"
L["Empties the list, and today's count with it. Favours you still owe stay, and the all-time totals are kept."] = "Esvazia a lista, e a contagem de hoje junto. Os favores que você ainda deve continuam, e os totais desde o início são mantidos."
L["Still owed"] = "Pendente"
L["Returned"] = "Retribuído"
L["Let go"] = "Dispensado"
L["Gave"] = "Doado"
L["with %s"] = "com %s"
L["the time to return it ran out"] = "o tempo para retribuir acabou"
L["nothing you cast is any use to them"] = "nada que você lança serve para essa pessoa"
L["forgotten at a logout or reload"] = "esquecido ao sair ou recarregar a interface"
L["you put them on your never-offer list"] = "você pôs essa pessoa na sua lista de nunca oferecer"
L["%s, in your group"] = "%s, no seu grupo"
L["%s, to a stranger"] = "%s, a um desconhecido"
L["%s, to %d who needed it"] = "%s, a %d que precisavam"
L["a buff"] = "um bônus"
L["Buffed you with %s, %s."] = "Deu %s a você, %s."
L["They buffed you %d times; one buff back repays all of it."] = "Deu bônus a você %d vezes; um bônus de volta retribui tudo."
L["Still owed. The prompt offers them until you return it or the time runs out."] = "Pendente. Essa pessoa aparece no lembrete até você retribuir ou o tempo acabar."
L["Still owed. What you cast reaches only your own party, so the prompt offers them only while they are in it."] = "Pendente. O que você lança só alcança seu próprio grupo, então essa pessoa só aparece no lembrete enquanto estiver nele."
L["Still owed. What you cast reaches only your own party -- in a raid, your own subgroup -- so the prompt offers them only while they are in it."] = "Pendente. O que você lança só alcança seu próprio grupo -- numa raide, seu próprio subgrupo -- então essa pessoa só aparece no lembrete enquanto estiver nele."
L["You returned it %s later."] = "Você retribuiu %s depois."
L["You returned it %s later, with %s."] = "Você retribuiu %s depois, com %s."
L["Let go: the time to return it ran out before you did."] = "Dispensado: o tempo para retribuir acabou antes que você retribuísse."
L["Let go: nothing you can cast is any use to them."] = "Dispensado: nada que você possa lançar serve para essa pessoa."
L["Let go: \"%s\" (%s tab, under %s) is off, so it was forgotten when you logged out or reloaded."] = "Dispensado: \"%s\" (aba %s, em %s) está desativado, então o favor foi esquecido quando você saiu ou recarregou a interface."
L["Keep favours through a /reload"] = "Manter os favores após um /reload"
L["When to offer"] = "Quando oferecer"
L["Let go: you put them on your never-offer list."] = "Dispensado: você pôs essa pessoa na sua lista de nunca oferecer."
L["Still owed, but Manners is switched off, so the prompt will not offer them."] = "Pendente, mas o Manners está desativado, então essa pessoa não vai aparecer no lembrete."
L["Still owed, but the prompt is not offering favours while \"People who buff me\" is off."] = "Pendente, mas o lembrete não mostra favores a retribuir enquanto \"Quem me dá bônus\" estiver desativado."
L["Still owed, but there is nothing on this character the prompt can cast."] = "Pendente, mas não há nada neste personagem que o lembrete possa lançar."
L["Still owed. They are flagged for PvP, and buffing them would flag you, so the prompt offers them only if their flag drops before the time to return it runs out."] = "Pendente. Essa pessoa está com JxJ ativado, e dar bônus a ela ativaria o seu, então ela só aparece no lembrete se o JxJ dela terminar antes de o tempo para retribuir acabar."
L["Still owed. The prompt is snoozed until %s, so it offers them only if the snooze ends before the time to return it runs out."] = "Pendente. O lembrete está em soneca até %s, então essa pessoa só aparece nele se a soneca terminar antes de o tempo para retribuir acabar."
L["Still owed. The prompt stays away while you are mounted, and offers them once you get off, until the time to return it runs out."] = "Pendente. O lembrete some enquanto você está montado, e essa pessoa aparece nele quando você desmontar, até o tempo para retribuir acabar."
L["Still owed. What you cast reaches only your own party, so the prompt offers them only while they are in it, and it is snoozed until %s, so only if time is left then."] = "Pendente. O que você lança só alcança seu próprio grupo, então essa pessoa só aparece no lembrete enquanto estiver nele, e o lembrete está em soneca até %s, então só se ainda restar tempo nessa hora."
L["Still owed. What you cast reaches only your own party -- in a raid, your own subgroup -- so the prompt offers them only while they are in it, and it is snoozed until %s, so only if time is left then."] = "Pendente. O que você lança só alcança seu próprio grupo -- numa raide, seu próprio subgrupo -- então essa pessoa só aparece no lembrete enquanto estiver nele, e o lembrete está em soneca até %s, então só se ainda restar tempo nessa hora."
L["Still owed. What you cast reaches only your own party, so the prompt offers them only while they are in it, once you are no longer mounted, until the time runs out."] = "Pendente. O que você lança só alcança seu próprio grupo, então essa pessoa só aparece no lembrete enquanto estiver nele, depois que você desmontar, até o tempo acabar."
L["Still owed. What you cast reaches only your own party -- in a raid, your own subgroup -- so the prompt offers them only while they are in it, once you are no longer mounted, until the time runs out."] = "Pendente. O que você lança só alcança seu próprio grupo -- numa raide, seu próprio subgrupo -- então essa pessoa só aparece no lembrete enquanto estiver nele, depois que você desmontar, até o tempo acabar."
L["You buffed them with %s, %s."] = "Você deu %s a essa pessoa, %s."
L["They were in your group and had not buffed you."] = "Estava no seu grupo e não tinha dado bônus a você."
L["They were not in your group and had not buffed you."] = "Não estava no seu grupo e não tinha dado bônus a você."
L["They asked for it in chat."] = "Pediu o bônus no bate-papo."
L["One cast gave it to %d who needed it in their party or class, and counts as one buff given."] = "Um só lançamento deu o bônus a %d que precisavam dele no grupo ou na classe, e conta como um bônus dado."
L["just now"] = "agora mesmo"
L["%d min ago"] = "há %d min"
