L["Show a second line"] = "Mostrar uma segunda linha"
L["Needs a prompt at least %d pixels tall."] = "Precisa de um lembrete com pelo menos %d pixels de altura."
L["Icon and waiting list"] = "Ícone e fila"
L["Show spell icon"] = "Mostrar ícone do feitiço"
L["Icon size"] = "Tamanho do ícone"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "Fica dentro do lembrete -- deixe-o mais alto ou mais largo antes para ter um ícone maior."
L["This look sizes the icon from the prompt's height: %d at %d high. Make the prompt taller for a bigger icon."] = "Este visual dimensiona o ícone pela altura do lembrete: %d com %d de altura. Deixe o lembrete mais alto para ter um ícone maior."
